import fs from 'fs';
import path from 'path';
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const envPath = path.resolve(__dirname, '../.env');
const envLocalPath = path.resolve(__dirname, '../.env.local');

// Load environment variables
if (fs.existsSync(envPath)) dotenv.config({ path: envPath });
if (fs.existsSync(envLocalPath)) dotenv.config({ path: envLocalPath, override: true });

const template = `// Import the scripts for the messaging service worker
importScripts('https://www.gstatic.com/firebasejs/10.9.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.9.0/firebase-messaging-compat.js');

// Generated dynamically - DO NOT EDIT MANUALLY
firebase.initializeApp({
    apiKey: "${process.env.VITE_FIREBASE_API_KEY || ''}",
    authDomain: "${process.env.VITE_FIREBASE_AUTH_DOMAIN || ''}",
    projectId: "${process.env.VITE_FIREBASE_PROJECT_ID || ''}",
    storageBucket: "${process.env.VITE_FIREBASE_STORAGE_BUCKET || ''}",
    messagingSenderId: "${process.env.VITE_FIREBASE_MESSAGING_SENDER_ID || ''}",
    appId: "${process.env.VITE_FIREBASE_APP_ID || ''}"
});

const messaging = firebase.messaging();

messaging.onBackgroundMessage((payload) => {
    console.log('[firebase-messaging-sw.js] Received background message ', payload);
    
    const notificationTitle = payload.notification.title;
    const notificationOptions = {
        body: payload.notification.body,
        icon: '/logo.svg',
        data: payload.data
    };

    self.registration.showNotification(notificationTitle, notificationOptions);
});
`;

const swPath = path.resolve(__dirname, '../public/firebase-messaging-sw.js');
fs.writeFileSync(swPath, template);

console.log('✅ firebase-messaging-sw.js generated successfully with environment variables.');

import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './hooks/useAuth';
import { useAppConfig } from './context/AppConfigContext';
import Teaser from './components/Teaser/Teaser';
import AdminLogin from './modules/admin/AdminLogin';
import AdminDashboard from './modules/admin/AdminDashboard';
import UserDashboard from './modules/user/UserDashboard';
import JoinInvite from './modules/auth/JoinInvite';
import WelcomeScreen from './modules/auth/WelcomeScreen';
import LoadingScreen from './components/ui/LoadingScreen/LoadingScreen';
import { PastelToastProvider } from './components/ui/PastelToast/PastelToast';
import { BingoProvider } from './context/BingoContext';
import './App.css';
import VersionBadge from './components/ui/VersionBadge/VersionBadge';

/**
 * App — top-level routing (React Router)
 *
 * Routes:
 *   /             → Teaser (unauthenticated) | redirect to /app (authenticated)
 *   /join         → JoinInvite (public, partner onboarding)
 *   /admin/login  → AdminLogin (public)
 *   /admin/*      → AdminDashboard (admin only) | AdminLogin (fallback)
 *   /app/*        → UserDashboard (authenticated) | redirect to /join (fallback)
 *   /*            → Teaser (fallback)
 */
export default function App() {
  const { 
    isAdmin, 
    isAuthenticated, 
    isLoading, 
    welcomeSeen,
    teaserCompleted
  } = useAuth();

  // While resolving Firebase auth, show nothing (prevents flash)
  if (isLoading) return <LoadingScreen />;

  return (
    <PastelToastProvider>
        <Routes>
        {/* Raíz Dispatcher: Redirige según el estado de la sesión y el progreso */}
        <Route path="/" element={
          !isAuthenticated 
            ? <Navigate to="/join" replace /> 
            : isAdmin 
              ? <Navigate to="/admin" replace />
              : (welcomeSeen === null || teaserCompleted === null)
                ? <LoadingScreen />
                : teaserCompleted === false
                  ? <Navigate to="/teaser" replace />
                  : welcomeSeen === false
                    ? <Navigate to="/welcome" replace />
                    : <Navigate to="/app" replace />
        } />

        {/* Flujo de invitación (público) */}
        <Route path="/join" element={
          isAuthenticated 
            ? <Navigate to="/" replace />
            : <><JoinInvite /><VersionBadge /></>
        } />

        {/* Teaser (protegido por estado) — solo si no ha sido completado */}
        <Route path="/teaser" element={
          !isAuthenticated 
            ? <Navigate to="/join" replace />
            : isAdmin
              ? <Navigate to="/admin" replace />
              : teaserCompleted === true
                ? <Navigate to="/" replace />
                : <><Teaser /><VersionBadge /></>
        } />

        {/* Pantalla de Bienvenida (protegida) — accesible después del Teaser */}
        <Route path="/welcome" element={
          !isAuthenticated 
            ? <Navigate to="/join" replace />
            : isAdmin
              ? <Navigate to="/admin" replace />
              : teaserCompleted === false
                ? <Navigate to="/teaser" replace />
                : welcomeSeen === true
                  ? <Navigate to="/app" replace />
                  : <><WelcomeScreen /><VersionBadge /></>
        } />

        {/* Admin: login público + dashboard protegido */}
        <Route path="/admin/login" element={
          isAdmin
            ? <Navigate to="/admin" replace />
            : <><AdminLogin /><VersionBadge /></>
        } />
        <Route path="/admin/*" element={
          isAdmin
            ? <BingoProvider><AdminDashboard /><VersionBadge /></BingoProvider>
            : <><AdminLogin /><VersionBadge /></>
        } />

        {/* Dashboard de usuario (protegido) */}
        <Route path="/app/*" element={
          !isAuthenticated
            ? <Navigate to="/join" replace />
            : isAdmin
              ? <Navigate to="/admin" replace />
              : teaserCompleted === false
                ? <Navigate to="/teaser" replace />
                : welcomeSeen === false
                  ? <Navigate to="/welcome" replace />
                  : <BingoProvider><UserDashboard /><VersionBadge /></BingoProvider>
        } />

        {/* Fallback: redirigir a raíz para que el dispatcher decida */}
        <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
    </PastelToastProvider>
  );
}

import { motion } from 'framer-motion';
import { MEMORY_TAGS } from '../../config/constants';
import styles from './BingoStartModal.module.css';

export default function BingoStartModal({ bingoItem, onClose, onStartCita, defaultMinPhotos = 3 }) {
    const minPhotosVal = bingoItem.minPhotos || defaultMinPhotos;

    const handleStartCita = () => {
        if (onStartCita) {
            onStartCita({
                type: 'bingo',
                categoryId: bingoItem.id,
                bingoLabel: `${bingoItem.emoji} ${bingoItem.title}`,
                minPhotos: minPhotosVal,
                description: bingoItem.description,
                tags: (bingoItem.suggestedTags || []).map(t => typeof t === 'string' ? t : t.value)
            });
        }
    };

    return (
        <div className={styles.overlay} onClick={onClose}>
            <motion.div
                className={styles.card}
                onClick={e => e.stopPropagation()}
                initial={{ scale: 0.9, opacity: 0, y: 30 }}
                animate={{ scale: 1, opacity: 1, y: 0 }}
                exit={{ scale: 0.9, opacity: 0, y: 30 }}
                transition={{ type: 'spring', damping: 15, stiffness: 120 }}
            >
                <div className={styles.header}>
                    <button className={styles.closeBtn} onClick={onClose}>
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>

                <div className={styles.content}>
                    <div className={styles.iconWrapper}>
                        <span className={bingoItem.emoji === 'favorite' || bingoItem.emoji === 'help_outline' ? `${styles.emoji} material-symbols-outlined ${styles.materialEmoji}` : styles.emoji}>
                            {bingoItem.emoji}
                        </span>
                    </div>
                    <h2 className={styles.title}>{bingoItem.title}</h2>

                    <div className={styles.rulesBox}>
                        <p className={styles.description}>
                            {bingoItem.description || 'Cumple con este reto tomando fotos para documentar el momento.'}
                        </p>

                        <div className={styles.reqs}>
                            <span className="material-symbols-outlined" style={{ fontSize: '1.25rem' }}>photo_camera</span>
                            <span>Mínimo {minPhotosVal} fotos</span>
                        </div>

                        {bingoItem.suggestedTags?.length > 0 && (
                            <div className={styles.tagsContainer}>
                                {bingoItem.suggestedTags.map(tag => {
                                    const tagValue = typeof tag === 'string' ? tag : tag.value;
                                    const tagLabel = typeof tag === 'string' 
                                        ? (Object.values(MEMORY_TAGS).find(t => t.value === tag)?.label || tag)
                                        : tag.label;
                                    return (
                                        <span key={tagValue} className={styles.tagPill}>
                                            {tagLabel}
                                        </span>
                                    );
                                })}
                            </div>
                        )}
                    </div>

                    <p className={styles.hint}>
                        Inicia la cita para marcar esta casilla.
                    </p>

                    <button className={styles.startBtn} onClick={handleStartCita}>
                        <span className="material-symbols-outlined">play_arrow</span>
                        ¡Comenzar Cita!
                    </button>
                </div>
            </motion.div>
        </div>
    );
}

