                </div>
            </motion.div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import KawaiiInput from '../ui/KawaiiInput/KawaiiInput';
import PlacePickerBottomSheet from './PlacePickerBottomSheet';
import { reverseGeocode } from '../../services/mapService';
import Carousel from '../ui/Carousel/Carousel';
import { useBingo } from '../../hooks/useBingo';
import { useAppConfig } from '../../context/AppConfigContext';
import styles from './PendingDateForm.module.css';

export default function PendingDateForm({ pendingDate, onClose, onSave, onAutoSave, defaultPlaces }) {
    const { availableTags } = useBingo();
    const { memoryTags } = useAppConfig();
    // Determine initial location from metadata if available
    const [selectedPlaceId, setSelectedPlaceId] = useState(() => 
        pendingDate?.coordinates ? 'custom_map' : ''
    );
    const [customLocation, setCustomLocation] = useState(pendingDate?.coordinates || null);
    const [customPlaceName, setCustomPlaceName] = useState(pendingDate?.placeName || '');
    const [isPlacePickerOpen, setIsPlacePickerOpen] = useState(false);
    const [title, setTitle] = useState(pendingDate?.title || '');
    const [eventDate, setEventDate] = useState(() => {
        try {
            // Priority: eventDate from form > rawDate from EXIF > createdAt
            const dateToUse = pendingDate?.eventDate || pendingDate?.rawDate || pendingDate?.createdAt;
            if (dateToUse) {
                const d = new Date(dateToUse);
                if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
            }
        } catch (e) {
            console.error('Error parsing date:', e);
        }
        return new Date().toISOString().split('T')[0];
    });
    const [selectedTags, setSelectedTags] = useState(pendingDate?.tags || pendingDate?.suggestedTags || pendingDate?.context?.tags || []);
    const [comments, setComments] = useState(pendingDate?.description || pendingDate?.comments || pendingDate?.context?.description || '');
    const [locationError, setLocationError] = useState(false);
    const [showCarousel, setShowCarousel] = useState(false);

    // Auto-save debounced
    useEffect(() => {
        if (!onAutoSave) return;

        const timer = setTimeout(() => {
            // Only save if something looks "touched" or already exists
            const hasData = title || selectedTags.length > 0 || comments || selectedPlaceId;
            if (hasData) {
                onAutoSave({
                    id: pendingDate.id,
                    title,
                    eventDate,
                    tags: selectedTags,
                    comments,
                    placeId: selectedPlaceId,
                    placeName: selectedPlaceId === 'custom_map' ? customPlaceName : null,
                    customLocation
                });
            }
        }, 800);

        return () => clearTimeout(timer);
    }, [title, eventDate, selectedTags, comments, selectedPlaceId, customLocation, customPlaceName, onAutoSave, pendingDate.id]);

    // Auto-resolve place name if coordinates exist but name doesn't
    useEffect(() => {
        if (customLocation && !customPlaceName) {
            reverseGeocode(customLocation.lat, customLocation.lng)
                .then(res => {
                    if (res && res.name) {
                        setCustomPlaceName(res.name);
                    }
                })
                .catch(err => console.warn('[PendingDateForm] Failed to auto-resolve name:', err));
        }
    }, [customLocation, customPlaceName]);

    const toggleTag = (tag) => {
        setSelectedTags(prev =>
            prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
        );
    };

    if (!pendingDate) return null;

    const handleSave = () => {
        if (!selectedPlaceId && !customLocation) {
            setLocationError(true);
            return;
        }

        onSave({
            ...pendingDate,
            title: title || 'Recuerdo sin título',
            eventDate: eventDate,
            placeId: selectedPlaceId,
            placeName: selectedPlaceId === 'custom_map' ? customPlaceName : null,
            customLocation: customLocation,
            tags: selectedTags,
            comments: comments
        });
    };

    return (
        <motion.div
            className={styles.overlay}
            initial={{ opacity: 0, scale: 1.05 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.05 }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
        >
            <div className={styles.orbTopLeft}></div>

            <div className={styles.scrollArea}>
                <div className={styles.contentWrapper}>
                    <div className={styles.header}>
                        <button className={styles.backBtn} onClick={onClose}>
                            <span className="material-symbols-outlined">arrow_back</span>
                        </button>
                        <h2 className={styles.title}>Clasificar cita</h2>
                    </div>

                    <div className={styles.heroSection} onClick={() => setShowCarousel(true)}>
                        <img src={pendingDate.coverPhoto} alt="Cover" className={styles.heroImg} />
                        <div className={styles.heroBadge}>
                            <span className="material-symbols-outlined" style={{fontSize:'12px', verticalAlign:'middle', marginRight:'4px'}}>photo_library</span>
                            {pendingDate.photos?.length || 0} fotos
                        </div>
                        <div className={styles.heroOverlay}>
                            <span className="material-symbols-outlined">zoom_in</span>
                            Toca para ver todas
                        </div>
                    </div>

                    <AnimatePresence>
                        {showCarousel && (
                            <motion.div 
                                className={styles.carouselOverlay}
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                exit={{ opacity: 0 }}
                            >
                                <Carousel 
                                    photos={pendingDate.photos?.map(p => p.objectUrl) || [pendingDate.coverPhoto]} 
                                    onBack={() => setShowCarousel(false)} 
                                />
                            </motion.div>
                        )}
                    </AnimatePresence>

                    <div className={styles.formGroup}>
                        <KawaiiInput
                            label="¿Qué título le pondrías?"
                            iconLeft="edit"
                            placeholder="Ej. Nuestra cena especial"
                            value={title}
                            onChange={e => setTitle(e.target.value)}
                        />
                    </div>

                    <div className={styles.formGroup}>
                        <KawaiiInput
                            type="date"
                            label="¿Cuándo fue esta magia?"
                            iconLeft="calendar_today"
                            value={eventDate}
                            onChange={e => setEventDate(e.target.value)}
                        />
                    </div>

                    <div className={styles.formGroup}>
                        <label className={styles.label}>¿Dónde fue?</label>
                        {selectedPlaceId === 'custom_map' && customLocation ? (
                            <div className={styles.confirmedLocationBadge}>
                                <div className={styles.confirmedLeft}>
                                    <div className={styles.checkCircle}>
                                        <span className="material-symbols-outlined">check</span>
                                    </div>
                                    <div className={styles.locationMeta}>
                                        <span className={styles.locationLabel}>
                                            {customPlaceName || 'Ubicación de la foto'}
                                        </span>
                                        <span className={styles.locationCoords}>
                                            {customLocation.lat.toFixed(4)}, {customLocation.lng.toFixed(4)}
                                        </span>
                                    </div>
                                </div>
                                <button
                                    className={styles.editLocationBtn}
                                    onClick={() => setIsPlacePickerOpen(true)}
                                >
                                    <span className="material-symbols-outlined">edit_location_alt</span>
                                    Cambiar
                                </button>
                            </div>
                        ) : (
                            <KawaiiInput
                                type="select"
                                label=""
                                iconLeft="location_on"
                                placeholder="Toca aquí para elegir el lugar"
                                value={selectedPlaceId}
                                onClick={() => {
                                    setLocationError(false);
                                    setIsPlacePickerOpen(true);
                                }}
                                error={locationError ? "Por favor selecciona una ubicación para continuar" : null}
                                options={[
                                    ...(defaultPlaces?.map(p => ({ value: p.id, label: `${p.emoji} ${p.name}` })) || []),
                                    ...(customLocation ? [{ value: 'custom_map', label: '📍 Ubicación elegida en mapa' }] : [])
                                ]}
                            />
                        )}
                    </div>

                    <div className={styles.formGroup}>
                        <label className={styles.label}>Etiquetas</label>
                        <div className={styles.tagsContainer}>
                            {(() => {
                                // Merge global config tags with dynamic Bingo tags
                                const allTags = [...(memoryTags || [])];
                                (availableTags || []).forEach(tag => {
                                    if (!allTags.find(t => t.value === tag.value)) {
                                        allTags.push(tag);
                                    }
                                });

                                return allTags.map(({ value, label }) => (
                                    <button
                                        key={value}
                                        className={`${styles.tagBtn} ${selectedTags.includes(value) ? styles.tagBtnActive : ''}`}
                                        onClick={() => toggleTag(value)}
                                    >
                                        {label}
                                    </button>
                                ));
                            })()}
                        </div>
                    </div>

                    <div className={styles.formGroup}>
                        <KawaiiInput
                            type="textarea"
                            label={
                                <>
                                    Alguna nota especial
                                    <span className={styles.optionalBadge}>(Opcional)</span>
                                </>
                            }
                            placeholder="Escribe aquí algún chiste local o algo que no quieras olvidar..."
                            value={comments}
                            onChange={e => setComments(e.target.value)}
                            rows={3}
                        />
                    </div>

                    {(pendingDate.isFromBingo || pendingDate.context?.type === 'bingo') && (
                        <div className={styles.bingoBanner}>
                            <span className="material-symbols-outlined">casino</span>
                            ¡Esta cita desbloquea un logro del Bingo! 🎰
                        </div>
                    )}
                </div>
            </div>

            <div className={styles.footer}>
                <button
                    className={styles.saveBtn}
                    onClick={handleSave}
                    disabled={!selectedPlaceId && !customLocation}
                >
                    <span>Guardar este recuerdo</span>
                    <span className="material-symbols-outlined">favorite</span>
                </button>
            </div>

            <PlacePickerBottomSheet
                isOpen={isPlacePickerOpen}
                onClose={() => setIsPlacePickerOpen(false)}
                places={defaultPlaces || []}
                onSelectPlace={(placeId) => {
                    setSelectedPlaceId(placeId);
                    setCustomLocation(null);
                }}
                onLocationSelected={(locationData, placeId, placeName) => {
                    if (placeId) {
                        setSelectedPlaceId(placeId);
                        setCustomLocation(null);
                        setCustomPlaceName('');
                    } else {
                        setCustomLocation(locationData);
                        setCustomPlaceName(placeName || '');
                        setSelectedPlaceId('custom_map');
                    }
                }}
                initialCoordinates={pendingDate.coordinates}
            />
        </motion.div>
    );
}

import React, { useRef, useState, useEffect } from 'react';
import { motion, AnimatePresence, useMotionValue, useTransform, animate } from 'framer-motion';
import { toast } from './../../components/ui/PastelToast/PastelToast';
import styles from './PendingDatesList.module.css';

/**
 * Individual Card component with relative gesture logic
 */
function PendingDateCard({ pd, idx, onSelectDate, onRemove, onRestore }) {
    const isUploading = pd.status === 'uploading';
    const isFailed = pd.status === 'failed';
    const containerRef = useRef(null);
    const [containerWidth, setContainerWidth] = useState(0);
    const x = useMotionValue(0);

    // Colores tipo "Pastel Red" progresivos e intensos
    const backgroundColor = useTransform(
        x, 
        [-150, -60, 0], 
        ['#ff6b81', '#ffecf0', '#ffffff'] // De blanco a rosa claro y termina en un rojo pastel potente
    );
    const deleteOpacity = useTransform(x, [-80, -20, 0], [1, 0.4, 0]);
    const iconScale = useTransform(x, [-80, -30, 0], [1.3, 0.9, 0.4]);

    // Better date parsing & 24hr format conversion
    // Priority: user-selected eventDate > original metadata date
    const finalDate = pd.eventDate || pd.originalDate;
    const parts = typeof finalDate === 'string' ? finalDate.split(', ') : [];

    let displayDate = 'Sin fecha';
    let displayTime = '';

    if (pd.eventDate) {
        // If it's a YYYY-MM-DD from the form
        const d = new Date(pd.eventDate);
        if (!isNaN(d.getTime())) {
            displayDate = d.toLocaleDateString('es-MX', { day: 'numeric', month: 'short', year: 'numeric' });
        }
    } else if (parts.length >= 2) {
        displayDate = parts[1];
        displayTime = parts[2] || '';
    }

    // Convert "06:32 p" or "06:32 p.m." to "18:32"
    if (displayTime) {
        const timeMatch = displayTime.match(/(\d{1,2}):(\d{2})\s*([ap])/i);
        if (timeMatch) {
            let [_, hours, minutes, ampm] = timeMatch;
            hours = parseInt(hours, 10);
            if (ampm.toLowerCase().startsWith('p') && hours < 12) hours += 12;
            if (ampm.toLowerCase().startsWith('a') && hours === 12) hours = 0;
            displayTime = `${hours.toString().padStart(2, '0')}:${minutes}`;
        } else {
            // Clean up if it doesn't match the regex but has suffix
            displayTime = displayTime.replace(/\s*[ap]\.?m?\.?/gi, '').trim();
        }
    }

    const maxDrag = containerWidth ? -(containerWidth * 0.9) : -300; 

    // Centrar automáticamente cuando se monta para asegurar estado limpio
    useEffect(() => {
        x.set(0);
    }, [x]);

    // Calcular ancho inicial y al redimensionar
    useEffect(() => {
        const updateWidth = () => {
            if (containerRef.current) setContainerWidth(containerRef.current.offsetWidth);
        };
        updateWidth();
        window.addEventListener('resize', updateWidth);
        return () => window.removeEventListener('resize', updateWidth);
    }, []);

    const handleDelete = () => {
        if (onRemove) {
            // Pequeña vibración visual antes de borrar
            animate(x, -containerWidth * 0.8, { duration: 0.3 });

            setTimeout(() => {
                onRemove(pd.id);
                toast.info('Recuerdo quitado de la lista ✨', 'Toca para DESHACER ↺', {
                    id: `delete-${pd.id}`, // Individual toast for each deletion
                    duration: 6000,
                    onClick: () => {
                        if (onRestore) {
                            onRestore(pd);
                            toast.success('¡Recuperado!', 'El recuerdo volvió a su lugar', { id: `delete-${pd.id}` });
                        }
                    }
                });
            }, 300);
        }
    };

    return (
        <motion.div
            ref={containerRef}
            layout
            initial={{ opacity: 0, y: 15 }}
            animate={{ 
                opacity: pd.isHidden ? 0 : 1, 
                y: 0,
                height: pd.isHidden ? 0 : 'auto',
                minHeight: pd.isHidden ? 0 : 'unset',
                marginBottom: pd.isHidden ? 0 : '1.125rem',
                scale: pd.isHidden ? 0.9 : 1
            }}
            exit={{ 
                x: 200, 
                opacity: 0, 
                scale: 0.9,
                transition: { duration: 0.4, ease: [0.32, 0, 0.67, 0] } 
            }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
            className={styles.listItemContainer}
        >
            <motion.div 
                className={styles.deleteBackground}
                style={{ opacity: deleteOpacity }}
            >
                <motion.span 
                    className="material-symbols-outlined"
                    style={{ scale: iconScale }}
                >
                    delete
                </motion.span>
                <span className={styles.deleteLabel}>Eliminar</span>
            </motion.div>

            <motion.div
                style={{ x, background: backgroundColor }}
                drag={!isUploading ? "x" : false}
                dragConstraints={{ left: maxDrag, right: 0 }}
                dragElastic={0.15}
                dragMomentum={false}
                animate={{ 
                    x: pd.isHidden ? -containerWidth : 0
                }}
                transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                onDragEnd={(e, info) => {
                    const currentX = x.get();
                    const threshold = containerWidth * 0.25 || 80; 
                    const isFlick = info.velocity.x < -500;

                    if (currentX < -threshold || isFlick) {
                        handleDelete();
                    } else {
                        animate(x, 0, { type: 'spring', damping: 25, stiffness: 200 });
                    }
                }}
                className={`${styles.listItem} ${isUploading ? styles.listItemUploading : ''} ${isFailed ? styles.listItemFailed : ''}`}
            >
                <div 
                    className={styles.itemContent}
                    onClick={() => !isUploading && onSelectDate(pd)}
                >
                    <div className={styles.thumbWrapper}>
                        {pd.photos?.[0]?.objectUrl ? (
                            <img src={pd.photos[0].objectUrl} alt="Recuerdo" className={styles.thumb} />
                        ) : (
                            <div className={styles.thumbFallback}>
                                <span className="material-symbols-outlined">photo_camera</span>
                            </div>
                        )}
                        {isUploading && (
                            <div className={styles.statusOverlay}><div className={styles.miniSpinner}></div></div>
                        )}
                        {isFailed && (
                            <div className={`${styles.statusOverlay} ${styles.failedOverlay}`}>
                                <span className="material-symbols-outlined">error</span>
                            </div>
                        )}
                    </div>

                    <div className={styles.info}>
                        <span className={styles.date}>
                            {pd.title ? (
                                <strong className={styles.titleText}>{pd.title}</strong>
                            ) : (
                                displayDate
                            )}
                        </span>
                        <div className={styles.detailsRow}>
                            <span className={styles.photoCount}>
                                {pd.title ? displayDate : (
                                    <>
                                        <span className="material-symbols-outlined">photo_library</span>
                                        {pd.photos?.length || 0} fotos
                                    </>
                                )}
                            </span>
                            {displayTime && <span className={styles.timeTag}>{displayTime}</span>}
                            {pd.title && (
                                <span className={styles.photoCountMini}>
                                    <span className="material-symbols-outlined" style={{fontSize: '12px'}}>photo_library</span>
                                    {pd.photos?.length || 0}
                                </span>
                            )}
                        </div>
                    </div>
