import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import KawaiiInput from '../ui/KawaiiInput/KawaiiInput';
import Button from '../ui/Button/Button';
import MapLocationPicker from './MapLocationPicker';
import styles from './PlacePickerBottomSheet.module.css';

export default function PlacePickerBottomSheet({
    isOpen,
    onClose,
    places,
    onSelectPlace,
    onLocationSelected, // Gets raw coordinates/data from map
    initialCoordinates // from pendingDate if any
}) {
    const [searchTerm, setSearchTerm] = useState('');
    const [isMapOpen, setIsMapOpen] = useState(false);
    const [selectedId, setSelectedId] = useState('');
    const [mapPreviewCoords, setMapPreviewCoords] = useState(null);

    // Reset map state when closing the bottom sheet
    useEffect(() => {
        if (!isOpen) {
            setIsMapOpen(false);
            setSearchTerm('');
            setSelectedId('');
            setMapPreviewCoords(null);
        }
    }, [isOpen]);

    const filteredPlaces = places.filter(p =>
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.tags?.some(t => t.toLowerCase().includes(searchTerm.toLowerCase()))
    );

    const handleMapConfirm = (locationData, placeId, placeName) => {
        onLocationSelected(locationData, placeId, placeName);
        setIsMapOpen(false);
        onClose();
    };

    return (
        <motion.div
            className={styles.overlay}
            initial={false}
            animate={{
                opacity: isOpen ? 1 : 0,
                pointerEvents: isOpen ? 'auto' : 'none'
            }}
            transition={{ duration: 0.2 }}
            onClick={onClose}
        >
            <motion.div
                className={styles.bottomSheet}
                initial={false}
                animate={{ y: isOpen ? 0 : '100%' }}
                transition={{ type: 'spring', damping: 25, stiffness: 250 }}
                onClick={e => e.stopPropagation()}
            >
                <div style={{ position: 'relative', width: '100%', height: '100%' }}>
                    {/* Map View */}
                    <div style={{
                        position: 'absolute', inset: 0,
                        opacity: isMapOpen ? 1 : 0,
                        pointerEvents: isMapOpen ? 'auto' : 'none',
                        transition: 'opacity 0.2s',
                        display: 'flex', flexDirection: 'column'
                    }}>
                        <MapLocationPicker
                            onConfirm={handleMapConfirm}
                            onCancel={() => {
                                setIsMapOpen(false);
                                setMapPreviewCoords(null);
                            }}
                            initialCoordinates={mapPreviewCoords || initialCoordinates}
                        />
                    </div>

                    {/* List View */}
                    <div style={{
                        position: 'absolute', inset: 0,
                        opacity: isMapOpen ? 0 : 1,
                        pointerEvents: isMapOpen ? 'none' : 'auto',
                        transition: 'opacity 0.2s',
                        display: 'flex', flexDirection: 'column'
                    }}>
                        <div className={styles.header}>
                            <div className={styles.handle} />
                            <h3>Selecciona un lugar</h3>
                            <button type="button" className={styles.closeBtn} onClick={onClose}>
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </div>

                        <div className={styles.searchSection}>
                            <KawaiiInput
                                type="search"
                                placeholder="Buscar lugar..."
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                onClear={() => setSearchTerm('')}
                            />
                            <Button
                                variant="secondary"
                                className={styles.mapBtn}
                                onClick={() => setIsMapOpen(true)}
                            >
                                <span className={`material-symbols-outlined ${styles.mapIcon}`}>map</span>
                                Elegir en el mapa
                            </Button>
                        </div>

                        <div className={styles.placesList}>
                            {filteredPlaces.length > 0 ? (
                                filteredPlaces.map(place => (
                                    <div
                                        key={place.id}
                                        className={`${styles.placeItem} ${selectedId === place.id ? styles.placeItemActive : ''}`}
                                        onClick={() => {
                                            setSelectedId(place.id);
                                            // Focus map on this place if coords exist
                                            if (place.lat && place.lng) {
                                                setMapPreviewCoords({ lat: place.lat, lng: place.lng });
                                                setIsMapOpen(true);
                                            }
                                        }}
                                        onDoubleClick={() => {
                                            onSelectPlace(place.id);
                                            onClose();
                                        }}
                                        role="button"
                                        aria-pressed={selectedId === place.id}
                                        tabIndex={0}
                                    >
                                        <div className={styles.placeEmoji}>{place.emoji}</div>
                                        <div className={styles.placeInfo}>
                                            <span className={styles.placeName}>{place.name}</span>
                                            {place.tags && place.tags.length > 0 && (
                                                <span className={styles.placeTags}>
                                                    {place.tags.join(' • ')}
                                                </span>
                                            )}
                                        </div>
                                        {selectedId === place.id && (
                                            <span className={`material-symbols-outlined ${styles.checkIcon}`}>check_circle</span>
                                        )}
                                    </div>
                                ))
                            ) : (
                                <div className={styles.emptyState}>
                                    <span className={styles.emptyIcon}>🙈</span>
                                    <p>No encontramos ese lugar.</p>
                                </div>
                            )}
                        </div>

                        {/* Footer with Selection Button */}
                        <div className={styles.footer}>
                            <Button
                                className={styles.confirmBtn}
                                onClick={() => {
                                    if (selectedId) {
                                        onSelectPlace(selectedId);
                                        onClose();
                                    }
                                }}
                                disabled={!selectedId}
                            >
                                Seleccionar este lugar
                                <span className="material-symbols-outlined">done_all</span>
                            </Button>
                        </div>
                    </div>
                </div>
            </motion.div>
        </motion.div>
    );
}

import { useState, useEffect, useRef, useMemo } from 'react';
import { motion, useReducedMotion } from 'framer-motion';
import './Countdown.css';

function getTimeUntil(targetDate) {
    const diff = targetDate - Date.now();
    if (diff <= 0) return { days: 0, hours: 0, minutes: 0, seconds: 0 };
    return {
        days: Math.floor(diff / (1000 * 60 * 60 * 24)),
        hours: Math.floor((diff / (1000 * 60 * 60)) % 24),
        minutes: Math.floor((diff / (1000 * 60)) % 60),
        seconds: Math.floor((diff / 1000) % 60),
    };
}

// April 4, 2026, 00:00:00 CST (UTC-6) by default
const DEFAULT_TARGET = new Date('2026-04-04T00:00:00-06:00');

const FlipUnit = ({ value, label }) => {
    // Helper para formato 00
    const fmt = (v) => String(v).padStart(2, '0');

    // Valor actual (Animado)
    const [current, setCurrent] = useState(fmt(value));
    // Valor previo (Estático)
    const [previous, setPrevious] = useState(fmt(value));

    const [animate, setAnimate] = useState(false);

    useEffect(() => {
        const valStr = fmt(value);
        if (valStr !== current) {
            // 1. Guardamos el valor que se va a ir en 'previous'
            setPrevious(current);
            // 2. Actualizamos el valor nuevo en 'current'
            setCurrent(valStr);
            // 3. Disparamos la animación
            setAnimate(true);

            const timer = setTimeout(() => {
                setAnimate(false);
                // Al terminar la animación, 'previous' se iguala a 'current' 
                // para preparar el siguiente ciclo, aunque visualmente ya no importa
                setPrevious(valStr);
            }, 600); // Mismo tiempo que el CSS

            return () => clearTimeout(timer);
        }
    }, [value]);

    return (
        <div className="flip-unit">
            <div className={`flip-card ${animate ? 'flipping' : ''}`}>

                {/* 1. TOP ESTÁTICO (Fondo): Muestra el NUEVO valor */}
                {/* Cuando la carta caiga, revelará este número */}
                <div className="card-face card-top">
                    {current}
                </div>

                {/* 2. BOTTOM ESTÁTICO (Fondo): Muestra el VIEJO valor */}
                {/* Cuando la carta caiga, tapará este número */}
                <div className="card-face card-bottom">
                    {previous}
                </div>

                {/* 3. PIEZA QUE GIRA */}
                <div className="card-flip">
                    {/* Frente: Parte de ARRIBA del número VIEJO */}
                    <div className="card-face card-top face-front">
                        {previous}
                    </div>

                    {/* Reverso: Parte de ABAJO del número NUEVO */}
                    <div className="card-face card-bottom face-back">
                        {current}
                    </div>
                </div>

            </div>
            <span className="flip-label">{label}</span>
        </div>
    );
};

function Countdown({ visible, targetDate, onComplete, title = "Algo especial está en camino…" }) {
    // Fix: Memoize the Date object to prevent it from being a new reference on every render,
    // which causes the useEffect below to trigger an infinite loop.
    const finalDate = useMemo(() => targetDate ? new Date(targetDate) : DEFAULT_TARGET, [targetDate]);

    const [time, setTime] = useState(() => getTimeUntil(finalDate));
    const shouldReduceMotion = typeof window !== 'undefined' ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

    useEffect(() => {
        if (!visible) return;

        // Check immediately
        const initial = getTimeUntil(finalDate);
        setTime(initial);

        // If already passed, trigger complete and stop.
        if (initial.days <= 0 && initial.hours <= 0 && initial.minutes <= 0 && initial.seconds <= 0) {
            onComplete?.();
            return;
        }

        const interval = setInterval(() => {
            const t = getTimeUntil(finalDate);
            setTime(t);
            if (t.days <= 0 && t.hours <= 0 && t.minutes <= 0 && t.seconds <= 0) {
                clearInterval(interval);
                onComplete?.();
            }
        }, 1000);

        return () => clearInterval(interval);
    }, [visible, finalDate]); // Removed onComplete from dependency to avoid loop if parent recreates it without useCallback

    if (!visible) return null;

    const ariaLabel = `Faltan ${time.days} días, ${time.hours} horas, ${time.minutes} minutos y ${time.seconds} segundos`;
    const dateString = finalDate.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });

    return (
        <motion.div
            className="countdown-section"
            initial={shouldReduceMotion ? false : { opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1], delay: 0.3 }}
            role="timer"
            aria-label={ariaLabel}
        >
            <p className="countdown-teaser">{title}</p>

            <div className="countdown-grid" aria-hidden="true">
                <FlipUnit value={time.days} label="días" />
                <span className="countdown-separator">:</span>
                <FlipUnit value={time.hours} label="horas" />
                <span className="countdown-separator">:</span>
                <FlipUnit value={time.minutes} label="min" />
                <span className="countdown-separator">:</span>
                <FlipUnit value={time.seconds} label="seg" />
            </div>

            <p className="countdown-date">
                <time dateTime={finalDate.toISOString()}>{dateString}</time>
            </p>
        </motion.div>
    );
}

export default Countdown;

import './FloatingPetals.css';

/**
 * CSS-only floating petals — lightweight ambient effect
 * Creates ~12 drifting particles (gold/rose) for romantic atmosphere
 */
function FloatingPetals() {
    return (
        <div className="floating-petals" aria-hidden="true">
            {Array.from({ length: 12 }, (_, i) => (
                <div
                    key={i}
                    className={`petal petal--${(i % 3) + 1}`}
                    style={{
                        '--delay': `${i * 2.5}s`,
                        '--x-start': `${10 + Math.random() * 80}%`,
                        '--drift': `${(Math.random() - 0.5) * 100}px`,
                        '--size': `${3 + Math.random() * 4}px`,
                        '--duration': `${12 + Math.random() * 10}s`,
                    }}
                />
            ))}
        </div>
    );
}

export default FloatingPetals;

