import { useState, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useReducedMotion } from 'framer-motion';
import './LetterReveal.css';

// Content structure from the "Better" snippet
// Including "Una carta para ti" etc.
const LETTER_BODY = [
    { type: 'greeting', text: 'Mi amor,' },

    { type: 'paragraph', text: 'Sé que la distancia a veces pesa. Hay días en que un mensaje no alcanza, una llamada se queda corta y simplemente extraño tenerte cerca.' },

    { type: 'paragraph', text: 'Llevamos casi 4 años juntos. Y aunque estoy acostumbrado a estar solo, cuando estás conmigo todo cambia. Puedo dormir tranquilo, profundo, sin dar vueltas. Contigo el sueño llega fácil, como si mi cuerpo supiera que está en el lugar correcto.' },

    { type: 'paragraph', text: 'Eso es lo que más extraño: no las cosas grandes o locas, sino lo cotidiano. Dormir a tu lado, despertar y verte ahí, saber que no estoy solo en la cama. Es simple, pero para mí significa mucho.' },

    { type: 'paragraph', text: 'Admiro tu paciencia, cómo me aguantas incluso cuando no soy el más fácil. Y aunque a veces pienso que podrías tener más carácter o ser más "intensa", la verdad es que tu forma tranquila y constante de quererme me ha mantenido aquí todo este tiempo. Me demuestras amor en cosas que nadie más nota, de maneras no convencionales, y eso me llega más hondo que cualquier gesto exagerado.' },

    { type: 'paragraph', text: 'Quiero que sepas que pienso en el día en que esta distancia termine. No sé exactamente cuándo, pero sé que va a pasar. Y cuando llegue, voy a abrazarte fuerte, vamos a dormir juntos todas las noches que queramos, y voy a recordarte cada día lo agradecido que estoy de tenerte.' },

    { type: 'paragraph', text: 'Pronto estos mensajes y llamadas serán solo el comienzo de algo mejor. Vamos a construir más recuerdos, más noches tranquilas, más mañanas sin prisa. Porque aunque ahora estemos lejos, tú sigues siendo mi lugar favorito para descansar.' },

    { type: 'closing', text: 'Te quiero mucho, más de lo que sé decir.\nCon todo mi cariño,' },

    { type: 'signature', text: '-Church' }
];

const LetterReveal = ({ visible, onComplete, onFinished, skipTriggered = false }) => {
    const [isVisible, setIsVisible] = useState(false);

    // Typing state
    const [currentBlockIndex, setCurrentBlockIndex] = useState(0);
    const [currentCharIndex, setCurrentCharIndex] = useState(0);
    const [isTyping, setIsTyping] = useState(false);
    const [isFinished, setIsFinished] = useState(false);
    const [isSkipped, setIsSkipped] = useState(false); // Track if user skipped

    const containerRef = useRef(null);
    const shouldReduceMotion = useReducedMotion();

    // Start animation loop
    useEffect(() => {
        if (visible) {
            const timer = setTimeout(() => {
                setIsVisible(true);
                if (shouldReduceMotion) {
                    setIsFinished(true);
                } else {
                    setIsTyping(true);
                }
            }, 300);
            return () => clearTimeout(timer);
        } else {
            setIsVisible(false);
        }
    }, [visible, shouldReduceMotion]);

    // Typing effect logic
    useEffect(() => {
        if (!isTyping || isFinished || currentBlockIndex >= LETTER_BODY.length) return;

        const currentBlock = LETTER_BODY[currentBlockIndex];

        if (currentCharIndex < currentBlock.text.length) {
            const char = currentBlock.text[currentCharIndex];
            const speed = char === ',' || char === '.' ? 50 : 30 + Math.random() * 20;

            const timer = setTimeout(() => {
                setCurrentCharIndex(prev => prev + 1);
            }, speed);
            return () => clearTimeout(timer);
        } else {
            // Block finished, move to next
            const timer = setTimeout(() => {
                setCurrentBlockIndex(prev => prev + 1);
                setCurrentCharIndex(0);
            }, 600);
            return () => clearTimeout(timer);
        }
    }, [isTyping, isFinished, currentBlockIndex, currentCharIndex]);

    // Check completion
    useEffect(() => {
        if (currentBlockIndex >= LETTER_BODY.length && !isFinished) {
            setIsFinished(true);
            setIsTyping(false);
        }
    }, [currentBlockIndex, isFinished]);

    // Auto-scroll logic targeting the .letter-wrapper
    useEffect(() => {
        const el = containerRef.current;
        if (!el) return;
        // Basic scroll to bottom if content expands
        // Checking if isTyping to allow user manual scroll override if they want? 
        // For now, gentle scroll to bottom is good.
        el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
    }, [currentBlockIndex, currentCharIndex]);

    // Link internal status to parent
    useEffect(() => {
        if (isFinished) {
            onFinished?.(true);
        }
    }, [isFinished, onFinished]);

    // Handle external skip trigger from Teaser.jsx
    useEffect(() => {
        if (skipTriggered && !isFinished) {
            setIsTyping(false);
            setIsFinished(true);
            setIsSkipped(true);
            setCurrentBlockIndex(LETTER_BODY.length);
        }
    }, [skipTriggered, isFinished]);

    // Auto-advance logic: if finished naturally (not skipped), wait 6s and proceed
    useEffect(() => {
        if (isFinished && !isSkipped) {
            const timer = setTimeout(() => {
                onComplete();
            }, 6000); // 6 seconds to read signature
            return () => clearTimeout(timer);
        }
    }, [isFinished, isSkipped, onComplete]);

    // Helper to render text up to current point
    const renderBlockContent = (block, index) => {
        if (isFinished) return block.text;
        if (index > currentBlockIndex) return '';
        if (index < currentBlockIndex) return block.text;

        return block.text.substring(0, currentCharIndex);
    };

    return (
        <div className={`night-sky ${!isVisible ? 'hidden' : ''}`}>
            {/* Stars Layer Removed - Global Background Used */}


            <div className={`letter-container ${isVisible ? 'visible' : ''}`}>
                <div className="letter-wrapper" ref={containerRef}>


                    {/* Countdown would go here, but omitted as per user request */}

                    <div className="content">
                        {LETTER_BODY.map((block, i) => {
                            if (!isFinished && i > currentBlockIndex) return null;

                            const text = renderBlockContent(block, i);
                            const isTypingThis = !isFinished && i === currentBlockIndex;

                            const renderedText = text.split('\n').map((line, lineIdx, arr) => (
                                <span key={lineIdx}>
                                    {line}
                                    {lineIdx < arr.length - 1 && <br />}
                                </span>
                            ));

                            return (
                                <p key={i} className={block.type}>
                                    {renderedText}
                                    {isTypingThis && <span className="typing-cursor">|</span>}
                                </p>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LetterReveal;

import { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import StarryBackground from './StarryBackground';
import IntroSequence, { SakuraOverlay } from './IntroSequence';
import FlowerGarden from './FlowerGarden';
import LetterReveal from './LetterReveal';
import Countdown from './Countdown';
import FloatingPetals from './FloatingPetals';
import { useAppConfig } from '../../context/AppConfigContext';
import { useAuth } from '../../hooks/useAuth';
import { db } from '../../services/firebase';
import { doc, updateDoc } from 'firebase/firestore';
import './Teaser.css';

/**
 * Teaser flow:
 * 1. intro     — Star → text → PhotoMosaic (C ♥ I) → text
 * 2. flowers   — CSS flower garden animation with floating hearts
 * 3. letter    — Typing love letter in glassmorphism card
 * 4. countdown — Timer to April 4 anniversary (reveals after letter finishes)
 *
 * Photo config:
 * Place couple photos in /public/photos/teaser/ as 1.jpg, 2.jpg, etc.
 * Set PHOTO_COUNT to the number of photos you've added.
 * Minimum: 10 photos. Ideal: 27+ for no repeats.
 * If 0, placeholder glow dots are shown instead.
 */
const PHOTO_COUNT = 0; // ← Change this when you add photos!

function Teaser() {
    const [phase, setPhase] = useState('intro');
    const [showCountdown, setShowCountdown] = useState(false);
    const [showSakura, setShowSakura] = useState(false);
    const [isLetterFinished, setIsLetterFinished] = useState(false);
    const [letterSkipTriggered, setLetterSkipTriggered] = useState(false);
    const [isExploding, setIsExploding] = useState(false);
    const [isFadingOut, setIsFadingOut] = useState(false);
    const navigate = useNavigate();
    const { teaser } = useAppConfig();
    const { user } = useAuth();

    const unlockAt = teaser?.unlockAt 
        ? new Date(teaser.unlockAt) 
        : new Date('2026-04-04T00:00:00');

    const handleIntroComplete = useCallback(() => {
        setPhase('flowers');
    }, []);

    const handleSkipToLetter = useCallback(() => {
        setShowSakura(false); // hide petals on skip
        setPhase('letter');
    }, []);

    const handleSakuraTrigger = useCallback(() => {
        setShowSakura(true);
    }, []);

    const handleFlowersComplete = useCallback(() => {
        setPhase('letter');
    }, []);

    const handleLetterComplete = useCallback(() => {
        setIsLetterFinished(true);
        setShowCountdown(true);
    }, []);

    const handleCountdownComplete = useCallback(async () => {
        setIsExploding(true);
        
        // Start fade to dark poetic background at 2s
        setTimeout(() => setIsFadingOut(true), 2000);

        // Final transition after 10s (2s sakura + 8s text)
        setTimeout(async () => {
            if (user?.uid) {
                try {
                    // 1. Mark teaser as completed in Firestore
                    const userRef = doc(db, 'users', user.uid);
                    await updateDoc(userRef, { teaserCompleted: true });
                } catch (err) {
                    console.error('Error updating teaser status:', err);
                }
            }
            // 2. Navigate to welcome screen
            navigate('/welcome');
        }, 10000);
    }, [navigate, user?.uid]);

    return (
        <div className="teaser-app">
            <StarryBackground />

            {/* Floating petals appear after intro */}
            {phase !== 'intro' && <FloatingPetals />}

            <AnimatePresence mode="wait">
                    {/* Phase 1: Intro with PhotoMosaic */}
                    {phase === 'intro' && (
                        <IntroSequence
                            key="intro"
                            onComplete={handleIntroComplete}
                            onSkipToLetter={handleSkipToLetter}
                            onSakuraTrigger={handleSakuraTrigger}
                            photoCount={PHOTO_COUNT}
                        />
                    )}

                    {/* Phase 2: Flower Garden */}
                    {phase === 'flowers' && (
                        <FlowerGarden
                            key="flowers"
                            visible={true}
                            onComplete={handleFlowersComplete}
                        />
                    )}

                    {/* Phase 3 & 4: Letter + Countdown */}
                    {phase === 'letter' && (
                        <motion.div
                            key="main"
                            className="main-content"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            transition={{ duration: 1.5, ease: 'easeOut' }}
                        >
                            <div className="main-scroll">
                                <LetterReveal
                                    visible={!showCountdown}
                                    onComplete={handleLetterComplete}
                                    onFinished={setIsLetterFinished}
                                    skipTriggered={letterSkipTriggered}
                                />

                                <AnimatePresence>
                                    {showCountdown && (
                                        <motion.div
                                            initial={{ opacity: 0, y: 30 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
                                        >
                                            <Countdown 
                                                visible={true} 
                                                targetDate={unlockAt}
                                                onComplete={handleCountdownComplete}
                                            />

                                            <motion.div
                                                className="teaser-footer"
                                                initial={{ opacity: 0 }}
                                                animate={{ opacity: 1 }}
                                                transition={{ delay: 1.5, duration: 1 }}
                                            >
                                                <p className="footer-text">
                                                    Hecho con todo mi amor 💜
                                                </p>
                                            </motion.div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

            {/* 🌸 Sakura petals — rendered at App level so they persist above flower garden */}
            {/* We hide them when fade-out (Phase 5 dark bg) starts for a cleaner transition */}
            {(showSakura || (isExploding && !isFadingOut)) && <SakuraOverlay />}

            {/* Final Explosion Flash */}
            {isExploding && (
                <motion.div
                    className="explosion-flash"
                    initial={{ scale: 0, opacity: 1 }}
                    animate={{ scale: 4, opacity: 0 }}
                    transition={{ duration: 2.0, ease: "easeInOut" }}
                />
            )}

            {/* Cinematic Fade Out to Dark with Poetic Text */}
            {isFadingOut && (
                <motion.div
                    className="welcome-fade-overlay"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 2.0, ease: "easeInOut" }}
                    style={{
                        position: 'fixed',
                        top: 0, left: 0, right: 0, bottom: 0,
                        backgroundColor: '#110c14', // dark theme color
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 9999
                    }}
                >
                    <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 1.5, duration: 3.0, ease: "easeInOut" }}
                        style={{
                            color: '#fff',
                            fontSize: '1.4rem',
                            fontFamily: 'serif',
                            fontStyle: 'italic',
                            textAlign: 'center',
                            lineHeight: '1.6',
                            padding: '0 2rem'
                        }}
                    >
                        Ya llegó el momento...<br/>
                        <span style={{ fontSize: '1rem', opacity: 0.7, marginTop: '2rem', display: 'block' }}>
                            Nuestro viaje continúa.
                        </span>
                    </motion.div>
                </motion.div>
            )}

            {/* Centralized Buttons */}
            {phase === 'intro' && (
                <button className="skip-intro-btn" onClick={handleIntroComplete}>
                    Saltar ›
                </button>
            )}
            {phase === 'flowers' && (
                <button className="skip-intro-btn" onClick={handleFlowersComplete}>
                    Saltar ›
                </button>
            )}
            {phase === 'letter' && !showCountdown && (
                <button className="skip-letter-btn" onClick={() => {
                    if (isLetterFinished) {
                        handleLetterComplete();
                    } else {
                        setLetterSkipTriggered(true);
                    }
                }}>
                    {isLetterFinished ? "Continuar ›" : "Omitir ›"}
                </button>
            )}
        </div>
    );
}

