import { useState, useEffect } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import Countdown from './Countdown';
import { useAppConfig } from '../../context/AppConfigContext';
import LoadingScreen from '../ui/LoadingScreen/LoadingScreen';
import './TimeLock.css';

function TimeLock({ children }) {
    const { teaser, isConfigLoaded } = useAppConfig();
    const [isLocked, setIsLocked] = useState(true);

    const unlockDate = teaser?.unlockAt 
        ? new Date(teaser.unlockAt) 
        : null;

    useEffect(() => {
        if (!isConfigLoaded) return;

        if (teaser?.isEnabled === false) {
            setIsLocked(false);
            return;
        }

        if (unlockDate) {
            const target = unlockDate.getTime();
            const now = Date.now();

            if (now >= target) {
                setIsLocked(false);
            }
        }
    }, [isConfigLoaded, unlockDate, teaser?.isEnabled]);

    const handleUnlock = () => {
        // Wait a moment for the countdown hitting 0 visual state
        setTimeout(() => {
            setIsLocked(false);
        }, 1000);
    };

    if (!isConfigLoaded) return <LoadingScreen message="Sincronizando tiempo..." />;

    return (
        <AnimatePresence mode="wait">
            {isLocked ? (
                <motion.div
                    key="locked"
                    className="time-lock-screen"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0, transition: { duration: 1.5, ease: "easeInOut" } }}
                >
                    <div className="lock-content">
                        {/* Reusing Countdown with custom title and date */}
                        <Countdown
                            visible={true}
                            targetDate={unlockDate || new Date()}
                            onComplete={handleUnlock}
                            title="El contenido no está disponible aún. Espera un poquito..."
                        />
                    </div>
                </motion.div>
            ) : (
                <motion.div
                    key="content"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 1.5, ease: "easeOut" }}
                    style={{ width: '100%', height: '100%' }}
                >
                    {children}
                </motion.div>
            )}
        </AnimatePresence>
    );
}

export default TimeLock;

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './BottomNav.module.css';

/**
 * Reusable Bottom Navigation Component with "More" menu support.
 * 
 * @param {object} props
 * @param {string} props.activeTab - Current active tab ID
 * @param {function} props.setActiveTab - Function to update active tab
 * @param {Array} props.tabs - Main tabs to display in the primary bar
 * @param {Array} props.moreTabs - Secondary tabs to display in the "More" sheet
 * @param {number} props.pendingCount - Count for the notification badge
 */
export default function BottomNav({ activeTab, setActiveTab, tabs = [], moreTabs = [], pendingCount = 0, pendingBingoCount = 0 }) {
    const [isMoreOpen, setIsMoreOpen] = useState(false);
    const moreMenuRef = useRef(null);

    // Close menu when clicking outside
    useEffect(() => {
        function handleClickOutside(event) {
            if (moreMenuRef.current && !moreMenuRef.current.contains(event.target)) {
                setIsMoreOpen(false);
            }
        }
        if (isMoreOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isMoreOpen]);

    if (!tabs || tabs.length === 0) return null;

    // Check if the currently active tab is one of the "more" tabs
    const isMoreActive = moreTabs.some(t => t.id === activeTab);

    const handleTabSelect = (tabId) => {
        setActiveTab(tabId);
        setIsMoreOpen(false);
    };

    return (
        <div className={styles.bottomNavContainer} ref={moreMenuRef}>
            {/* --- "More" Sheet --- */}
            <AnimatePresence>
                {isMoreOpen && (
                    <motion.div
                        className={styles.moreSheet}
                        initial={{ opacity: 0, y: 20, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 20, scale: 0.95 }}
                    >
                        <div className={styles.moreGrid}>
                            {moreTabs.map(tab => (
                                <button
                                    key={tab.id}
                                    className={`${styles.moreItem} ${activeTab === tab.id ? styles.moreItemActive : ''}`}
                                    onClick={() => handleTabSelect(tab.id)}
                                >
                                    <div className={styles.iconWrapper}>
                                        <span className={`material-symbols-outlined ${styles.moreIcon}`}>
                                            {tab.icon}
                                        </span>
                                        {tab.id === 'bingo' && pendingBingoCount > 0 && (
                                            <motion.div
                                                className={styles.badgeLeft}
                                                initial={{ scale: 0 }}
                                                animate={{ scale: 1 }}
                                            >
                                                {pendingBingoCount}
                                            </motion.div>
                                        )}
                                    </div>
                                    <span className={styles.moreLabel}>{tab.label}</span>
                                </button>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* --- Primary Nav Bar --- */}
            <nav className={styles.bottomNav}>
                {tabs.map(tab => {
                    const isActive = activeTab === tab.id;
                    const hasLugaresBadge = tab.id === 'lugares' && pendingCount > 0;
                    const hasBadge = hasLugaresBadge;

                    return (
                        <button
                            key={tab.id}
                            onClick={() => handleTabSelect(tab.id)}
                            className={`${styles.navItem} ${isActive ? styles.navItemActive : ''}`}
                        >
                            <motion.div
                                className={styles.itemContent}
                                initial={false}
                                animate={{ scale: isActive ? 1.1 : 1 }}
                            >
                                <div className={styles.iconWrapper}>
                                    <span
                                        className={`material-symbols-outlined ${styles.navIcon}`}
                                        style={isActive ? { fontVariationSettings: "'FILL' 1" } : {}}
                                    >
                                        {tab.icon}
                                    </span>
                                    {hasLugaresBadge && (
                                        <motion.div
                                            className={styles.badge}
                                            initial={{ scale: 0 }}
                                            animate={{ scale: 1 }}
                                        >
                                            {pendingCount}
                                        </motion.div>
                                    )}
                                </div>
                                <span className={styles.navLabel}>{tab.label}</span>
                            </motion.div>
                        </button>
                    );

                })}

                {/* --- "More" Button --- */}
                {moreTabs.length > 0 && (
                    <button
                        onClick={() => setIsMoreOpen(!isMoreOpen)}
                        className={`${styles.navItem} ${isMoreActive ? styles.navItemActive : ''} ${isMoreOpen ? styles.navItemMoreOpen : ''} ${pendingBingoCount > 0 ? styles.navItemGlow : ''}`}
                    >
                        <motion.div
                            className={styles.itemContent}
                            animate={{ scale: isMoreOpen ? 1.1 : 1 }}
                        >
                            <div className={styles.iconWrapper}>
                                <span className={`material-symbols-outlined ${styles.navIcon}`}>
                                    more_horiz
                                </span>
                            </div>
                            <span className={styles.navLabel}>Más</span>
                        </motion.div>
                    </button>
                )}
            </nav>
        </div>
    );
}

import { motion, AnimatePresence } from 'framer-motion';
import styles from './BottomSheetModal.module.css';

/**
 * Reusable Bottom Sheet Modal Component
 * @param {object} props
 * @param {boolean} props.isOpen - Is modal open
 * @param {function} props.onClose - Function to close modal
 * @param {string} props.emoji - Large emoji header
 * @param {string} props.title - Modal title text
 * @param {string} props.description - Modal description text
 * @param {string} props.confirmText - Primary action text
 * @param {string} props.cancelText - Secondary action text
 * @param {function} props.onConfirm - Action when confirmed
 * @param {function} props.onCancel - Action when cancelled (defaults to onClose)
 * @param {boolean} props.closeOnClickOutside - Whether to close when clicking the overlay
 * @param {string} props.overlayClassName - Custom class for the overlay
 * @param {boolean} props.showOverlay - Whether to show the backdrop background/blur
 */
export default function BottomSheetModal({
    isOpen,
    onClose,
    emoji,
    title,
    description,
    children,
    confirmText = 'Confirmar',
    cancelText = 'Cancelar',
    onConfirm,
    onCancel,
    hideActions = false,
    closeOnClickOutside = true,
    overlayClassName = '',
    showOverlay = true,
}) {
    return (
        <AnimatePresence>
            {isOpen && (
                <motion.div
                    className={`${styles.modalOverlay} ${overlayClassName} ${!showOverlay ? styles.noOverlay : ''}`}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={() => closeOnClickOutside && onClose()}
                >
                    <motion.div
                        className={styles.modalContent}
                        initial={{ y: '100%' }}
                        animate={{ y: 0 }}
                        exit={{ y: '100%' }}
                        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
                        onClick={(e) => e.stopPropagation()}
                    >
                        {/* Indicador de arrastre decorativo */}
                        <div className={styles.dragHandle} />

                        {emoji && <span className={styles.modalEmoji}>{emoji}</span>}
                        {title && <h2>{title}</h2>}
                        {description && <p>{description}</p>}
                        {children && <div className={styles.children}>{children}</div>}


                        {!hideActions && (
                            <div className={styles.actions}>
                                <button
                                    type="button"
                                    className={styles.confirmBtn}
                                    onClick={onConfirm}
                                >
                                    {confirmText}
                                </button>
                                <button
                                    type="button"
                                    className={styles.cancelBtn}
                                    onClick={onCancel || onClose}
                                >
                                    {cancelText}
                                </button>
                            </div>
                        )}
                    </motion.div>
                </motion.div>
            )}
        </AnimatePresence>
    );
}

import { forwardRef } from 'react';
import { motion } from 'framer-motion';
import styles from './Button.module.css';

/**
 * Reusable Button component with different variants.
 * Uses motion.button for animations.
 * 
 * NOTE: We manually destructure motion props to ensure they are 
 * correctly handled by motion.button and not passed to the DOM in React 19.
 */
const Button = forwardRef(({
    type = 'button',
    children,
    variant = 'primary',
    size = 'md',
    isLoading = false,
    className = '',
    // Motion props
    whileHover,
    whileTap,
    initial,
    animate,
    exit,
    variants,
    transition,
    ...props
}, ref) => {
    return (
        <motion.button
            ref={ref}
            type={type}
            className={`${styles.button} ${styles[variant]} ${styles[size]} ${className}`}
            disabled={isLoading || props.disabled}
            // Explicitly pass motion props
            whileHover={whileHover}
            whileTap={whileTap}
            initial={initial}
            animate={animate}
            exit={exit}
            variants={variants}
            transition={transition}
            // Pass the rest of the standard DOM props
            {...props}
        >
            {isLoading ? (
                <span className={styles.loader}>✦</span>
            ) : children}
        </motion.button>
    );
});

Button.displayName = 'Button';

export default Button;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './Carousel.module.css';

/**
 * Enhanced Carousel Component
 * Provides a premium, interactive way to view a collection of photos.
 */
export default function Carousel({ photos = [], initialIndex = 0, onBack }) {
    const [currentIndex, setCurrentIndex] = useState(initialIndex);
    const [direction, setDirection] = useState(0);

    if (!photos || photos.length === 0) return null;

    const paginate = (newDirection) => {
        setDirection(newDirection);
        setCurrentIndex((prevIndex) => {
            let nextIndex = prevIndex + newDirection;
            if (nextIndex < 0) nextIndex = photos.length - 1;
            if (nextIndex >= photos.length) nextIndex = 0;
            return nextIndex;
        });
    };

    const variants = {
        enter: (direction) => ({
            x: direction > 0 ? 300 : -300,
            opacity: 0,
            scale: 0.9,
            rotateY: direction > 0 ? 45 : -45
        }),
        center: {
            zIndex: 1,
            x: 0,
            opacity: 1,
            scale: 1,
            rotateY: 0
        },
        exit: (direction) => ({
            zIndex: 0,
            x: direction < 0 ? 300 : -300,
            opacity: 0,
            scale: 0.9,
            rotateY: direction < 0 ? 45 : -45
        })
    };

    return (
        <div className={styles.carouselContainer}>
            {onBack && (
                <button className={styles.backBtn} onClick={onBack}>
                    <span className="material-symbols-outlined">arrow_back</span>
                    <span>Volver</span>
                </button>
            )}

            <div className={styles.mainStage}>
                <AnimatePresence initial={false} custom={direction}>
                    <motion.div
                        key={currentIndex}
                        custom={direction}
                        variants={variants}
                        initial="enter"
                        animate="center"
                        exit="exit"
                        transition={{
                            x: { type: "spring", stiffness: 300, damping: 30 },
                            opacity: { duration: 0.2 },
                            scale: { duration: 0.3 },
                            rotateY: { duration: 0.4 }
                        }}
                        drag="x"
                        dragConstraints={{ left: 0, right: 0 }}
                        dragElastic={1}
                        onDragEnd={(e, { offset, velocity }) => {
                            const swipe = Math.abs(offset.x) * velocity.x;
                            if (swipe < -10000) {
                                paginate(1);
                            } else if (swipe > 10000) {
                                paginate(-1);
                            }
                        }}
                        className={styles.slide}
                    >
                        <img 
                            src={photos[currentIndex]} 
                            alt={`Foto ${currentIndex + 1}`} 
                            className={styles.image}
                        />
                    </motion.div>
                </AnimatePresence>

                {photos.length > 1 && (
                    <>
                        <button className={`${styles.navBtn} ${styles.prev}`} onClick={() => paginate(-1)}>
                            <span className="material-symbols-outlined">chevron_left</span>
                        </button>
                        <button className={`${styles.navBtn} ${styles.next}`} onClick={() => paginate(1)}>
                            <span className="material-symbols-outlined">chevron_right</span>
                        </button>
                    </>
                )}
            </div>

            <div className={styles.footer}>
                <div className={styles.counter}>
                    {currentIndex + 1} / {photos.length}
                </div>
                <div className={styles.indicators}>
                    {photos.map((_, idx) => (
                        <div 
                            key={idx} 
                            className={`${styles.dot} ${idx === currentIndex ? styles.dotActive : ''}`}
                            onClick={() => {
                                setDirection(idx > currentIndex ? 1 : -1);
                                setCurrentIndex(idx);
                            }}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
}

import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import Button from '../Button/Button';
import styles from './ConfirmModal.module.css';

/**
 * Global Confirm Modal Component
 * 
