                            <span className={styles.emoji}>{emoji}</span>
                        </div>

                        <div className={styles.content}>
                            {title && <h2 className={styles.title}>{title}</h2>}
                            <p className={styles.message}>{message}</p>
                        </div>

                        <div className={styles.actions}>
