import React, { useState, useRef } from 'react';
import styles from './KawaiiInput.module.css';

export default function KawaiiInput({
    type = 'text', // text, search, select, date, photo, textarea, toggle
    name,
    label,
    value,
    onChange,
    onFocus,
    onBlur,
    onClick,
    placeholder,
    iconLeft,
    iconRight,
    error,
    disabled = false,
    photos = [], // for photo picker
    options = [], // for select
    className = '',
    onClear,
    helpText,
    ...rest
}) {
    const [isFocused, setIsFocused] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const inputRef = useRef(null);

    const handleFocus = (e) => {
        setIsFocused(true);
        if (onFocus) onFocus(e);
    };

    const handleBlur = (e) => {
        setIsFocused(false);
        if (onBlur) onBlur(e);
    };

    const handleWrapperClick = () => {
        if (disabled) return;
        if (inputRef.current && (type === 'text' || type === 'search' || type === 'textarea')) {
            inputRef.current.focus();
        }
        if (onClick) onClick();
    };

    const wrapperClasses = [
        styles.inputWrapper,
        isFocused ? styles.inputWrapperFocus : '',
        error ? styles.inputWrapperError : '',
        disabled ? styles.inputWrapperDisabled : '',
        type === 'textarea' ? styles.inputWrapperTextarea : '',
        (type === 'select' || type === 'date' || type === 'photo' || type === 'toggle' || onClick) ? styles.clickable : '',
        className
    ].filter(Boolean).join(' ');

    const renderLeftContent = () => {
        if (type === 'photo') {
            if (photos && photos.length > 0) {
                return <img src={photos[0]} alt="Selected" className={styles.photoThumbnail} />;
            }
            return (
                <div className={styles.photoPlaceholder}>
                    <span className="material-symbols-outlined">image</span>
                </div>
            );
        }

        let icon = iconLeft;
        if (!icon) {
            switch (type) {
                case 'search': icon = 'search'; break;
                case 'date': icon = 'calendar_month'; break;
                case 'password': icon = 'lock'; break;
                default: icon = null;
            }
        }

        if (icon) {
            return (
                <span className={`material-symbols-outlined ${styles.leftIcon} ${type === 'textarea' ? styles.leftIconTextarea : ''}`}>
                    {icon}
                </span>
            );
        }
        return null;
    };

    const renderMainContent = () => {
        switch (type) {
            case 'textarea':
                return (
                    <textarea
                        ref={inputRef}
                        className={styles.textareaElement}
                        name={name}
                        value={value || ''}
                        onChange={onChange}
                        onFocus={handleFocus}
                        onBlur={handleBlur}
                        placeholder={placeholder}
                        disabled={disabled}
                        {...rest}
                    />
                );
            case 'select': {
                // Find selected option label
                const selectedOpt = options.find(opt => (opt.value || opt.id) === value);
                const displayVal = selectedOpt ? (selectedOpt.label || selectedOpt.name || (selectedOpt.emoji ? `${selectedOpt.emoji} ${selectedOpt.name}` : value)) : '';
                return (
                    <div className={`${styles.valueText} ${!value ? styles.valuePlaceholder : ''}`}>
                        {value ? displayVal : placeholder}
                    </div>
                );
            }
            case 'date':
                return (
                    <div className={`${styles.valueText} ${!value ? styles.valuePlaceholder : ''}`}>
                        {value || placeholder}
                    </div>
                );
            case 'photo':
                return (
                    <div className={`${styles.valueText} ${!photos?.length ? styles.valuePlaceholder : ''}`}>
                        {photos?.length > 0 ? `${photos.length} foto${photos.length !== 1 ? 's' : ''} seleccionada${photos.length !== 1 ? 's' : ''}` : (placeholder || 'Agregar fotos')}
                    </div>
                );
            case 'toggle':
                return (
                    <div className={styles.valueText}>
                        {placeholder || ''}
                    </div>
                );
            case 'search':
            case 'text':
            case 'password':
            case 'email':
            case 'number':
            default: {
                const inputType = type === 'password' ? (showPassword ? 'text' : 'password') : (type === 'search' ? 'text' : type);
                return (
                    <input
                        ref={inputRef}
                        type={inputType}
                        className={styles.inputElement}
                        name={name}
                        value={value || ''}
                        onChange={onChange}
                        onFocus={handleFocus}
                        onBlur={handleBlur}
                        placeholder={placeholder}
                        disabled={disabled}
                        {...rest}
                    />
                );
            }
        }
    };

    const renderRightContent = () => {
        if (type === 'toggle') {
            return (
                <div
                    className={`${styles.toggleWrapper} ${value ? styles.toggleWrapperActive : ''}`}
                    onClick={(e) => {
                        e.stopPropagation();
                        if (!disabled && onChange) {
                            onChange({ target: { checked: !value, value: !value } });
                        }
                    }}
                >
                    <div className={styles.toggleKnob} />
                </div>
            );
        }

        if (type === 'search' && value) {
            return (
                <button
                    type="button"
                    className={styles.rightAction}
                    onClick={(e) => {
                        e.stopPropagation();
                        // Nota: onClear es requerido si se usa type === 'search'
                        // No se provee fallback a onChange para evitar mutaciones silenciosas
                        if (onClear) {
                            onClear();
                        }
                        if (inputRef.current) inputRef.current.focus();
                    }}
                >
                    <span className="material-symbols-outlined">close</span>
                </button>
            );
        }

        if (type === 'photo') {
            return (
                <div className={styles.rightAction}>
                    <span className="material-symbols-outlined">add_photo_alternate</span>
                </div>
            );
        }

        if (type === 'date') {
            return (
                <div className={styles.rightAction}>
                    <span className="material-symbols-outlined">chevron_right</span>
                </div>
            );
        }

        if (type === 'select') {
            return (
                <div className={styles.rightAction}>
                    <span className="material-symbols-outlined">expand_more</span>
                </div>
            );
        }

        if (type === 'password') {
            return (
                <button
                    type="button"
                    className={styles.rightAction}
                    onClick={(e) => {
                        e.stopPropagation();
                        setShowPassword(!showPassword);
                    }}
                >
                    <span className="material-symbols-outlined">
                        {showPassword ? 'visibility_off' : 'visibility'}
                    </span>
                </button>
            );
        }

        if (iconRight) {
            return (
                <div className={styles.rightAction}>
                    <span className="material-symbols-outlined">{iconRight}</span>
                </div>
            );
        }

        return null;
    };

    return (
        <div className={styles.container}>
            {label && (
                <label className={styles.label}>{label}</label>
            )}

            <div className={wrapperClasses} onClick={handleWrapperClick}>
                {renderLeftContent()}
                {renderMainContent()}
                {renderRightContent()}

                {/* 
                 * Overlay native inputs for generic select/date.
                 * Desactivamos intencionalmente (!onClick) si el componente padre maneja
                 * la acción (ej. un Custom Bottom Sheet) para evitar conflictos con el UI nativo.
                 */}
                {type === 'select' && options && options.length > 0 && !onClick && (
                    <select
                        className={styles.hiddenNativeInput}
                        name={name}
                        value={value || ''}
                        onChange={onChange}
                        onFocus={handleFocus}
                        onBlur={handleBlur}
                        disabled={disabled}
                    >
                        <option value="" disabled>{placeholder}</option>
                        {options.map(opt => (
                            <option key={opt.value || opt.id} value={opt.value || opt.id}>
                                {opt.label || opt.name || (opt.emoji ? `${opt.emoji} ${opt.name}` : '')}
                            </option>
                        ))}
                    </select>
                )}

                {type === 'date' && !onClick && (
                    <input
                        type="date"
                        className={styles.hiddenNativeInput}
                        name={name}
                        value={value || ''}
                        onChange={onChange}
                        onFocus={handleFocus}
                        onBlur={handleBlur}
                        disabled={disabled}
                    />
                )}
            </div>

            {error && (
                <div className={styles.errorText}>
                    {typeof error === 'string' ? error : 'Este campo es requerido'}
                </div>
            )}
        </div>
    );
}

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './MapPin.module.css';

/**
 * Premium MapPin Component
 * Improved with Claymorphism and Framer Motion for high-fidelity animations.
 */
export default function MapPin({ 
    size = 'medium', 
    color = '#F4A7B9', 
    scale = 1.0,
    selected = false, 
    hideIcon = false, 
    hidePulse = false, 
    onClick 
}) {

    // Helper to darken color for volumetric shadows
    const getDarkerColor = (hex) => {
        if (!hex || hex === 'var(--pastel-mint)') return 'rgba(0,0,0,0.15)';
        let r = parseInt(hex.slice(1, 3), 16);
        let g = parseInt(hex.slice(3, 5), 16);
        let b = parseInt(hex.slice(5, 7), 16);
        return `rgba(${Math.floor(r * 0.7)}, ${Math.floor(g * 0.7)}, ${Math.floor(b * 0.7)}, 0.4)`;
    };

    const darkerColor = getDarkerColor(color);

    if (size === 'micro') {
        return (
            <motion.div 
                className={styles.pinWrapper}
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                whileHover={{ scale: 1.4 }}
                onClick={onClick}
            >
                <div className={styles.microDot} style={{ backgroundColor: color }} />
            </motion.div>
        );
    }

    return (
        <motion.div 
            className={`${styles.pinWrapper} ${selected ? styles.selected : ''}`}
            onClick={onClick}
            initial={{ scale: 0, y: -20, opacity: 0 }}
            animate={{ scale: scale, y: 0, opacity: 1 }}
            transition={{ type: 'spring', damping: 12, stiffness: 200 }}
        >
            {/* Smooth Ripple Effect (Framer Motion) */}
            <AnimatePresence>
                {!hidePulse && (size === 'large' || selected) && (
                    <motion.div 
                        className={styles.ripple}
                        style={{ color }}
                        initial={{ scale: 0.8, opacity: 0.5 }}
                        animate={{ scale: 2.2, opacity: 0 }}
                        exit={{ opacity: 0 }}
                        transition={{ 
                            duration: 2, 
                            repeat: Infinity, 
                            ease: "easeOut" 
                        }}
                    />
                )}
            </AnimatePresence>

            {/* The Pin Body (Claymorphic) */}
            <motion.div 
                className={`${styles.pin} ${styles[`size-${size}`]}`}
                style={{ backgroundColor: color }}
                whileHover={{ 
                    scale: 1.15,
                    rotate: -40, // Slight squish rotation
                    transition: { type: 'spring', stiffness: 400, damping: 10 }
                }}
                whileTap={{ scale: 0.95 }}
            >

                <div className={styles.innerLight} />
                <div className={styles.innerShadow} />
                
                {!hideIcon && (
                    <motion.div 
                        className={styles.iconContainer}
                        animate={selected ? { scale: [1, 1.3, 1] } : {}}
                        transition={{ repeat: selected ? Infinity : 0, duration: 1.5 }}
                    >
                        {size === 'large' && (
                            <span className="material-symbols-outlined material-icons-filled" style={{ fontSize: '20px', color: 'white' }}>
                                favorite
                            </span>
                        )}
                        {size === 'medium' && (
                            <span className="material-symbols-outlined material-icons-filled" style={{ fontSize: '15px', color: 'white' }}>
                                favorite
                            </span>
                        )}
                        {size === 'small' && (
                            <div className={styles.smallDot} />
                        )}
                    </motion.div>
                )}
            </motion.div>

            {/* Ground Shadow */}
            <motion.div 
                className={styles.shadow} 
                animate={{ 
                    scaleX: selected ? 1.5 : 1,
                    opacity: selected ? 0.3 : 0.15
                }}
            />
        </motion.div>
    );
}

import { useState, useEffect, useCallback, createContext } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import styles from './PastelToast.module.css';

/* ─── Context ─── */
const ToastContext = createContext(null);

let _dispatch = null;

/* ─────────────────────────────────────────
   Public API — usable anywhere in the tree
   ───────────────────────────────────────── */
export const toast = {
    success: (title, description, options) => _dispatch?.({ op: 'add', type: 'success', title, description, ...options }),
    error: (title, description, options) => _dispatch?.({ op: 'add', type: 'error', title, description, ...options }),
    loading: (title, description, options) => _dispatch?.({ op: 'add', type: 'loading', title, description, ...options }),
    info: (title, description, options) => _dispatch?.({ op: 'add', type: 'info', title, description, ...options }),

    /**
     * promise toast: shows a persisted "loading" toast, then
     * UPDATES IT IN PLACE (same id → same key) to success/error.
     * This avoids stacking and re-entry animations.
     */
    promise: async (promise, { loading, success, error }) => {
        const id = _dispatch?.({ op: 'add', type: 'loading', title: loading.title, description: loading.description, persist: true });
        try {
            const result = await promise;
            _dispatch?.({ op: 'update', id, type: 'success', title: success.title, description: success.description });
            return result;
        } catch (err) {
            _dispatch?.({ op: 'update', id, type: 'error', title: error.title, description: error.description });
            throw err;
        }
    },
};

/* ─────────────────────────────────────────
   Provider
   ───────────────────────────────────────── */
export function PastelToastProvider({ children }) {
    const [toasts, setToasts] = useState([]);

    const dispatch = useCallback((action) => {
        if (action.op === 'add') {
            const id = Date.now() + Math.random();

            // Version 3.0: Compact stacking (limit to 3)
            setToasts(prev => {
                const newToasts = [
                    {
                        id,
                        type: action.type,
                        title: action.title,
                        description: action.description,
                        onClick: action.onClick,
                    },
                    ...prev
                ].slice(0, 3);
                return newToasts;
            });

            if (!action.persist) {
                const duration = action.duration || 3500;
                setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), duration);
            }

            return id;
        }

        if (action.op === 'update') {
            // Update the single active toast
            setToasts(prev => prev.map(t =>
                t.id === action.id
                    ? { ...t, type: action.type, title: action.title, description: action.description }
                    : t
            ));
            // Auto-dismiss after update
            setTimeout(() => setToasts(prev => prev.filter(t => t.id !== action.id)), 4000);
        }
    }, []);

    useEffect(() => { _dispatch = dispatch; }, [dispatch]);

    const remove = (id) => setToasts(prev => prev.filter(t => t.id !== id));

    return (
        <ToastContext.Provider value={{ dispatch }}>
            {children}
            <div className={styles.viewport}>
                <AnimatePresence mode="popLayout">
                    {toasts.map(t => (
                        <ToastItem key={t.id} {...t} onClose={() => remove(t.id)} />
                    ))}
                </AnimatePresence>
            </div>
        </ToastContext.Provider>
    );
}

/* ─────────────────────────────────────────
   SVG Icons
   ───────────────────────────────────────── */
const ICONS = {
    success: (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="20 6 9 17 4 12" />
        </svg>
    ),
    error: (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
        </svg>
    ),
    loading: (
        <svg className={styles.spin} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
            <path d="M21 12a9 9 0 1 1-6.219-8.56" />
        </svg>
    ),
    info: (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="10" />
            <line x1="12" y1="16" x2="12" y2="12" />
            <line x1="12" y1="8" x2="12.01" y2="8" />
        </svg>
    ),
};

/* ─────────────────────────────────────────
   Toast Item
   ───────────────────────────────────────── */
function ToastItem({ id, type, title, description, onClose, onClick }) {
    return (
        <motion.div
            layout
            initial={{ opacity: 0, scale: 0.9, y: -20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.85, transition: { duration: 0.15 } }}
            drag="y"
            dragConstraints={{ top: -50, bottom: 50 }}
            onDragEnd={(_, info) => {
                if (Math.abs(info.offset.y) > 40) onClose();
            }}
            whileTap={{ scale: 0.98 }}
            transition={{
                type: 'spring',
                stiffness: 500,
                damping: 30,
                mass: 1
            }}
            className={`${styles.toast} ${styles[type]}`}
            role="status"
            aria-live="polite"
        >
            <motion.div
                key={type}
                className={`${styles.badge} ${styles[`badge_${type}`]}`}
                initial={{ scale: 0.8, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ type: 'spring', stiffness: 500, damping: 25 }}
            >
                {ICONS[type]}
            </motion.div>

            <div className={styles.content} onClick={() => {
                if (onClick) onClick();
                onClose();
            }}>
                <span className={styles.title}>{title}</span>
                {description && (
                    <span className={styles.description}>{description}</span>
                )}
            </div>

            <button 
                className={styles.closeBtn} 
                onClick={(e) => {
                    e.stopPropagation();
                    onClose();
                }}
                aria-label="Cerrar"
            >
                ✕
            </button>
        </motion.div>
    );
}

import { motion } from 'framer-motion';
import styles from './SegmentedControl.module.css';

export default function SegmentedControl({ tabs, activeTab, onChange }) {
    return (
        <div className={styles.tabsMenu}>
            {tabs.map((tab) => (
                <button
                    key={tab.id}
                    className={`${styles.tabBtn} ${activeTab === tab.id ? styles.activeText : ''}`}
                    onClick={() => onChange(tab.id)}
                >
                    {activeTab === tab.id && (
                        <motion.div
                            layoutId="activeTabIndicator"
                            className={styles.activeTabIndicator}
                            transition={{ type: "spring", stiffness: 400, damping: 30 }}
                        />
                    )}
                    <span className={styles.tabLabel}>{tab.label}</span>
                </button>
            ))}
        </div>
    );
}

import { motion, AnimatePresence } from 'framer-motion';
import { useOfflineQueue } from '../../../hooks/useOfflineQueue';
import styles from './UploadQueueStatus.module.css';

/**
 * UploadQueueStatus — Floating badge showing pending and failed uploads.
 * Redesigned with Clay Chunky aesthetics.
 */
export default function UploadQueueStatus() {
    const { 
        pendingCount, 
        failedCount, 
        isProcessing, 
        retryFailedItems, 
        clearFailedItems 
    } = useOfflineQueue();

    const hasItems = pendingCount > 0 || failedCount > 0 || isProcessing;
    if (!hasItems) return null;

    return (
        <AnimatePresence>
            <motion.div 
                className={styles.root}
                initial={{ opacity: 0, y: 50, scale: 0.9 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: 20, scale: 0.9 }}
            >
                {/* Pending / Processing State */}
                {(pendingCount > 0 || isProcessing) && (
                    <div className={styles.badge}>
                        <span className={styles.icon}>
                            {isProcessing ? (
                                <span className={styles.spinner}>⏳</span>
                            ) : (
                                '📤'
                            )}
                        </span>
                        <span className={styles.text}>
                            {isProcessing
                                ? `Sincronizando...`
                                : `${pendingCount} pendiente${pendingCount > 1 ? 's' : ''}`
                            }
                        </span>
                    </div>
                )}

                {/* Failed State */}
                {failedCount > 0 && (
                    <div className={`${styles.badge} ${styles.failed}`}>
                        <span className={styles.icon}>⚠️</span>
                        <div className={styles.failedContent}>
                            <span className={styles.text}>
                                {failedCount} falló permanentemente
                            </span>
                            <div className={styles.actions}>
                                <button 
                                    onClick={retryFailedItems}
                                    className={styles.retryBtn}
                                    title="Reintentar todo"
                                >
                                    🔄 Reintentar
                                </button>
                                <button 
                                    onClick={clearFailedItems}
                                    className={styles.clearBtn}
                                    title="Limpiar fallidos"
                                >
                                    🗑️ Limpiar
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </motion.div>
        </AnimatePresence>
    );
}

import * as React from "react"
import { cva } from "class-variance-authority";
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props} />
  );
}

