function MapRoute({
  id: propId,
  coordinates,
  color = "#4285F4",
  width = 3,
  opacity = 0.8,
  dashArray,
  onClick,
  onMouseEnter,
  onMouseLeave,
  interactive = true
}) {
  const { map, isLoaded } = useMap();
  const autoId = useId();
  const id = propId ?? autoId;
  const sourceId = `route-source-${id}`;
  const layerId = `route-layer-${id}`;

  // Add source and layer on mount
  useEffect(() => {
    if (!isLoaded || !map) return;

    map.addSource(sourceId, {
      type: "geojson",
      data: {
        type: "Feature",
        properties: {},
        geometry: { type: "LineString", coordinates: [] },
      },
    });

    map.addLayer({
      id: layerId,
      type: "line",
      source: sourceId,
      layout: { "line-join": "round", "line-cap": "round" },
      paint: {
        "line-color": color,
        "line-width": width,
        "line-opacity": opacity,
        ...(dashArray && { "line-dasharray": dashArray }),
      },
    });

    return () => {
      try {
        if (map.getLayer(layerId)) map.removeLayer(layerId);
        if (map.getSource(sourceId)) map.removeSource(sourceId);
      } catch {
        // ignore
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoaded, map]);

  // When coordinates change, update the source data
  useEffect(() => {
    if (!isLoaded || !map || coordinates.length < 2) return;

    const source = map.getSource(sourceId);
    if (source) {
      source.setData({
        type: "Feature",
        properties: {},
        geometry: { type: "LineString", coordinates },
      });
    }
  }, [isLoaded, map, coordinates, sourceId]);

  useEffect(() => {
    if (!isLoaded || !map || !map.getLayer(layerId)) return;

    map.setPaintProperty(layerId, "line-color", color);
    map.setPaintProperty(layerId, "line-width", width);
    map.setPaintProperty(layerId, "line-opacity", opacity);
    if (dashArray) {
      map.setPaintProperty(layerId, "line-dasharray", dashArray);
    }
  }, [isLoaded, map, layerId, color, width, opacity, dashArray]);

  // Handle click and hover events
  useEffect(() => {
    if (!isLoaded || !map || !interactive) return;

    const handleClick = () => {
      onClick?.();
    };
    const handleMouseEnter = () => {
      map.getCanvas().style.cursor = "pointer";
      onMouseEnter?.();
    };
    const handleMouseLeave = () => {
      map.getCanvas().style.cursor = "";
      onMouseLeave?.();
    };

    map.on("click", layerId, handleClick);
    map.on("mouseenter", layerId, handleMouseEnter);
    map.on("mouseleave", layerId, handleMouseLeave);

    return () => {
      map.off("click", layerId, handleClick);
      map.off("mouseenter", layerId, handleMouseEnter);
      map.off("mouseleave", layerId, handleMouseLeave);
    };
  }, [
    isLoaded,
    map,
    layerId,
    onClick,
    onMouseEnter,
    onMouseLeave,
    interactive,
  ]);

  return null;
}

function MapClusterLayer(
  {
    data,
    clusterMaxZoom = 14,
    clusterRadius = 50,
    clusterColors = ["#22c55e", "#eab308", "#ef4444"],
    clusterThresholds = [100, 750],
    pointColor = "#3b82f6",
    onPointClick,
    onClusterClick
  }
) {
  const { map, isLoaded } = useMap();
  const id = useId();
  const sourceId = `cluster-source-${id}`;
  const clusterLayerId = `clusters-${id}`;
  const clusterCountLayerId = `cluster-count-${id}`;
  const unclusteredLayerId = `unclustered-point-${id}`;

  const stylePropsRef = useRef({
    clusterColors,
    clusterThresholds,
    pointColor,
  });

  // Add source and layers on mount
  useEffect(() => {
    if (!isLoaded || !map) return;

    // Add clustered GeoJSON source
    map.addSource(sourceId, {
      type: "geojson",
      data,
      cluster: true,
      clusterMaxZoom,
      clusterRadius,
    });

    // Add cluster circles layer
    map.addLayer({
      id: clusterLayerId,
      type: "circle",
      source: sourceId,
      filter: ["has", "point_count"],
      paint: {
        "circle-color": [
          "step",
          ["get", "point_count"],
          clusterColors[0],
          clusterThresholds[0],
          clusterColors[1],
          clusterThresholds[1],
          clusterColors[2],
        ],
        "circle-radius": [
          "step",
          ["get", "point_count"],
          20,
          clusterThresholds[0],
          30,
          clusterThresholds[1],
          40,
        ],
        "circle-stroke-width": 1,
        "circle-stroke-color": "#fff",
        "circle-opacity": 0.85,
      },
    });

    // Add cluster count text layer
    map.addLayer({
      id: clusterCountLayerId,
      type: "symbol",
      source: sourceId,
      filter: ["has", "point_count"],
      layout: {
        "text-field": "{point_count_abbreviated}",
        "text-font": ["Open Sans"],
        "text-size": 12,
      },
      paint: {
        "text-color": "#fff",
      },
    });

    // Add unclustered point layer
    map.addLayer({
      id: unclusteredLayerId,
      type: "circle",
      source: sourceId,
      filter: ["!", ["has", "point_count"]],
      paint: {
        "circle-color": pointColor,
        "circle-radius": 5,
        "circle-stroke-width": 2,
        "circle-stroke-color": "#fff",
      },
    });

    return () => {
      try {
        if (map.getLayer(clusterCountLayerId))
          map.removeLayer(clusterCountLayerId);
        if (map.getLayer(unclusteredLayerId))
          map.removeLayer(unclusteredLayerId);
        if (map.getLayer(clusterLayerId)) map.removeLayer(clusterLayerId);
        if (map.getSource(sourceId)) map.removeSource(sourceId);
      } catch {
        // ignore
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLoaded, map, sourceId]);

  // Update source data when data prop changes (only for non-URL data)
  useEffect(() => {
    if (!isLoaded || !map || typeof data === "string") return;

    const source = map.getSource(sourceId);
    if (source) {
      source.setData(data);
    }
  }, [isLoaded, map, data, sourceId]);

  // Update layer styles when props change
  useEffect(() => {
    if (!isLoaded || !map) return;

    const prev = stylePropsRef.current;
    const colorsChanged =
      prev.clusterColors !== clusterColors ||
      prev.clusterThresholds !== clusterThresholds;

    // Update cluster layer colors and sizes
    if (map.getLayer(clusterLayerId) && colorsChanged) {
      map.setPaintProperty(clusterLayerId, "circle-color", [
        "step",
        ["get", "point_count"],
        clusterColors[0],
        clusterThresholds[0],
        clusterColors[1],
        clusterThresholds[1],
        clusterColors[2],
      ]);
      map.setPaintProperty(clusterLayerId, "circle-radius", [
        "step",
        ["get", "point_count"],
        20,
        clusterThresholds[0],
        30,
        clusterThresholds[1],
        40,
      ]);
    }

    // Update unclustered point layer color
    if (map.getLayer(unclusteredLayerId) && prev.pointColor !== pointColor) {
      map.setPaintProperty(unclusteredLayerId, "circle-color", pointColor);
    }

    stylePropsRef.current = { clusterColors, clusterThresholds, pointColor };
  }, [
    isLoaded,
    map,
    clusterLayerId,
    unclusteredLayerId,
    clusterColors,
    clusterThresholds,
    pointColor,
  ]);

  // Handle click events
  useEffect(() => {
    if (!isLoaded || !map) return;

    // Cluster click handler - zoom into cluster
    const handleClusterClick = async (
      e
    ) => {
      const features = map.queryRenderedFeatures(e.point, {
        layers: [clusterLayerId],
      });
      if (!features.length) return;

      const feature = features[0];
      const clusterId = feature.properties?.cluster_id;
      const pointCount = feature.properties?.point_count;
      const coordinates = feature.geometry.coordinates;

      if (onClusterClick) {
        onClusterClick(clusterId, coordinates, pointCount);
      } else {
        // Default behavior: zoom to cluster expansion zoom
        const source = map.getSource(sourceId);
        const zoom = await source.getClusterExpansionZoom(clusterId);
        map.easeTo({
          center: coordinates,
          zoom,
        });
      }
    };

    // Unclustered point click handler
    const handlePointClick = (
      e
    ) => {
      if (!onPointClick || !e.features?.length) return;

      const feature = e.features[0];
      const coordinates = (
        feature.geometry
      ).coordinates.slice();

      // Handle world copies
      while (Math.abs(e.lngLat.lng - coordinates[0]) > 180) {
        coordinates[0] += e.lngLat.lng > coordinates[0] ? 360 : -360;
      }

      onPointClick(feature, coordinates);
    };

    // Cursor style handlers
    const handleMouseEnterCluster = () => {
      map.getCanvas().style.cursor = "pointer";
    };
    const handleMouseLeaveCluster = () => {
      map.getCanvas().style.cursor = "";
    };
    const handleMouseEnterPoint = () => {
      if (onPointClick) {
        map.getCanvas().style.cursor = "pointer";
      }
    };
    const handleMouseLeavePoint = () => {
      map.getCanvas().style.cursor = "";
    };

    map.on("click", clusterLayerId, handleClusterClick);
    map.on("click", unclusteredLayerId, handlePointClick);
    map.on("mouseenter", clusterLayerId, handleMouseEnterCluster);
    map.on("mouseleave", clusterLayerId, handleMouseLeaveCluster);
    map.on("mouseenter", unclusteredLayerId, handleMouseEnterPoint);
    map.on("mouseleave", unclusteredLayerId, handleMouseLeavePoint);

    return () => {
      map.off("click", clusterLayerId, handleClusterClick);
      map.off("click", unclusteredLayerId, handlePointClick);
      map.off("mouseenter", clusterLayerId, handleMouseEnterCluster);
      map.off("mouseleave", clusterLayerId, handleMouseLeaveCluster);
      map.off("mouseenter", unclusteredLayerId, handleMouseEnterPoint);
      map.off("mouseleave", unclusteredLayerId, handleMouseLeavePoint);
    };
  }, [
    isLoaded,
    map,
    clusterLayerId,
    unclusteredLayerId,
    sourceId,
    onClusterClick,
    onPointClick,
  ]);

  return null;
}

export {
  Map,
  useMap,
  MapMarker,
  MarkerContent,
  MarkerPopup,
  MarkerTooltip,
  MarkerLabel,
  MapPopup,
  MapControls,
  MapRoute,
  MapClusterLayer,
};

import { createContext, useContext, useState, useEffect, useMemo } from 'react';
import { doc, onSnapshot } from 'firebase/firestore';
import { db } from '../services/firebase';
import { COLLECTIONS, SINGLETON_DOCS } from '../config/constants';
import SystemConfig from '../models/SystemConfig';
import { openDB } from '../config/dbConfig';

const APP_CONFIG_CACHE_KEY = 'system_config';

const AppConfigContext = createContext(null);

/**
 * App Config Provider — reads /appConfig/main from Firestore in real-time.
 */
export function AppConfigProvider({ children }) {
    const [config, setConfig] = useState(new SystemConfig());
    const [isConfigLoaded, setIsConfigLoaded] = useState(false);

    useEffect(() => {
        const configRef = doc(
            db,
            COLLECTIONS.APP_CONFIG,
            SINGLETON_DOCS.APP_CONFIG
        );

        // Load from cache first
        const loadCache = async () => {
            try {
                const idb = await openDB();
                const tx = idb.transaction('app_cache', 'readonly');
                const store = tx.objectStore('app_cache');
                const req = store.get(APP_CONFIG_CACHE_KEY);
                req.onsuccess = () => {
                    if (req.result?.data) {
                        console.log('[AppConfig] Loaded from IndexedDB');
                        setConfig(SystemConfig.fromFirestore(req.result.data));
                        setIsConfigLoaded(true);
                    }
                };
            } catch (err) {
                console.warn('[AppConfig] IndexedDB Cache Error:', err);
            }
        };
        loadCache();

        const unsubscribe = onSnapshot(
            configRef,
            async (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.data();
                    const newConfig = SystemConfig.fromFirestore(data);
                    setConfig(newConfig);
                    
                    // Persist to IndexedDB
                    try {
                        const idb = await openDB();
                        const tx = idb.transaction('app_cache', 'readwrite');
                        tx.objectStore('app_cache').put({ 
                            key: APP_CONFIG_CACHE_KEY, 
                            data, 
                            savedAt: Date.now() 
                        });
                    } catch (err) {
                        console.warn('[AppConfig] Failed to cache to IndexedDB:', err);
                    }
                } else {
                    setConfig(new SystemConfig());
                }
                setIsConfigLoaded(true);
            },
            (error) => {
                console.warn('[AppConfig] Firestore unavailable:', error.code);
                // If not already loaded from cache, we'll keep the defaults
                setIsConfigLoaded(true);
            }
        );

        return unsubscribe;
    }, []);

    const value = useMemo(() => ({
        ...config,
        isConfigLoaded,
        /**
         * Check if a feature is enabled
         * @param {string} featureName
         * @returns {boolean}
         */
        isFeatureOn: (featureName) => config.isFeatureOn(featureName),
    }), [config, isConfigLoaded]);

    return (
        <AppConfigContext.Provider value={value}>
            {children}
        </AppConfigContext.Provider>
    );
}

/**
 * Hook to access app config
 * @returns {{ features, visibility, wrappedConfig, mapConfig, notifications, isConfigLoaded, isFeatureOn }}
 */
export function useAppConfig() {
    const context = useContext(AppConfigContext);
    if (context === null) {
        throw new Error('useAppConfig must be used within an AppConfigProvider');
    }
    return context;
}

export default AppConfigContext;

import { createContext, useContext, useState, useEffect, useMemo, useCallback } from 'react';
import { onAuthStateChanged } from 'firebase/auth';
import { getToken, onMessage } from 'firebase/messaging';
import { arrayUnion, doc, updateDoc, onSnapshot } from 'firebase/firestore';
import { auth, messaging, db } from '../services/firebase';
import firebaseConfig from '../config/firebase';
import {
    getCurrentUserClaims,
    signOut as authSignOut,
} from '../services/auth';
import { ROLES, COLLECTIONS } from '../config/constants';
import User from '../models/User';
import { toast } from '../components/ui/PastelToast/PastelToast';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
    const [user, setUser] = useState(null);
    const [role, setRole] = useState(null);
    const [deviceId, setDeviceId] = useState(null);
    const [onboardingCompleted, setOnboardingCompleted] = useState(null);
    const [welcomeSeen, setWelcomeSeen] = useState(null);
    const [teaserCompleted, setTeaserCompleted] = useState(null);
    const [gameCoins, setGameCoins] = useState(0);
    const [isLoading, setIsLoading] = useState(true);

    // Register FCM Token for partners
    const registerFCM = useCallback(async (userId) => {
        try {
            // SKIP FCM in emulator mode to avoid logs and SW evaluation errors
            if (import.meta.env.VITE_USE_EMULATORS === 'true') {
                console.log('[Auth] FCM skipping in emulator mode');
                return;
            }

            // Wait for messaging to be initialized (it's lazy in firebase.js)
            let messagingInstance = messaging;
            if (!messagingInstance) {
                const { isSupported, getMessaging } = await import('firebase/messaging');
                if (await isSupported()) {
                    const { app } = await import('../services/firebase');
                    messagingInstance = getMessaging(app);
                }
            }

            if (!messagingInstance) return;

            const token = await getToken(messagingInstance, {
                vapidKey: firebaseConfig.vapidKey
            });
            if (token) {
                const userRef = doc(db, COLLECTIONS.USERS, userId);
                await updateDoc(userRef, {
                    fcmTokens: arrayUnion(token)
                });
            }
        } catch (err) {
            console.error('FCM Registration failed:', err);
        }
    }, []);

    useEffect(() => {
        let unsubscribeDoc = () => { };

        const unsubscribeAuth = onAuthStateChanged(auth, async (firebaseUser) => {
            // Clean up previous doc listener if user changes
            unsubscribeDoc();

            if (firebaseUser) {
                setIsLoading(true); // Ensure stays loading while getting claims
                let claims = { role: null, deviceId: null };
                try {
                    claims = await getCurrentUserClaims(true);
                } catch (err) {
                    console.error('[Auth] Error fetching claims:', err);
                }

                setUser(firebaseUser);
                setRole(claims.role);
                setDeviceId(claims.deviceId);
                console.log('[Auth] User identified:', { uid: firebaseUser.uid, role: claims.role, deviceId: claims.deviceId });

                // Start real-time listener for user document
                const userRef = doc(db, COLLECTIONS.USERS, firebaseUser.uid);
                unsubscribeDoc = onSnapshot(userRef, (snapshot) => {
                    let data = {};
                    if (snapshot.exists()) {
                        data = snapshot.data();
                    } else {
                        // Fallback to User model defaults
                        const defaultUser = new User({ uid: firebaseUser.uid });
                        data = {
                            onboardingCompleted: defaultUser.onboardingCompleted,
                            welcomeSeen: defaultUser.welcomeSeen,
                            teaserCompleted: defaultUser.teaserCompleted
                        };
                    }

                    setOnboardingCompleted(data.onboardingCompleted ?? null);
                    setWelcomeSeen(data.welcomeSeen ?? false);
                    setTeaserCompleted(data.teaserCompleted ?? false);
                    setGameCoins(data.gameCoins ?? 0);

                    // Fallback: If role wasn't in claims, take it from Firestore
                    if (!claims.role && data.role) {
                        console.log('[Auth] Role fallback from Firestore:', data.role);
                        setRole(data.role);
                    }
                    
                    setIsLoading(false); // Only stop loading after doc is loaded
                }, (err) => {
                    console.error('[Auth] User document listener error:', err);
                    setIsLoading(false);
                });

                // If partner, try registering FCM
                if (claims.role === ROLES.PARTNER) {
                    registerFCM(firebaseUser.uid);
                }
            } else {
                setUser(null);
                setRole(null);
                setDeviceId(null);
                setOnboardingCompleted(null);
                setWelcomeSeen(null);
                setTeaserCompleted(null);
                setGameCoins(0);
                setIsLoading(false); // No user, stop loading
            }
        });

        // Listen for foreground messages
        let unsubscribeMessaging = () => { };

        const setupMessagingListener = async () => {
            let messagingInstance = messaging;
            if (!messagingInstance) {
                const { isSupported, getMessaging } = await import('firebase/messaging');
                if (await isSupported()) {
                    const { app } = await import('../services/firebase');
                    messagingInstance = getMessaging(app);
                }
            }

            if (messagingInstance) {
                unsubscribeMessaging = onMessage(messagingInstance, (payload) => {
                    console.log('Message received in foreground: ', payload);
                    try {
                        const { title, body } = payload.notification || {};
                        if (title || body) {
                            toast.info(title || 'Nueva notificación', body || '');
                        }
                    } catch (err) {
                        console.error('[AuthContext] Failed to show foreground toast:', err);
                    }
                });
            }
        };

        setupMessagingListener();

        return () => {
            unsubscribeAuth();
            unsubscribeDoc();
            unsubscribeMessaging();
        };
    }, [registerFCM]);

    const signOut = useCallback(() => authSignOut(), []);

    const value = useMemo(() => ({
        user,
        role,
        deviceId,
        onboardingCompleted,
        welcomeSeen,
        teaserCompleted,
        gameCoins,
        isLoading,
        isAuthenticated: !!user,
        isAdmin: role === ROLES.ADMIN,
        isPartner: role === ROLES.PARTNER,
        signOut,
    }), [user, role, deviceId, onboardingCompleted, welcomeSeen, teaserCompleted, gameCoins, isLoading, signOut]);

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (context === null) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
}

export default AuthContext;

import { createContext, useContext, useCallback, useEffect, useRef, useState } from 'react';
import {
    doc,
    onSnapshot,
    updateDoc,
    setDoc,
    increment,
    arrayUnion,
    serverTimestamp,
} from 'firebase/firestore';
import { db as firestoreDb } from '../services/firebase';
import { useAuth } from '../hooks/useAuth';
import { useOfflineActions } from '../hooks/useOfflineActions';
import { logActivity } from '../apiClient';
import { COLLECTIONS, SINGLETON_DOCS } from '../config/constants';
import { toast } from '../components/ui/PastelToast/PastelToast';
import BingoAction from '../models/BingoAction';
import { openDB } from '../config/dbConfig';

const BingoContext = createContext();

const BINGO_CACHE_KEY = 'bingo_board_cache';

async function saveBingoCache(boardData) {
    try {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction('app_cache', 'readwrite');
            tx.objectStore('app_cache').put({ key: BINGO_CACHE_KEY, data: boardData, savedAt: Date.now() });
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error);
        });
    } catch { /* falla silenciosa */ }
}

async function loadBingoCache() {
    try {
        const db = await openDB();
        return new Promise((resolve) => {
            const tx = db.transaction('app_cache', 'readonly');
            const req = tx.objectStore('app_cache').get(BINGO_CACHE_KEY);
            req.onsuccess = () => resolve(req.result?.data ?? null);
            req.onerror = () => resolve(null);
        });
    } catch { return null; }
}

const boardRef = doc(firestoreDb, COLLECTIONS.BINGO_BOARD, SINGLETON_DOCS.BINGO_BOARD);

export function BingoProvider({ children }) {
    const [categories, setCategories] = useState([]);
    const [completedCount, setCompletedCount] = useState(0);
    const [totalCount, setTotalCount] = useState(16);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const { user } = useAuth();

    const { queueAction } = useOfflineActions();
    const optimisticPending = useRef(new Set());
    const [celebrationEvent, setCelebrationEvent] = useState(null);
    const [irisEvent, setIrisEvent] = useState(false);

    const triggerIris = useCallback(() => {
        setIrisEvent(true);
        setTimeout(() => setIrisEvent(false), 4500); // Cinematic duration
    }, []);

    const clearCelebrationEvent = useCallback(() => setCelebrationEvent(null), []);

    const checkBingoAchievements = useCallback(async (prevCats, nextCats, categoryId) => {
        if (!user) return;

        const ROWS = 4;
        const COLS = 4;

        // 1. Detection Logic
        const getLinesDetails = (cats) => {
            const lines = [];
            // Rows
            for (let r = 0; r < ROWS; r++) {
                let rowFull = true;
                for (let c = 0; c < COLS; c++) {
                    if (!cats[r * COLS + c].completedMemoryId) { rowFull = false; break; }
                }
                if (rowFull) lines.push({ type: 'line', label: `Fila ${r + 1} ✅`, coins: 15 });
            }
            // Cols
            for (let c = 0; c < COLS; c++) {
                let colFull = true;
                for (let r = 0; r < ROWS; r++) {
                    if (!cats[r * COLS + c].completedMemoryId) { colFull = false; break; }
                }
                if (colFull) lines.push({ type: 'line', label: `Columna ${c + 1} ✅`, coins: 15 });
            }
            // Diagonals (4x4 indices: 0,5,10,15 and 3,6,9,12)
            if ([0, 5, 10, 15].every(i => cats[i]?.completedMemoryId)) {
                lines.push({ type: 'diagonal', label: 'Diagonal Principal ✅', coins: 15 });
            }
            if ([3, 6, 9, 12].every(i => cats[i]?.completedMemoryId)) {
                lines.push({ type: 'diagonal', label: 'Diagonal Secundaria ✅', coins: 15 });
            }
            return lines;
        };

        const prevLines = getLinesDetails(prevCats);
        const nextLines = getLinesDetails(nextCats);

        // Find NEW lines by filtering those that weren't in prev
        // Using label and type as key
        const newAchievements = nextLines.filter(nl => 
            !prevLines.some(pl => pl.label === nl.label && pl.type === nl.type)
        );

        const isBoardFull = nextCats.every(c => c.completedMemoryId);
        const wasBoardFull = prevCats.every(c => c.completedMemoryId);

        if (isBoardFull && !wasBoardFull) {
            newAchievements.push({ type: 'full_board', label: '¡TABLERO COMPLETO! 🏆', coins: 50 });
        }

        // Special Square Logic (+5)
        if (categoryId) {
            const square = nextCats.find(c => c.id === categoryId);
            const wasSquareComplete = prevCats.find(c => c.id === categoryId)?.completedMemoryId;
            if (square?.isSpecial && !wasSquareComplete) {
                newAchievements.push({ type: 'special', label: 'Casilla Especial ✨', coins: 5 });
            }
        }

        if (newAchievements.length > 0) {
            const totalCoins = newAchievements.reduce((sum, ac) => sum + ac.coins, 0);

            try {
                const userRef = doc(firestoreDb, COLLECTIONS.USERS, user.uid);

                // Register EACH transaction separately for auditing
                const newTransactions = newAchievements.map(ac => ({
                    type: "earned",
                    source: `bingo_${ac.type}`,
                    label: ac.label,
                    amount: ac.coins,
                    timestamp: new Date().toISOString()
                }));

                await updateDoc(userRef, {
                    gameCoins: increment(totalCoins),
                    coinTransactions: arrayUnion(...newTransactions)
                });

                if (isBoardFull && !wasBoardFull) {
                    logActivity({ 
                        action: 'bingoBoardCompleted', 
                        targetType: 'bingo',
                        targetId: SINGLETON_DOCS.BINGO_BOARD,
                        displayText: '¡Completó el tablero de Bingo! 🎯',
                        metadata: { 
                            userId: user.uid,
                            timestamp: new Date().toISOString() 
                        }
                    });
                }

                // Prepare event for overlay
                setCelebrationEvent({
                    isCombo: newAchievements.length > 1,
                    achievements: newAchievements,
                    totalCoins,
                    tierLabel: newAchievements.length > 1 ? '¡COMBO ÉPICO! 🎊' : newAchievements[0].label,
                    reward: isBoardFull && !wasBoardFull ? '¡Tablero completado! Se reseteará automáticamente.' : '¡Tus monedas han sido añadidas! ✨',
                    isFullBoard: isBoardFull && !wasBoardFull
                });
            } catch (err) {
                console.error('[BingoContext] Error updating rewards:', err);
            }
        }
    }, [user]);


    const applyServerState = useCallback((data) => {
        if (!data) return;

        setCategories(prev => {
            if (optimisticPending.current.size > 0) {
                const merged = (data.categories || []).map(serverCat => {
                    const localCat = prev.find(c => c.id === serverCat.id);
                    if (localCat?.completedMemoryId && !serverCat.completedMemoryId) {
                        return localCat;
                    }
                    return serverCat;
                });
                return merged;
            }
            return data.categories || [];
        });

        setCompletedCount(data.completedCount ?? 0);
        setTotalCount(data.totalCount ?? 20);
        saveBingoCache(data);
    }, []);

    useEffect(() => {
        let unsubscribe = null;
        setIsLoading(true);

        const init = async () => {
            const cached = await loadBingoCache();
            if (cached) {
                applyServerState(cached);
                setIsLoading(false);
            }

            if (navigator.onLine) {
                try {
                    unsubscribe = onSnapshot(
                        boardRef,
                        (snap) => {
                            if (snap.exists()) {
                                applyServerState(snap.data());
                            }
                            setIsLoading(false);
                            setError(null);
                        },
                        (err) => {
                            console.error('[BingoProvider] Error en snapshot:', err);
                            setError(err.message);
                            setIsLoading(false);
                        }
                    );
                } catch (err) {
                    setError(err.message);
                    setIsLoading(false);
                }
            } else {
                if (!cached) setError('Sin conexión y sin datos guardados localmente.');
                setIsLoading(false);
            }
        };

        init();

        const handleOnline = () => {
            if (!unsubscribe) {
                unsubscribe = onSnapshot(boardRef, (snap) => {
                    if (snap.exists()) applyServerState(snap.data());
                });
            }
        };

        window.addEventListener('online', handleOnline);
        return () => {
            unsubscribe?.();
            window.removeEventListener('online', handleOnline);
        };
    }, [applyServerState]);

    const markComplete = useCallback(async (categoryId, memoryId = null) => {
        const existing = categories.find(c => c.id === categoryId);
        if (!existing) return { success: false, error: 'Categoría no encontrada' };
        if (existing.completedMemoryId) return { success: false, error: 'Casilla ya completada' };

        const completedAt = new Date().toISOString();

        try {
            const action = new BingoAction({ categoryId, memoryId, completedAt });
            const payload = action.toQueuePayload();

            optimisticPending.current.add(categoryId);
            setCategories(prev => {
                const nextCats = prev.map(cat =>
                    cat.id === categoryId
                        ? { ...cat, completedMemoryId: memoryId || 'pending', completedAt }
                        : cat
                );
                checkBingoAchievements(prev, nextCats, categoryId);
                return nextCats;
            });
            setCompletedCount(prev => prev + 1);

            const { queued, id: actionId } = await queueAction('bingo_completion', payload);

            if (navigator.onLine) {
                toast.success('¡Bingo! 🎉', `Casilla "${existing.title || existing.label || 'Casilla'}" marcada`);
            } else {
                toast.info('Guardado offline 📱', 'Se sincronizará cuando tengas conexión');
            }

            setTimeout(() => {
                optimisticPending.current.delete(categoryId);
            }, 10000);

            return { success: true, queued, actionId };
        } catch (err) {
            console.error('[BingoProvider] Error al encolar acción:', err);
            toast.error('Error', err.message);
            return { success: false, error: err.message };
        }
    }, [categories, queueAction, checkBingoAchievements]);

    const markBatchComplete = useCallback(async (categoryIds, memoryId = null) => {
        if (!categoryIds || categoryIds.length === 0) return;

        const completedAt = new Date().toISOString();
        const existingCats = categories;

        try {
            optimisticPending.current = new Set([...optimisticPending.current, ...categoryIds]);

            setCategories(prev => {
                const nextCats = prev.map(cat => 
                    categoryIds.includes(cat.id)
                        ? { ...cat, completedMemoryId: memoryId || 'pending', completedAt }
                        : cat
                );
                // Trigger achievements ONCE for the whole batch
                checkBingoAchievements(prev, nextCats, categoryIds[0]); 
                return nextCats;
            });

            setCompletedCount(prev => prev + categoryIds.length);

            // Queue each one
            for (const catId of categoryIds) {
                const action = new BingoAction({ categoryId: catId, memoryId, completedAt });
                queueAction('bingo_completion', action.toQueuePayload());
            }

            toast.success('¡Bingo! 🎉', `Has completado ${categoryIds.length} casillas`);

            setTimeout(() => {
                categoryIds.forEach(id => optimisticPending.current.delete(id));
            }, 10000);

            return { success: true };
        } catch (err) {
            console.error('[BingoProvider] Error in batch mark:', err);
            return { success: false, error: err.message };
        }
    }, [categories, queueAction, checkBingoAchievements]);

    const isCategoryComplete = useCallback((categoryId) => {
        return categories.find(c => c.id === categoryId)?.completedMemoryId != null;
    }, [categories]);

    const isCategoryAvailable = useCallback((categoryId) => {
        return !isCategoryComplete(categoryId);
    }, [isCategoryComplete]);

    const getCategory = useCallback((categoryId) => {
        return categories.find(c => c.id === categoryId) ?? null;
    }, [categories]);

    const updateBingoBoard = useCallback(async (newCategories) => {
        try {
            setIsLoading(true);
            await updateDoc(boardRef, {
                categories: newCategories,
                updatedAt: serverTimestamp()
            });
            toast.success('¡Tablero Guardado! 🎯', 'Los retos han sido actualizados.');
            return { success: true };
        } catch (err) {
            console.error('[BingoProvider] Error al guardar tablero:', err);
            toast.error('Error al guardar', err.message);
            return { success: false, error: err.message };
        } finally {
            setIsLoading(false);
        }
    }, []);

    const availableTags = categories.reduce((acc, cat) => {
        const catTags = (cat.suggestedTags || []).map(t => {
            if (typeof t === 'string') return { value: t, label: t.charAt(0).toUpperCase() + t.slice(1) };
            return t; // It's already an object {value, label}
        });

        catTags.forEach(tag => {
            if (!acc.find(item => item.value === tag.value)) {
                acc.push(tag);
            }
        });
        return acc;
    }, []);

    const progressPercent = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

    const value = {
        categories,
        availableTags,
        completedCount,
        totalCount,
        progressPercent,
        isLoading,
        error,
        markBatchComplete,
        markComplete,
        completeBingoSquare: markComplete,
        isCategoryComplete,
        isCategoryAvailable,
        getCategory,
        updateBingoBoard,
        resetBingoBoard: useCallback(async () => {
            if (!categories.length) return;

            // 1. Archive current board
            try {
                const historyId = `${SINGLETON_DOCS.BINGO_BOARD}_${Date.now()}`;
                await setDoc(doc(firestoreDb, COLLECTIONS.BINGO_HISTORY, historyId), {
                    categories,
                    completedCount,
                    totalCount,
                    archivedAt: new Date().toISOString(),
                    userId: user?.uid
                });

                // 2. Clear current board
                const resetCats = categories.map(c => ({
                    ...c,
                    completedMemoryId: null,
                    completedAt: null
                }));

                await updateDoc(boardRef, {
                    categories: resetCats,
                    completedCount: 0,
                    updatedAt: serverTimestamp()
                });

                // Cinematic Iris Transition
                triggerIris();

                toast.info('Tablero reseteado 🔄', '¡Es hora de nuevos retos!');
            } catch (err) {
                console.error('[BingoContext] Error resetting board:', err);
                toast.error('Error al resetear board', err.message);
            }
        }, [categories, completedCount, totalCount, user, triggerIris]),
        celebrationEvent,
        clearCelebrationEvent: () => setCelebrationEvent(null),
        irisEvent,
        triggerIris
    };

    return (
        <BingoContext.Provider value={value}>
            {children}
        </BingoContext.Provider>
    );
}

export const useBingoContext = () => {
    const context = useContext(BingoContext);
    if (!context) {
        throw new Error('useBingoContext must be used within a BingoProvider');
    }
    return context;
};

