/**
 * useCoupons.js
 * 
 * Hook to manage coupons in real-time.
 */

import { useState, useEffect, useCallback } from 'react';
import { 
    collection, 
    onSnapshot, 
    query, 
    where, 
    orderBy, 
    doc, 
    addDoc,
    updateDoc, 
    deleteDoc,
    serverTimestamp 
} from 'firebase/firestore';
import { db } from '../services/firebase';
import { COLLECTIONS } from '../config/constants';
import Coupon from '../models/Coupon';
import { useOfflineActions } from './useOfflineActions';
import { useAuth } from './useAuth';
import { toast } from '../components/ui/PastelToast/PastelToast';

export function useCoupons({ adminMode = false } = {}) {
    const { user } = useAuth();
    const [coupons, setCoupons] = useState([]);
    const [redemptions, setRedemptions] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const { queueAction } = useOfflineActions();

    useEffect(() => {
        const couponsRef = collection(db, COLLECTIONS.COUPONS);

        let constraints = [orderBy('createdAt', 'desc')];
        if (!adminMode) {
            constraints.push(where('isActive', '==', true));
        }

        const q = query(couponsRef, ...constraints);

        const unsubscribeCoupons = onSnapshot(q, (snapshot) => {
            const list = snapshot.docs.map(doc => Coupon.fromFirestore(doc));
            setCoupons(list);
            setIsLoading(false);
        }, (err) => {
            console.error('[useCoupons] Coupons Error:', err);
            setError(err.message);
            setIsLoading(false);
        });

        // If not admin, also fetch redemptions for the current user
        let unsubscribeRedemptions = () => {};
        if (!adminMode && user?.uid) {
            const redemptionsRef = collection(db, 'redemptions');
            const userRedemptionsQuery = query(
                redemptionsRef, 
                where('userId', '==', user.uid), 
                orderBy('requestedAt', 'desc')
            );

            unsubscribeRedemptions = onSnapshot(userRedemptionsQuery, (snapshot) => {
                const list = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
                setRedemptions(list);
            });
        }

        return () => {
            unsubscribeCoupons();
            unsubscribeRedemptions();
        };
    }, [adminMode, user?.uid]);

    const redeemCoupon = useCallback(async (couponId, notes = '') => {
        if (!user?.uid) return { success: false, error: 'Auth required' };
        try {
            // New logic: Create a redemption record with status 'pending_approval'
            const redemptionData = {
                userId: user.uid,
                couponId,
                status: 'pending_approval',
                requestedAt: serverTimestamp(),
                note: notes || null
            };

            await addDoc(collection(db, 'redemptions'), redemptionData);
            toast.success('Solicitud enviada 💌', 'Admin lo revisará pronto ✨');
            return { success: true };
        } catch (err) {
            console.error('[useCoupons] Error redeeming:', err);
            toast.error('Error al solicitar canje');
            return { success: false, error: err.message };
        }
    }, [user?.uid]);

    const assignCouponDirectly = useCallback(async (couponId, targetUserId) => {
        if (!user?.uid) throw new Error('Auth required');
        try {
            const redemptionData = {
                userId: targetUserId,
                couponId,
                status: 'assigned',
                requestedAt: serverTimestamp(),
                assignedAt: serverTimestamp(),
                assignedBy: user.uid
            };

            await addDoc(collection(db, 'redemptions'), redemptionData);
            return { success: true };
        } catch (err) {
            console.error('[useCoupons] Error assigning:', err);
            throw err;
        }
    }, [user?.uid]);

    const claimRedemption = useCallback(async (redemptionId) => {
        try {
            const redemptionRef = doc(db, 'redemptions', redemptionId);
            await updateDoc(redemptionRef, {
                status: 'claimed',
                claimedAt: serverTimestamp()
            });

            // Update redemptionsLeft in coupon
            // Need to get couponId first from somewhere or pass it
            return { success: true };
        } catch (err) {
            toast.error('Error al marcar como cobrado');
            return { success: false };
        }
    }, []);

    const createCoupon = useCallback(async (couponData) => {
        try {
            const docRef = await addDoc(collection(db, COLLECTIONS.COUPONS), {
                ...couponData,
                status: 'activo',
                createdAt: serverTimestamp()
            });
            return { success: true, id: docRef.id };
        } catch (err) {
            console.error('[useCoupons] Error creating:', err);
            throw err;
        }
    }, []);

    const updateCoupon = useCallback(async (id, data) => {
        try {
            const couponRef = doc(db, COLLECTIONS.COUPONS, id);
            await updateDoc(couponRef, {
                ...data,
                updatedAt: serverTimestamp()
            });
            return { success: true };
        } catch (err) {
            console.error('[useCoupons] Error updating:', err);
            throw err;
        }
    }, []);

    const deleteCoupon = useCallback(async (id) => {
        try {
            const couponRef = doc(db, COLLECTIONS.COUPONS, id);
            await deleteDoc(couponRef);
            return { success: true };
        } catch (err) {
            console.error('[useCoupons] Error deleting:', err);
            throw err;
        }
    }, []);

    return {
        coupons,
        redemptions,
        isLoading,
        error,
        redeemCoupon,
        assignCouponDirectly,
        claimRedemption,
        createCoupon,
        updateCoupon,
        deleteCoupon
    };
}

/**
 * useOfflineActions.js
 * 
 * Motor genérico para acciones offline que NO involucran archivos.
 * Maneja operaciones como marcar Bingo, registrar ejercicio, etc.
 * 
 * Separado de useOfflineQueue (que maneja fotos/blobs) para evitar
 * inflar ese hook con lógica de Firestore pura.
 * 
 * IndexedDB Store: 'pending_actions' en 'capsule_offline_queue' (misma DB)
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import {
    doc,
    updateDoc,
    setDoc,
    getDoc,
    arrayUnion,
    increment,
    serverTimestamp,
    getFirestore,
    collection,
} from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { toast } from '../components/ui/PastelToast/PastelToast';
import { COLLECTIONS, SINGLETON_DOCS } from '../config/constants';

// ─────────────────────────────────────────────────────────────────────────────
// IndexedDB — reutiliza la misma DB que useOfflineQueue
// ─────────────────────────────────────────────────────────────────────────────

import { openDB } from '../config/dbConfig';
const ACTION_STORE = 'pending_actions';

async function saveAction(action) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(ACTION_STORE, 'readwrite');
        tx.objectStore(ACTION_STORE).put(action);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

async function getPendingActions() {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(ACTION_STORE, 'readonly');
        const req = tx.objectStore(ACTION_STORE).getAll();
        req.onsuccess = () => {
            const all = req.result || [];
            resolve(all.filter(a => a.status === 'pending' || a.status === 'processing'));
        };
        req.onerror = () => reject(req.error);
    });
}

async function updateAction(id, updates) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(ACTION_STORE, 'readwrite');
        const store = tx.objectStore(ACTION_STORE);
        const getReq = store.get(id);
        getReq.onsuccess = () => {
            if (!getReq.result) return;
            store.put({ ...getReq.result, ...updates });
        };
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

async function removeAction(id) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(ACTION_STORE, 'readwrite');
        tx.objectStore(ACTION_STORE).delete(id);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

// ─────────────────────────────────────────────────────────────────────────────
// Procesadores por tipo de acción
// ─────────────────────────────────────────────────────────────────────────────

const db = getFirestore();

/**
 * Procesa una acción de completar casilla de bingo.
 */
async function processBingoCompletion(action) {
    const { categoryId, memoryId, completedAt } = action.payload;

    const boardRef = doc(db, COLLECTIONS.BINGO_BOARD, SINGLETON_DOCS.BINGO_BOARD);
    const boardSnap = await getDoc(boardRef);

    if (!boardSnap.exists()) {
        throw new Error(`[offlineActions] bingoBoard/${SINGLETON_DOCS.BINGO_BOARD} no existe`);
    }

    const boardData = boardSnap.data();
    const categories = boardData.categories || [];

    const updatedCategories = categories.map(cat => {
        if (String(cat.id) === String(categoryId) && !cat.completedMemoryId) {
            return {
                ...cat,
                completedMemoryId: memoryId || null,
                completedAt: completedAt || new Date().toISOString(),
            };
        }
        return cat;
    });

    const newCompletedCount = updatedCategories.filter(c => c.completedMemoryId).length;

    await updateDoc(boardRef, {
        categories: updatedCategories,
        completedCount: newCompletedCount,
        updatedAt: serverTimestamp(),
    });
}

/**
 * Procesa un registro de ejercicio.
 */
async function processExerciseLog(action) {
    const { workoutDate, notes, durationMinutes } = action.payload; // Quitamos userId del payload, lo sacamos del auth
    const auth = getAuth();
    const userId = auth.currentUser?.uid;
    if (!userId) throw new Error('[processExerciseLog] No hay usuario autenticado.');

    const trackingRef = doc(db, 'exerciseTracking', userId);
    const snap = await getDoc(trackingRef);

    const today = new Date(workoutDate + 'T00:00:00');
    today.setHours(0, 0, 0, 0);
    const todayISO = today.toISOString().split('T')[0];

    const newEntry = {
        date: todayISO,
        notes: notes || '',
        durationMinutes: durationMinutes || 0,
        loggedAt: new Date().toISOString(),
    };

    if (!snap.exists()) {
        await setDoc(trackingRef, {
            currentStreak: 1,
            longestStreak: 1,
            totalDays: 1,
            lastWorkoutDate: todayISO,
            unlockedTiers: [],
            workoutLog: [newEntry],
            createdAt: serverTimestamp(),
            updatedAt: serverTimestamp(),
        });
        return;
    }

    const data = snap.data();
    const workoutLog = data.workoutLog || [];

    const alreadyLogged = workoutLog.some(entry => entry.date === todayISO);
    if (alreadyLogged) {
        console.log('[offlineActions] Workout ya registrado para', todayISO);
        return;
    }

    const lastDate = data.lastWorkoutDate
        ? new Date(data.lastWorkoutDate + 'T00:00:00')
        : null;

    let newStreak = 1;
    if (lastDate) {
        const diffDays = Math.round((today - lastDate) / (1000 * 60 * 60 * 24));
        if (diffDays === 1) {
            newStreak = (data.currentStreak || 0) + 1;
        } else if (diffDays === 0) {
            newStreak = data.currentStreak || 1;
        }
    }

    const newLongest = Math.max(newStreak, data.longestStreak || 0);

    await updateDoc(trackingRef, {
        currentStreak: newStreak,
        longestStreak: newLongest,
        totalDays: increment(1),
        lastWorkoutDate: todayISO,
        workoutLog: arrayUnion(newEntry),
        updatedAt: serverTimestamp(),
    });
}

/**
 * Procesa un registro de película.
 * Crea un nuevo documento en la colección 'memories' con los datos de la película.
 */
async function processMovieEntry(action) {
    const { title, tmdbId, watchDate, placeId, rating, posterPath, overview } = action.payload;
    const auth = getAuth();
    const uid = auth.currentUser?.uid;
    if (!uid) throw new Error('[processMovieEntry] No hay usuario autenticado.');

    const memoriesRef = collection(db, COLLECTIONS.MEMORIES);
    const newMemoryRef = doc(memoriesRef);

    await setDoc(newMemoryRef, {
        id: newMemoryRef.id,
        title,
        description: overview || `Vimos la película: ${title}`,
        eventDate: watchDate,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        placeId: placeId || null,
        tags: ['movies'],
        movieData: {
            tmdbId,
            rating,
            posterPath,
            title,
        },
        uploadedBy: uid,
        photoCount: 0,
        mainPhotoUrl: posterPath ? `https://image.tmdb.org/t/p/w500${posterPath}` : null,
        isHidden: false,
    });
}

// ─────────────────────────────────────────────────────────────────────────────
// Dispatcher principal
// ─────────────────────────────────────────────────────────────────────────────

async function dispatchAction(action) {
    switch (action.type) {
        case 'bingo_completion':
            return processBingoCompletion(action);
        case 'exercise_log':
            return processExerciseLog(action);
        case 'movie_entry':
            return processMovieEntry(action);
        default:
            throw new Error(`[offlineActions] Tipo de acción desconocido: ${action.type}`);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook principal
// ─────────────────────────────────────────────────────────────────────────────

let isProcessingActionsGlobal = false;

export function useOfflineActions() {
    const [pendingActionsCount, setPendingActionsCount] = useState(0);
    const [isProcessingActions, setIsProcessingActions] = useState(false);
    const processingRef = useRef(false);

    const refreshActionsCount = useCallback(async () => {
        try {
            const pending = await getPendingActions();
            setPendingActionsCount(pending.length);
        } catch {
            // IndexedDB no disponible
        }
    }, []);

    const processActions = useCallback(async () => {
        if (processingRef.current || isProcessingActionsGlobal) return;
        if (!navigator.onLine) {
            refreshActionsCount();
            return;
        }

        const pending = await getPendingActions();
        if (pending.length === 0) {
            refreshActionsCount();
            return;
        }

        processingRef.current = true;
        isProcessingActionsGlobal = true;
        setIsProcessingActions(true);

        try {
            pending.sort((a, b) => (a.createdAt ?? 0) - (b.createdAt ?? 0));

            for (const action of pending) {
                if (!navigator.onLine) break;

                try {
                    await updateAction(action.id, { status: 'processing' });
                    await dispatchAction(action);
                    await removeAction(action.id);
                    console.log(`[offlineActions] ✅ ${action.type} procesado:`, action.id);
                } catch (err) {
                    console.error(`[offlineActions] ❌ ${action.type} falló:`, err);
                    const retries = (action.retryCount ?? 0) + 1;
                    if (retries >= 3) {
                        await updateAction(action.id, { status: 'failed', retryCount: retries });
                    } else {
                        await updateAction(action.id, { status: 'pending', retryCount: retries });
                    }
                }
            }
        } finally {
            processingRef.current = false;
            isProcessingActionsGlobal = false;
            setIsProcessingActions(false);
            refreshActionsCount();
        }
    }, [refreshActionsCount]);

    useEffect(() => {
        refreshActionsCount();

        const cleanup = async () => {
            const pending = await getPendingActions();
            const stuck = pending.filter(a => a.status === 'processing');
            for (const action of stuck) {
                await updateAction(action.id, { status: 'pending' });
            }
            if (navigator.onLine) processActions();
        };
        cleanup();

        const handleOnline = () => processActions();
        const handleVisibility = () => {
            if (document.visibilityState === 'visible' && navigator.onLine) processActions();
        };
        const heartbeat = setInterval(() => {
            if (navigator.onLine) processActions();
        }, 120000);

        window.addEventListener('online', handleOnline);
        document.addEventListener('visibilitychange', handleVisibility);

        return () => {
            window.removeEventListener('online', handleOnline);
            document.removeEventListener('visibilitychange', handleVisibility);
            clearInterval(heartbeat);
        };
    }, [processActions, refreshActionsCount]);

    const queueAction = useCallback(async (type, payload) => {
        const id = crypto.randomUUID();
        await saveAction({
            id,
            type,
            payload,
            status: 'pending',
            retryCount: 0,
            createdAt: Date.now(),
        });
        await refreshActionsCount();

        if (navigator.onLine) {
            processActions();
        }

        return { queued: true, id };
    }, [refreshActionsCount, processActions]);

    return {
        queueAction,
        pendingActionsCount,
        isProcessingActions,
        processActions,
    };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { uploadFile, compressImage } from '../services/storage';
import { createMemory, createSnapshot, findOrCreatePlace } from '../apiClient';
import { STORAGE_PATHS } from '../config/constants';
import Memory from '../models/Memory';
import { toast } from '../components/ui/PastelToast/PastelToast';
import { useBingo } from './useBingo';

// ─────────────────────────────────────────────────────────────────────────────
// IndexedDB helpers
// ─────────────────────────────────────────────────────────────────────────────

import { openDB } from '../config/dbConfig';
const STORE_NAME = 'upload_queue';

// Global lock to prevent multiple hook instances from running sync concurrently
let isProcessingGlobal = false;

async function getAllPending() {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const req = store.getAll();
        req.onsuccess = () => {
            const results = req.result || [];
            // Filter for items that are 'pending' or 'uploading' 
            // We EXCLUDE 'failed' items from the automatic background sync
            resolve(results.filter(item =>
                item.status === 'pending' ||
                item.status === 'uploading'
            ));
        };
        req.onerror = () => reject(req.error);
    });
}

async function getAllFailed() {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const req = store.getAll();
        req.onsuccess = () => {
            const results = req.result || [];
            resolve(results.filter(item => item.status === 'failed'));
        };
        req.onerror = () => reject(req.error);
    });
}

async function clearFailedFromDB() {
    const db = await openDB();
    const failed = await getAllFailed();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    for (const item of failed) {
        store.delete(item.id);
    }
    return new Promise((resolve, reject) => {
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

async function saveToQueue(item) {
    const db = await openDB();

    // If this item is associated with a citation, clean up existing queue items for that citation
    if (item.originalCitaId) {
        const txSync = db.transaction(STORE_NAME, 'readwrite');
        const storeSync = txSync.objectStore(STORE_NAME);
        const allItems = await new Promise(r => {
            const req = storeSync.getAll();
            req.onsuccess = () => r(req.result || []);
        });

        for (const existing of allItems) {
            if (existing.originalCitaId === item.originalCitaId && existing.id !== item.id) {
                storeSync.delete(existing.id);
            }
        }
    }

    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).put(item);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

async function updateQueueItem(id, updates) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const getReq = store.get(id);
        getReq.onsuccess = () => {
            if (!getReq.result) return;
            const updatedItem = { ...getReq.result, ...updates };
            store.put(updatedItem);

            // If status is updating, sync with pending citations
            if (updates.status && updatedItem.originalCitaId) {
                syncCitaStatus(updatedItem.originalCitaId, updates.status);
            }
        };
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

async function removeFromQueue(id) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        tx.objectStore(STORE_NAME).delete(id);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
    });
}

/**
 * Synchronize the status of a citation in the pending_citas store.
 */
async function syncCitaStatus(citaId, status) {
    if (!citaId) return;
    try {
        const db = await openDB();
        const tx = db.transaction('pending_citas', 'readwrite');
        const store = tx.objectStore('pending_citas');
        const getReq = store.get(citaId);
        getReq.onsuccess = () => {
            const item = getReq.result;
            if (item) {
                item.status = status;
                store.put(item);
            }
        };
        await new Promise((resolve, reject) => {
            tx.oncomplete = () => resolve();
            tx.onerror = () => reject(tx.error);
        });
    } catch (err) {
        console.error('[offlineQueue] Error syncing cita status:', err);
    }
}

/**
 * Offline-capable photo upload queue using IndexedDB.
 */
export function useOfflineQueue() {
    const { completeBingoSquare } = useBingo();
    const [pendingCount, setPendingCount] = useState(0);
    const [failedCount, setFailedCount] = useState(0);
    const [isProcessing, setIsProcessing] = useState(false);
    const processingRef = useRef(false);

    // Refresh pending count from IndexedDB
    const refreshCount = useCallback(async () => {
        try {
            const pending = await getAllPending();
            const failed = await getAllFailed();
            setPendingCount(pending.length);
            setFailedCount(failed.length);
        } catch (err) {
            console.error('[offlineQueue] Error refreshing count:', err);
        }
    }, []);

    // Process all pending uploads
    const processQueue = useCallback(async () => {
        if (processingRef.current || isProcessingGlobal) return;

        // Check connectivity before starting
        if (!navigator.onLine) {
            refreshCount();
            return;
        }

        const pending = await getAllPending();
        if (pending.length === 0) {
            refreshCount();
            return;
        }

        processingRef.current = true;
        isProcessingGlobal = true;
        setIsProcessing(true);

        const DELAY_BETWEEN_UPLOADS = 3000;

        try {
            // Sort FIFO (oldest first)
            pending.sort((a, b) => (a.createdAt ?? 0) - (b.createdAt ?? 0));

            for (const item of pending) {
                // If we lost connection mid-process, stop
                if (!navigator.onLine) break;

                try {
                    // Reset retry count if it was marked as failed before
                    const currentRetries = item.status === 'failed' ? 0 : (item.retryCount ?? 0);
                    await updateQueueItem(item.id, { status: 'uploading', retryCount: currentRetries + 1 });

                    if (item.type === 'photo') {
                        await uploadFile(item.compressedBlob, item.targetStoragePath);
                    } else if (item.type === 'memory') {
                        toast.info('Sincronizando recuerdo...', 'Guardando tus momentos pendientes ✨');
                        const photoUrls = [];
                        for (let i = 0; i < (item.photos?.length ?? 0); i++) {
                            const photo = item.photos[i];
                            const photoId = crypto.randomUUID();
                            const tempMemoryId = item.id;
                            const storagePath = STORAGE_PATHS.PHOTO_ORIGINAL(tempMemoryId, photoId);
                            const url = await uploadFile(photo.blob, storagePath);
                            photoUrls.push({ url, storagePath, photoId });

                            if (i < item.photos.length - 1) {
                                await new Promise(r => setTimeout(r, DELAY_BETWEEN_UPLOADS));
                            }
                        }

                        const memoryModel = Memory.fromForm(item.data);
                        memoryModel.offlinePhotoUrls = photoUrls;

                        // CRITICAL: If no placeId but we have coordinates, find or create the place first
                        // so it appears on the map as a pin.
                        if (!memoryModel.placeId && memoryModel.placeLat && memoryModel.placeLng) {
                            try {
                                console.log('[offlineQueue] Creating missing place for memory...');
                                const placeResult = await findOrCreatePlace({
                                    lat: memoryModel.placeLat,
                                    lng: memoryModel.placeLng,
                                    name: memoryModel.placeName,
                                });

                                if (placeResult?.success && placeResult?.placeId) {
                                    memoryModel.placeId = placeResult.placeId;
                                    console.log('[offlineQueue] Place created/found:', placeResult.placeId);
                                }
                            } catch (placeErr) {
                                console.error('[offlineQueue] findOrCreatePlace failed:', placeErr);
                                // CRITICAL: coordinates remain in the payload even if place creation fails
                            }
                        }

                        const res = await createMemory({
                            ...memoryModel.toApiPayload(),
                            id: item.id, // Enforce using the same ID as the storage folder
                            offlinePhotoUrls: photoUrls,
                            // Ensure coordinates always reach the backend as fallback
                            placeLat: memoryModel.placeLat,
                            placeLng: memoryModel.placeLng,
                            placeName: memoryModel.placeName,
                        });

                        // ── BINGO INTEGRATION ──────────
                        if (item.bingoOrigin?.categoryId) {
                            // If this memory was EXPLICITLY started from a bingo square,
                            // complete it automatically and IGNORE general suggestions.
                            console.log('[offlineQueue] Auto-completing bingo square:', item.bingoOrigin.categoryId);
                            await completeBingoSquare(item.bingoOrigin.categoryId, item.id);
                        } else if (res?.bingoSuggestions?.length > 0) {
                            // Only save suggestions if it WASN'T an explicit bingo date
                            try {
                                const db = await openDB();
                                const tx = db.transaction('pending_bingo', 'readwrite');
                                tx.objectStore('pending_bingo').put({
                                    memoryId: item.id,
                                    suggestions: res.bingoSuggestions,
                                    createdAt: Date.now(),
                                    resolved: false
                                });
                                // Trigger update to UI
                                window.dispatchEvent(new Event('pending_bingo_updated'));
                            } catch (e) {
                                console.error('[offlineQueue] Error saving pending_bingo', e);
                            }
                        }

                        if (item.originalCitaId) {
                            const db = await openDB();
                            const tx = db.transaction('pending_citas', 'readwrite');
                            tx.objectStore('pending_citas').delete(item.originalCitaId);
                        }
                        toast.success('¡Recuerdo sincronizado!', 'Ya está disponible en tu mapa 📍');
                    } else if (item.type === 'snapshot') {
                        const snapshotId = item.id;
                        const storagePath = STORAGE_PATHS.SNAPSHOT_ORIGINAL(snapshotId);
                        const blob = item.photos?.[0]?.blob ?? item.compressedBlob;
                        const url = await uploadFile(blob, storagePath);

                        await createSnapshot({
                            storagePath,
                            photoUrl: url,
                            message: item.data?.message ?? '',
                        });
                        toast.success('Instantánea sincronizada ✨');
                    }

                    await removeFromQueue(item.id);
                } catch (err) {
                    console.error('[offlineQueue] Item failed:', err);
                    const currentRetries = item.retryCount ?? 0;
                    const newRetryCount = currentRetries + 1;
                    
                    if (newRetryCount >= 3) {
                        // Mark as permanent fail
                        await updateQueueItem(item.id, { status: 'failed', retryCount: newRetryCount });
                        if (item.originalCitaId) {
                            await syncCitaStatus(item.originalCitaId, 'failed');
                        }
                    } else {
                        // Mark for later retry
                        await updateQueueItem(item.id, { status: 'pending', retryCount: newRetryCount });
                    }
                }

                await new Promise(r => setTimeout(r, DELAY_BETWEEN_UPLOADS));
            }
        } finally {
            processingRef.current = false;
            isProcessingGlobal = false;
            setIsProcessing(false);
            refreshCount();
        }
    }, [refreshCount, completeBingoSquare]);

    // Intelligent Sync Triggers
    useEffect(() => {
        refreshCount();

        // 0. Cleanup stuck uploading items on mount
        const cleanupStuck = async () => {
            const current = await getAllPending();
            const stuck = current.filter(i => i.status === 'uploading');

            if (stuck.length > 0) {
                console.log('[offlineQueue] Cleaning up stuck items:', stuck.map(s => s.id));
                for (const item of stuck) {
                    await updateQueueItem(item.id, { status: 'pending' });
                }
                refreshCount();
            }
        };

        cleanupStuck().then(() => {
            // After initial cleanup, also check for any item that might have been 
            // stuck during this session (rare, but possible if a throw happens)
            if (navigator.onLine) {
                processQueue();
            }
        });

        // 2. Sync on connectivity change
        const handleOnline = () => {
            toast.info('Conexión restaurada', 'Sincronizando recuerdos pendientes...');
            processQueue();
        };

        // 3. Sync on tab becoming visible (returning to app)
        const handleVisibilityChange = () => {
            if (document.visibilityState === 'visible' && navigator.onLine) {
                processQueue();
            }
        };

        // 4. Periodic heartbeat (every 2 minutes)
        const heartbeat = setInterval(() => {
            if (navigator.onLine) processQueue();
        }, 120000);

        window.addEventListener('online', handleOnline);
        document.addEventListener('visibilitychange', handleVisibilityChange);

        return () => {
            window.removeEventListener('online', handleOnline);
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            clearInterval(heartbeat);
        };
    }, [processQueue, refreshCount]);

    /**
     * Queue a file for upload (or upload immediately if online).
     *
     * @param {File} file - Raw file from input
     * @param {string} memoryId - Target memory ID
     * @param {object} meta - { uploadedBy, caption, capturedAt, gpsCoordinates, isMain }
     * @param {Function} [onProgress] - Progress callback (only used when online)
     * @returns {Promise<{queued: boolean, url?: string}>}
     */
    const queueUpload = useCallback(async (file, memoryId, meta = {}, onProgress = null) => {
        const compressed = await compressImage(file, 1200, 0.8);
        const photoId = crypto.randomUUID();
        const storagePath = STORAGE_PATHS.PHOTO_ORIGINAL(memoryId, photoId);

        // ALWAYS save to IndexedDB queue first for persistence
        await saveToQueue({
            id: photoId,
            type: 'photo',
            localFileUri: URL.createObjectURL(compressed),
            compressedBlob: compressed,
            targetStoragePath: storagePath,
            targetMemoryId: memoryId,
            firestoreUpdates: meta.firestoreUpdates ?? null,
            status: 'pending',
            retryCount: 0,
            createdAt: Date.now(),
        });

        await refreshCount();

        // If online, trigger processing
        if (navigator.onLine) {
            processQueue();
        }

        return { queued: true, photoId, storagePath };
    }, [refreshCount]);

    /**
     * Queue a complete memory (form data + photo files) for offline upload.
     *
     * @param {object} formData - Memory form fields (title, eventDate, tags, etc.)
     * @param {File[]} photoFiles - Array of raw photo files
     * @param {string} originalCitaId - Optional ID of the pending cita this came from
     * @param {object} bingoOrigin - Optional { categoryId } metadata
     * @returns {Promise<{queued: boolean}>}
     */
    const queueMemory = useCallback(async (formData, photoFiles, originalCitaId = null, bingoOrigin = null) => {
        const compressedPhotos = await Promise.all(
            photoFiles.map(async (file) => {
                const blob = await compressImage(file, 1200, 0.8);
                return { blob, fileName: file.name, size: blob.size, mimeType: 'image/jpeg' };
            })
        );

        await saveToQueue({
            id: crypto.randomUUID(),
            type: 'memory',
            data: formData,
            photos: compressedPhotos,
            originalCitaId,
            bingoOrigin,
            status: 'pending',
            retryCount: 0,
            createdAt: Date.now(),
        });

        await refreshCount();

        // Try processing immediately if online
        if (navigator.onLine) {
            processQueue();
        }

        return { queued: true };
    }, [refreshCount, processQueue]);

    /**
     * Queue a snapshot photo for offline upload.
     *
     * @param {File} photoFile - The snapshot photo file
     * @param {string} message - Optional short message
     * @returns {Promise<{queued: boolean}>}
     */
    const queueSnapshot = useCallback(async (photoFile, message = '') => {
        const blob = await compressImage(photoFile, 1200, 0.8);

        await saveToQueue({
            id: crypto.randomUUID(),
            type: 'snapshot',
            data: { message },
            photos: [{ blob, fileName: photoFile.name, size: blob.size, mimeType: 'image/jpeg' }],
            status: 'pending',
            retryCount: 0,
            createdAt: Date.now(),
        });

        await refreshCount();

        if (navigator.onLine) {
            processQueue();
        }

        return { queued: true };
    }, [refreshCount, processQueue]);

    /**
     * Resets a failed item to pending status so it can be retried.
     */
    const retryItem = useCallback(async (id) => {
        await updateQueueItem(id, { status: 'pending', retryCount: 0 });
        await refreshCount();
        if (navigator.onLine) processQueue();
    }, [refreshCount, processQueue]);

    const retryFailedItems = useCallback(async () => {
        const failed = await getAllFailed();
        for (const item of failed) {
            await updateQueueItem(item.id, { status: 'pending', retryCount: 0 });
        }
        await refreshCount();
        if (navigator.onLine) processQueue();
    }, [refreshCount, processQueue]);

    const clearFailedItems = useCallback(async () => {
        await clearFailedFromDB();
        await refreshCount();
    }, [refreshCount]);

    /**
     * Gets all snapshots currently in the offline queue.
     */
    const getPendingSnapshots = useCallback(async () => {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const req = store.getAll();
            req.onsuccess = () => {
                const results = req.result || [];
                resolve(results.filter(item => item.type === 'snapshot' && item.status !== 'failed'));
            };
            req.onerror = () => reject(req.error);
        });
    }, []);

    return {
        queueUpload,
        queueMemory,
        queueSnapshot,
        pendingCount,
        failedCount,
        isProcessing,
        processQueue,
        retryItem,
        retryFailedItems,
        clearFailedItems,
        getPendingSnapshots,
    };
}

import { useState, useCallback, useEffect } from 'react';
import { openDB } from '../config/dbConfig';

/**
 * Hook to manage offline Bingo suggestions that were captured
 * asynchronously via background sync in `useOfflineQueue.js`.
 */
export function usePendingBingo() {
    const [pendingSuggestions, setPendingSuggestions] = useState([]);

    const fetchPending = useCallback(async () => {
        try {
            const db = await openDB();
            const tx = db.transaction('pending_bingo', 'readonly');
            const store = tx.objectStore('pending_bingo');

            const allItems = await new Promise((resolve) => {
                const req = store.getAll();
                req.onsuccess = () => resolve(req.result || []);
            });

            setPendingSuggestions(allItems.filter(item => !item.resolved));
        } catch (err) {
            console.error('[usePendingBingo] Error fetching:', err);
        }
    }, []);

    useEffect(() => {
        fetchPending();

        // Listen to visibility to refresh when coming back to the app
        const handleVisibility = () => {
             if (document.visibilityState === 'visible') fetchPending();
        };
        // Listen to local changes
        const handleLocalChange = () => fetchPending();

        document.addEventListener('visibilitychange', handleVisibility);
        window.addEventListener('pending_bingo_updated', handleLocalChange);

        return () => {
            document.removeEventListener('visibilitychange', handleVisibility);
            window.removeEventListener('pending_bingo_updated', handleLocalChange);
        };
    }, [fetchPending]);

    const resolvePendingSuggestion = useCallback(async (memoryId) => {
        try {
            const db = await openDB();
            const tx = db.transaction('pending_bingo', 'readwrite');
            const store = tx.objectStore('pending_bingo');
            const getReq = store.get(memoryId);

            getReq.onsuccess = () => {
                const item = getReq.result;
                if (item) {
                    item.resolved = true;
                    store.put(item);
                }
            };

            await new Promise((resolve, reject) => {
                tx.oncomplete = () => resolve();
                tx.onerror = () => reject(tx.error);
            });

            await fetchPending();
        } catch (err) {
            console.error('[usePendingBingo] Error marking resolved:', err);
        }
    }, [fetchPending]);

    const dismissSuggestion = useCallback(async (memoryId) => {
        try {
            const db = await openDB();
            const tx = db.transaction('pending_bingo', 'readwrite');
            const store = tx.objectStore('pending_bingo');
            const getReq = store.get(memoryId);

            getReq.onsuccess = () => {
                const item = getReq.result;
                if (item) {
                    item.dismissed = true;
                    store.put(item);
                }
            };

            await new Promise((resolve, reject) => {
                tx.oncomplete = () => resolve();
                tx.onerror = () => reject(tx.error);
            });

            await fetchPending();
        } catch (err) {
            console.error('[usePendingBingo] Error marking dismissed:', err);
        }
    }, [fetchPending]);

    return {
        pendingSuggestions,
        resolvePendingSuggestion,
        dismissSuggestion,
        refreshPending: fetchPending
    };
}

