import { useState, useEffect, useCallback, useMemo } from 'react';

import { openDB } from '../config/dbConfig';
import { autoDetectMetadata } from '../utils/extractGpsFromFile';
const STORE_NAME = 'pending_citas';

export function usePendingCitas() {
    const [pendingCitas, setPendingCitas] = useState([]);
    const [pendingCount, setPendingCount] = useState(0);
    const [hiddenIds, setHiddenIds] = useState(new Set());
    const [removalTimers, setRemovalTimers] = useState({});

    const refreshPending = useCallback(async () => {
        try {
            const db = await openDB();
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const request = store.getAll();

            request.onsuccess = () => {
                const results = request.result || [];
                setPendingCitas(prev => {
                    const urlMap = new Map();
                    prev.forEach(cita => {
                        cita.photos?.forEach(p => {
                            if (p.file && p.objectUrl) urlMap.set(p.file, p.objectUrl);
                        });
                    });

                    return results.map(item => {
                        const photosWithUrls = (item.photos || []).map(p => {
                            if (!p.file) return { ...p, objectUrl: null };
                            // REUSE if we already have it, otherwise create
                            const existingUrl = urlMap.get(p.file);
                            return {
                                ...p,
                                objectUrl: existingUrl || URL.createObjectURL(p.file)
                            };
                        });

                        return {
                            ...item,
                            photos: photosWithUrls,
                            coverPhoto: photosWithUrls[0]?.objectUrl
                        };
                    });
                });
                setPendingCount(results.length);
            };
        } catch (err) {
            console.error('[usePendingCitas] Error refreshing:', err);
        }
    }, []);

    useEffect(() => {
        refreshPending();
    }, [refreshPending]);

    const addPendingCita = useCallback(async (files, context = null) => {
        const db = await openDB();
        const id = crypto.randomUUID();
        const newItem = {
            id,
            createdAt: Date.now(),
            photos: files.map(file => ({
                file, // Original Blob/File
                name: file.name,
                type: file.type
            })),
            status: 'pending',
            context,
            isFromBingo: context?.type === 'bingo',
            bingoOrigin: context?.type === 'bingo' ? { categoryId: context.categoryId } : null,
            tags: context?.tags || [],
            description: context?.description || ''
        };

        if (files.length > 0) {
            try {
                const metadata = await autoDetectMetadata(files[0]);
                if (metadata) {
                    if (metadata.lat && metadata.lng) {
                        newItem.coordinates = { lat: metadata.lat, lng: metadata.lng };
                    }
                    if (metadata.dateTime) {
                        newItem.originalDate = metadata.dateTime.toLocaleDateString('es-MX', {
                            weekday: 'long',
                            day: 'numeric',
                            month: 'long',
                            hour: '2-digit',
                            minute: '2-digit'
                        });
                        newItem.rawDate = metadata.dateTime.toISOString();
                    }
                }
            } catch (err) {
                console.warn('[usePendingCitas] Metadata extraction failed:', err);
            }
        }

        if (!newItem.originalDate) {
            newItem.originalDate = new Date().toLocaleDateString('es-MX', {
                weekday: 'long',
                day: 'numeric',
                month: 'long',
                hour: '2-digit',
                minute: '2-digit'
            });
        }

        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            store.add(newItem);
            tx.oncomplete = () => {
                refreshPending();
                resolve(id);
            };
            tx.onerror = () => reject(tx.error);
        });
    }, [refreshPending]);

    const removePendingCita = useCallback(async (id, immediate = false) => {
        if (immediate) {
            const db = await openDB();
            return new Promise((resolve, reject) => {
                const tx = db.transaction(STORE_NAME, 'readwrite');
                const store = tx.objectStore(STORE_NAME);
                store.delete(id);
                tx.oncomplete = () => {
                    setHiddenIds(prev => {
                        const next = new Set(prev);
                        next.delete(id);
                        return next;
                    });
                    refreshPending();
                    resolve();
                };
                tx.onerror = () => reject(tx.error);
            });
        }

        setHiddenIds(prev => {
            const next = new Set(prev);
            next.add(id);
            return next;
        });

        const timer = setTimeout(() => {
            removePendingCita(id, true);
            setRemovalTimers(prev => {
                const next = { ...prev };
                delete next[id];
                return next;
            });
        }, 6000);

        setRemovalTimers(prev => ({ ...prev, [id]: timer }));
    }, [refreshPending]);

    const restorePendingCita = useCallback(async (idOrCita) => {
        const id = typeof idOrCita === 'string' ? idOrCita : idOrCita.id;
        
        if (hiddenIds.has(id)) {
            if (removalTimers[id]) {
                clearTimeout(removalTimers[id]);
                setRemovalTimers(prev => {
                    const next = { ...prev };
                    delete next[id];
                    return next;
                });
            }
            setHiddenIds(prev => {
                const next = new Set(prev);
                next.delete(id);
                return next;
            });
            return;
        }

        const cita = idOrCita;
        if (typeof cita === 'object') {
            const db = await openDB();
            const cleanedPhotos = (cita.photos || []).map(p => {
                const { objectUrl, ...rest } = p;
                return rest;
            });

            const itemToRestore = {
                ...cita,
                photos: cleanedPhotos,
                status: 'pending'
            };

            return new Promise((resolve, reject) => {
                const tx = db.transaction(STORE_NAME, 'readwrite');
                const store = tx.objectStore(STORE_NAME);
                store.add(itemToRestore);
                tx.oncomplete = () => {
                    refreshPending();
                    resolve(cita.id);
                };
                tx.onerror = () => reject(tx.error);
            });
        }
    }, [hiddenIds, removalTimers, refreshPending]);

    const updatePendingCitaStatus = useCallback(async (id, status) => {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            const getReq = store.get(id);
            getReq.onsuccess = () => {
                const item = getReq.result;
                if (item) {
                    item.status = status;
                    store.put(item);
                }
            };
            tx.oncomplete = () => {
                refreshPending();
                resolve();
            };
            tx.onerror = () => reject(tx.error);
        });
    }, [refreshPending]);

    const updatePendingCita = useCallback(async (id, updates) => {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            const getReq = store.get(id);
            getReq.onsuccess = () => {
                const item = getReq.result;
                if (item) {
                    const updated = { ...item, ...updates };
                    store.put(updated);
                }
            };
            tx.oncomplete = () => {
                refreshPending();
                resolve();
            };
            tx.onerror = () => reject(tx.error);
        });
    }, [refreshPending]);

    const getActiveDraft = useCallback(async () => {
        const db = await openDB();
        return new Promise((resolve) => {
            const tx = db.transaction(STORE_NAME, 'readonly');
            const store = tx.objectStore(STORE_NAME);
            const request = store.getAll();
            request.onsuccess = () => {
                const results = request.result || [];
                const active = results.find(c => c.status === 'draft');
                resolve(active || null);
            };
        });
    }, []);

    const saveDraft = useCallback(async (id, data, photos = []) => {
        const db = await openDB();
        const draftId = id || crypto.randomUUID();
        const draftItem = {
            id: draftId,
            status: 'draft',
            updatedAt: Date.now(),
            data,
            photos: photos.map(p => ({
                file: p.file || p.blob,
                name: p.name || `photo_${Date.now()}.jpg`,
                type: p.type || 'image/jpeg'
            })),
            isNew: !id
        };

        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, 'readwrite');
            const store = tx.objectStore(STORE_NAME);
            store.put(draftItem);
            tx.oncomplete = () => {
                refreshPending();
                resolve(draftId);
            };
            tx.onerror = () => reject(tx.error);
        });
    }, [refreshPending]);

    return useMemo(() => ({
        pendingCitas: pendingCitas.map(cita => ({
            ...cita,
            isHidden: hiddenIds.has(cita.id)
        })),
        pendingCount: pendingCount - hiddenIds.size,
        addPendingCita,
        removePendingCita,
        updatePendingCitaStatus,
        updatePendingCita,
        refreshPending,
        getActiveDraft,
        saveDraft,
        restorePendingCita
    }), [pendingCitas, hiddenIds, pendingCount, addPendingCita, removePendingCita, updatePendingCitaStatus, updatePendingCita, refreshPending, getActiveDraft, saveDraft, restorePendingCita]);
}

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App.jsx'
import { AuthProvider } from './context/AuthContext.jsx'
import { AppConfigProvider } from './context/AppConfigContext.jsx'
import { BingoProvider } from './context/BingoContext.jsx'
import { BrowserRouter } from 'react-router-dom'

// ─────────────────────────────────────────────────────────────────────────────
// Build timestamp injected at build time by vite.config.js → define: {}
/* global __BUILD_TIMESTAMP__ */
const CURRENT_BUILD = typeof __BUILD_TIMESTAMP__ !== 'undefined' ? __BUILD_TIMESTAMP__ : 'dev';

async function forceUpdate() {
  try {
    if ('serviceWorker' in navigator) {
      const regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map(r => r.unregister()));
    }
    if ('caches' in window) {
      const keys = await caches.keys();
      const oldCaches = keys.filter(k => !k.includes(CURRENT_BUILD));
      await Promise.all(oldCaches.map(k => caches.delete(k)));
    }
  } catch (e) {}
  window.location.replace(`/?v=${Date.now()}`);
}

async function checkForUpdate() {
  if (CURRENT_BUILD === 'dev') return;
  if (new URLSearchParams(window.location.search).has('v')) return;
  try {
    const res = await fetch(`/version.json?_=${Date.now()}`, {
      cache: 'no-store',
      headers: { 'pragma': 'no-cache', 'cache-control': 'no-store' },
    });
    if (!res.ok) return;
    const { buildTime } = await res.json();
    if (buildTime && buildTime !== CURRENT_BUILD) {
      await forceUpdate();
    }
  } catch {}
}

// Solo esto. Sin setInterval, sin visibilitychange.
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!new URLSearchParams(window.location.search).has('v')) {
      window.location.reload();
    }
  });
}

// checkForUpdate();

// ─────────────────────────────────────────────────────────────────────────────
// React bootstrap
// ─────────────────────────────────────────────────────────────────────────────
createRoot(document.getElementById('root')).render(
  <StrictMode>
    <BrowserRouter>
      <AuthProvider>
        <AppConfigProvider>
          <BingoProvider>
            <App />
          </BingoProvider>
        </AppConfigProvider>
      </AuthProvider>
    </BrowserRouter>
  </StrictMode>,
)

import { useState, useMemo, useRef, useEffect } from 'react';
import Card from '../../components/ui/Card/Card';
import Button from '../../components/ui/Button/Button';
import { useActivityLog } from '../../hooks/useActivityLog';
import { useCoupons } from '../../hooks/useCoupons';
import { db } from '../../services/firebase';
import { doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import SnapshotButton from '../snapshots/components/SnapshotButton';
import styles from './ActivityPanel.module.css';

export default function ActivityPanel({ filterType, setFilterType, onOpenSnapshot, onOpenCamera }) {
    const { logs, isLoading: loadingLogs, markAsRead, markAllAsRead, unreadCount } = useActivityLog();
    const { coupons, redemptions, updateCoupon, claimRedemption } = useCoupons({ adminMode: true });

    // Local state for sidebar toggle (legacy) or other filters
    const [onlyUnread, setOnlyUnread] = useState(false);
    const scrollRef = useRef(null);

    useEffect(() => {
        const slider = scrollRef.current;
        if (!slider) return;

        let isDown = false;
        let startX;
        let scrollLeft;

        const startDragging = (e) => {
            isDown = true;
            slider.style.cursor = 'grabbing';
            startX = e.pageX - slider.offsetLeft;
            scrollLeft = slider.scrollLeft;
        };

        const stopDragging = () => {
            isDown = false;
            slider.style.cursor = 'grab';
        };

        const move = (e) => {
            if (!isDown) return;
            e.preventDefault();
            const x = e.pageX - slider.offsetLeft;
            const walk = (x - startX) * 2;
            slider.scrollLeft = scrollLeft - walk;
        };

        slider.addEventListener('mousedown', startDragging);
        slider.addEventListener('mouseleave', stopDragging);
        slider.addEventListener('mouseup', stopDragging);
        slider.addEventListener('mousemove', move);

        return () => {
            slider.removeEventListener('mousedown', startDragging);
            slider.removeEventListener('mouseleave', stopDragging);
            slider.removeEventListener('mouseup', stopDragging);
            slider.removeEventListener('mousemove', move);
        };
    }, []);

    const pendingRedemptions = useMemo(() => {
        return (redemptions || []).filter(r => r.status === 'pending_approval').map(r => {
            const coupon = coupons.find(c => c.id === r.couponId);
            return { ...r, coupon };
        }).filter(r => r.coupon);
    }, [redemptions, coupons]);

    const filteredLogs = useMemo(() => {
        return logs.filter(log => {
            // Remove snapshots from logs
            if (log.targetType === 'snapshot') return false;

            const matchesType = filterType === 'all' || log.targetType === filterType;
            const matchesUnread = !onlyUnread || !log.isReadByAdmin;
            return matchesType && matchesUnread;
        });
    }, [logs, filterType, onlyUnread]);

    const groupedLogs = useMemo(() => {
        const now = new Date();
        const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const yesterday = new Date(today);
        yesterday.setDate(today.getDate() - 1);

        // Monday of current week
        const day = today.getDay();
        const diff = today.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
        const monday = new Date(today.setDate(diff));
        // Reset today's date after mutation if needed, but easier to use timestamp
        const todayTs = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
        const yesterdayTs = todayTs - 86400000;
        const mondayTs = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate()).getTime();

        const groups = {};

        filteredLogs.forEach(log => {
            const d = new Date(log.createdAt);
            const ts = d.getTime();
            let label = '';

            if (ts >= todayTs) {
                label = 'Hoy';
            } else if (ts >= yesterdayTs) {
                label = 'Ayer';
            } else if (ts >= mondayTs) {
                label = 'Esta semana';
            } else {
                label = d.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' });
                // Capitalize month
                label = label.charAt(0).toUpperCase() + label.slice(1);
            }

            if (!groups[label]) groups[label] = [];
            groups[label].push(log);
        });

        // Ensure Hoy, Ayer, Esta semana appear in order
        const orderedLabels = ['Hoy', 'Ayer', 'Esta semana'];
        const result = [];

        orderedLabels.forEach(l => {
            if (groups[l]) result.push({ label: l, items: groups[l] });
        });

        // Add Month Year groups (sorted)
        Object.keys(groups)
            .filter(l => !orderedLabels.includes(l))
            .sort((a, b) => {
                // Approximate sort by string or parse back to date
                return 0; // Keeping it simple for now as most will be recent
            })
            .forEach(l => {
                result.push({ label: l, items: groups[l] });
            });

        return result;
    }, [filteredLogs]);

    const handleApprove = async (redemption) => {
        await updateCoupon(redemption.couponId, {
            redemptionsLeft: (redemption.coupon.redemptionsLeft || redemption.coupon.maxRedemptions || 1) - 1
        });

        await updateDoc(doc(db, 'redemptions', redemption.id), {
            status: 'approved',
            approvedAt: serverTimestamp()
        });
    };

    const handlePostpone = async (redemption) => {
        await updateDoc(doc(db, 'redemptions', redemption.id), {
            status: 'postponed',
            postponedAt: serverTimestamp()
        });
    };

    const getTimeAgo = (date) => {
        const seconds = Math.floor((new Date() - date) / 1000);
        if (seconds < 60) return 'ahora mismo';
        const minutes = Math.floor(seconds / 60);
        if (minutes < 60) return `hace ${minutes}m`;
        const hours = Math.floor(minutes / 60);
        if (hours < 24) return `hace ${hours}h`;
        return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    const getIcon = (type) => {
        switch (type) {
            case 'memory': return '📸';
            case 'photo': return '🖼️';
            case 'capsule': return '⏳';
            case 'coupon': return '🎁';
            case 'bingo': return '🎯';
            case 'wrapped': return '🎬';
            case 'snapshot': return '✨';
            default: return '🔔';
        }
    };

    const getLabel = (type) => {
        switch (type) {
            case 'memory': return 'Recuerdo';
            case 'photo': return 'Foto';
            case 'capsule': return 'Cápsula';
            case 'coupon': return 'Cupón';
            case 'bingo': return 'Bingo';
            case 'wrapped': return 'Wrapped';
            case 'snapshot': return 'Instantánea';
            default: return 'Actividad';
        }
    };

    const CATEGORIES = [
        { id: 'all', label: 'Todos', icon: '♡' },
        { id: 'memory', label: 'Recuerdos', icon: '📸' },
        { id: 'photo', label: 'Fotos', icon: '🖼️' },
        { id: 'capsule', label: 'Cápsulas', icon: '⏳' },
        { id: 'coupon', label: 'Cupones', icon: '🎁' },
        { id: 'bingo', label: 'Bingo', icon: '🎯' },
    ];

    if (loadingLogs) {
        return <div className={styles.loading}>Cargando feed de actividad...</div>;
    }

    return (
        <div className={styles.root}>
            <header className={styles.header}>
                <div className={styles.titleGroup}>
                    <h1 className={styles.title}>Panel de Actividad</h1>
                    <p className={styles.subtitle}>Monitorea las acciones de tu partner.</p>
                </div>
                {unreadCount > 0 && (
                    <Button variant="primary" size="md" onClick={markAllAsRead} className={styles.markAllBtn}>
                        Marcar todo como leído ({unreadCount})
                    </Button>
                )}
            </header>

            <div className={styles.dashboardGrid}>
                {/* ── Main Feed ── */}
                <div className={styles.feedContainer}>
                    {/* Filter Header Row */}
                    <div className={styles.filterHeader}>
                        <div className={styles.filterChips} ref={scrollRef}>
                            {CATEGORIES.map(cat => (
                                <button 
                                    key={cat.id}
                                    className={`${styles.chip} ${filterType === cat.id ? styles.activeChip : ''}`}
                                    onClick={() => setFilterType(cat.id)}
                                >
                                    <span className={styles.chipIcon}>{cat.icon}</span>
                                    {cat.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {groupedLogs.length === 0 ? (
                        <div className={styles.emptyFeed}>
                            <span>📭</span>
                            <p>No hay actividad que coincida con los filtros.</p>
                        </div>
                    ) : (
                        <div className={styles.feedList}>
                            {groupedLogs.map(group => (
                                <section key={group.label} className={styles.feedSection}>
                                    <header className={styles.dateHeader}>
                                        {group.label}
                                    </header>

                                    {group.items.map(log => (
                                        <div 
                                            key={log.id} 
                                            className={`${styles.feedItem} ${log.isReadByAdmin ? styles.read : styles.unread}`}
                                            onClick={() => !log.isReadByAdmin && markAsRead(log.id)}
                                        >
                                            <div className={`${styles.itemIcon} ${styles[log.targetType]}`}>
                                                {getIcon(log.targetType)}
                                            </div>
                                            <div className={styles.itemContent}>
                                                <div className={styles.itemHeader}>
                                                    <span className={styles.itemAction}>{log.displayText}</span>
                                                    <span className={styles.itemTime}>{getTimeAgo(log.createdAt)}</span>
                                                </div>
                                                <div className={styles.itemFooter}>
                                                    <span className={styles.itemType}>{getLabel(log.targetType)}</span>
                                                    <span className={styles.itemId}>#{log.targetId?.slice(-6)}</span>
                                                </div>
                                            </div>
                                            <div className={styles.statusIndicator}>
                                                {log.isReadByAdmin ? '○' : '●'}
                                            </div>
                                        </div>
                                    ))}
                                </section>
                            ))}
                        </div>
                    )}
                </div>

                {/* ── Desktop Sidebar Extensions ── */}
                <aside className={styles.filtersSidebar}>
                    {pendingRedemptions.length > 0 && (
                        <Card className={styles.pendingRedemptionsCard}>
                            <h3>🎟️ Solicitudes ({pendingRedemptions.length})</h3>
                            <div className={styles.pendingList}>
                                {pendingRedemptions.map(r => (
                                    <div key={r.id} className={styles.pendingItem}>
                                        <div className={styles.pendingInfo}>
                                            <span className={styles.pendingEmoji}>{r.coupon.emoji}</span>
                                            <div>
                                                <p className={styles.pendingTitle}>{r.coupon.title}</p>
                                                <span className={styles.pendingTime}>{getTimeAgo(r.requestedAt?.toDate() || new Date())}</span>
                                            </div>
                                        </div>
                                        <div className={styles.pendingActions}>
                                            <Button size="xs" onClick={() => handleApprove(r)}>✅</Button>
                                            <Button variant="ghost" size="xs" onClick={() => handlePostpone(r)}>⏳</Button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </Card>
                    )}

                    <Card className={styles.statsCard}>
                        <div className={styles.stat}>
                            <span className={styles.statLabel}>Sin leer</span>
                            <span className={styles.unreadCountBadge}>{unreadCount}</span>
                        </div>
                    </Card>
                </aside>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { AnimatePresence } from 'framer-motion';
import { useActivityLog } from '../../hooks/useActivityLog';
import MemoryManager from '../memories/MemoryManager';
import CapsuleManager from '../capsules/CapsuleManager';
import CouponManager from '../coupons/CouponManager';
import BingoManager from '../bingo/BingoManager';
import ActivityPanel from '../activity/ActivityPanel';
import WrappedManager from '../wrapped/WrappedManager';
import GlobalSettings from '../settings/GlobalSettings';
