import { useState } from 'react';
import { createCapsule } from '../../apiClient';
import Button from '../../components/ui/Button/Button';
import DescriptiveCheckbox from '../../components/ui/DescriptiveCheckbox/DescriptiveCheckbox';
import KawaiiInput from '../../components/ui/KawaiiInput/KawaiiInput';
import MediaUploader from './components/MediaUploader';
import { uploadFile } from '../../services/storage';
import { STORAGE_PATHS } from '../../config/constants';
import styles from './CapsuleForm.module.css';

export default function CapsuleForm({ onSuccess, onCancel }) {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState(null);

    // Initial state
    const [formData, setFormData] = useState({
        title: '',
        teaserMessage: '',
        message: '',
        unlockTrigger: 'date',
        unlockDate: '',
        autoDestruct: true,
        notifyOnUnlock: true,
    });

    const [files, setFiles] = useState([]);
    const [uploadProgress, setUploadProgress] = useState(0);

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError(null);
        setIsSubmitting(true);

        try {
            let attachments = [];
            
            if (files.length > 0) {
                // Generar un ID temporal para la carpeta si no existe uno
                const tempCapsuleId = crypto.randomUUID();
                
                for (let i = 0; i < files.length; i++) {
                    const file = files[i];
                    const fileId = crypto.randomUUID();
                    const ext = file.name.split('.').pop();
                    const path = STORAGE_PATHS.ORIGINAL('capsules', tempCapsuleId, fileId); 
                    // Nota: STORAGE_PATHS.ORIGINAL ya formatea como `type/entityId/fileId.jpg` (o extensión)
                    
                    const url = await uploadFile(file, path, (p) => {
                        // Progreso simple ponderado
                        const totalProgress = ((i / files.length) * 100) + (p / files.length);
                        setUploadProgress(Math.round(totalProgress));
                    });

                    attachments.push({
                        url,
                        storagePath: path,
                        fileName: file.name,
                        fileType: file.type,
                        size: file.size,
                    });
                }
            }

            await createCapsule({
                ...formData,
                attachments
            });
            onSuccess();
        } catch (err) {
            console.error('Error creating capsule:', err);
            setError(err.message || 'Ocurrió un error inesperado al guardar la cápsula.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <form className={styles.form} onSubmit={handleSubmit}>
            {error && <div className={styles.error}>{error}</div>}

            <div className={styles.field}>
                <KawaiiInput
                    type="text"
                    label="Título (Secreto Interno)"
                    name="title"
                    required
                    value={formData.title}
                    onChange={handleChange}
                    placeholder="Ej. Aniversario 2026, San Valentín..."
                />
            </div>

            <div className={styles.field}>
                <KawaiiInput
                    type="text"
                    label="Mensaje Gancho / Teaser (Visible antes de abrir)"
                    name="teaserMessage"
                    required
                    value={formData.teaserMessage}
                    onChange={handleChange}
                    placeholder="Ej. No abras esto hasta estar sola..."
                />
            </div>

            <div className={styles.row}>
                <div className={styles.field}>
                    <KawaiiInput
                        type="select"
                        label="Condición de Apertura"
                        name="unlockTrigger"
                        value={formData.unlockTrigger}
                        onChange={handleChange}
                        options={[
                            { value: 'date', label: 'Fecha y Hora Específica' },
                            { value: 'manual', label: 'Manual (Tú decides cuándo)' }
                        ]}
                    />
                </div>

                {formData.unlockTrigger === 'date' && (
                    <div className={styles.field}>
                        <KawaiiInput
                            type="date"
                            label="Fecha de Desbloqueo"
                            name="unlockDate"
                            required
                            value={formData.unlockDate}
                            onChange={handleChange}
                        />
                    </div>
                )}
            </div>

            <div className={styles.field}>
                <KawaiiInput
                    type="textarea"
                    label="El Mensaje Secreto"
                    name="message"
                    required
                    value={formData.message}
                    onChange={handleChange}
                    placeholder="Escribe la carta o mensaje que quieres que lea..."
                />
            </div>

            <div className={styles.checkboxContainer}>
                <DescriptiveCheckbox
                    name="autoDestruct"
                    checked={formData.autoDestruct}
                    onChange={handleChange}
                    title="💥 Autodestrucción Rápida (Read-Once)"
                    description="La cápsula se fulminará para siempre inmediatamente después de que ella la lea."
                />

                <DescriptiveCheckbox
                    name="notifyOnUnlock"
                    checked={formData.notifyOnUnlock}
                    onChange={handleChange}
                    title="🔔 Notificación Push (Cloud Tasks)"
                    description="Despertará su teléfono en el instante milimétrico de la fecha de apertura elegida."
                />
            </div>

            <div className={styles.field}>
                <MediaUploader files={files} onChange={setFiles} />
                {isSubmitting && files.length > 0 && (
                    <div className={styles.progressContainer}>
                        <div className={styles.progressBar} style={{ width: `${uploadProgress}%` }} />
                        <span className={styles.progressText}>Subiendo multimedia: {uploadProgress}%</span>
                    </div>
                )}
            </div>

            <div className={styles.actions}>
                <Button
                    type="button"
                    variant="ghost"
                    onClick={onCancel}
                    disabled={isSubmitting}
                >
                    Cancelar
                </Button>
                <Button
                    type="submit"
                    disabled={isSubmitting}
                    isLoading={isSubmitting}
                >
                    {isSubmitting ? 'Enterrando...' : 'Enterrar Cápsula'}
                </Button>
            </div>
        </form>
    );
}

import { useState, useEffect } from 'react';
import { doc, deleteDoc } from 'firebase/firestore';
import { db } from '../../services/firebase';
import { COLLECTIONS } from '../../config/constants';
import { getCapsules, openCapsule } from '../../apiClient';
import CapsuleForm from './CapsuleForm';
import Button from '../../components/ui/Button/Button';
import Card from '../../components/ui/Card/Card';
import PageHeader from '../../components/ui/PageHeader/PageHeader';
import EmptyState from '../../components/ui/EmptyState/EmptyState';
import ConfirmModal from '../../components/ui/ConfirmModal/ConfirmModal';
import { toast } from '../../components/ui/PastelToast/PastelToast';
import styles from './CapsuleManager.module.css';

export default function CapsuleManager() {
    const [capsules, setCapsules] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [editingCapsule, setEditingCapsule] = useState(null);

    // Confirm Modal State
    const [confirmState, setConfirmState] = useState({
        isOpen: false,
        title: '',
        message: '',
        onConfirm: () => {},
        variant: 'default',
        emoji: '👋'
    });

    useEffect(() => {
        loadCapsules();
    }, []);

    async function loadCapsules() {
        setIsLoading(true);
        try {
            const result = await getCapsules();
            setCapsules(result.docs || []);
        } catch (err) {
            console.error('Error loading capsules:', err);
            toast.error('Error al cargar cápsulas');
        } finally {
            setIsLoading(false);
        }
    }

    const handleCreated = () => {
        setShowForm(false);
        setEditingCapsule(null);
        loadCapsules();
    };

    const handleDelete = (id) => {
        setConfirmState({
            isOpen: true,
            title: '¿Eliminar Cápsula?',
            message: 'Esta acción no se puede deshacer. Se borrarán todos los datos y archivos asociados.',
            variant: 'danger',
            emoji: '🗑️',
            onConfirm: async () => {
                try {
                    await deleteDoc(doc(db, COLLECTIONS.CAPSULES, id));
                    toast.success('Cápsula eliminada 🗑️');
                    setCapsules(prev => prev.filter(c => c.id !== id));
                    setConfirmState(p => ({ ...p, isOpen: false }));
                } catch (err) {
                    toast.error('Error al eliminar');
                }
            }
        });
    };

    const handleUnlockManual = (id) => {
        setConfirmState({
            isOpen: true,
            title: '¿Desbloquear Cápsula?',
            message: 'Se notificará al partner y podrá leer el contenido de inmediato.',
            variant: 'default',
            emoji: '🔑',
            onConfirm: async () => {
                try {
                    await toast.promise(openCapsule({ capsuleId: id }), {
                        loading: 'Desbloqueando...',
                        success: 'Cápsula desbloqueada ✅',
                        error: 'Error al desbloquear'
                    });
                    loadCapsules();
                    setConfirmState(p => ({ ...p, isOpen: false }));
                } catch (err) {
                    console.error('Unlock error:', err);
                }
            }
        });
    };

    return (
        <div className={styles.root}>
            <PageHeader
                title="Cápsulas del Tiempo"
                subtitle={`${capsules.length} cápsulas creadas`}
                actionLabel="Nueva Cápsula"
                actionIcon="✨"
                onAction={() => { setEditingCapsule(null); setShowForm(true); }}
            />

            <ConfirmModal 
                isOpen={confirmState.isOpen}
                title={confirmState.title}
                message={confirmState.message}
                variant={confirmState.variant}
                emoji={confirmState.emoji}
                onConfirm={confirmState.onConfirm}
                onCancel={() => setConfirmState(p => ({ ...p, isOpen: false }))}
                confirmText="Síp, adelante"
                cancelText="Nop, espera"
            />

            {/* Form panel */}
            {showForm && (
                <Card className={styles.formPanel}>
                    <div className={styles.formPanelHeader}>
                        <h2>{editingCapsule ? '✍️ Editar Cápsula' : '✨ Nueva Cápsula Real'}</h2>
                        <button onClick={() => setShowForm(false)} className={styles.closeBtn} title="Cerrar">✕</button>
                    </div>
                    <CapsuleForm
                        initialData={editingCapsule}
                        onSuccess={handleCreated}
                        onCancel={() => setShowForm(false)}
                    />
                </Card>
            )}

            {/* Capsule grid */}
            {isLoading ? (
                <div className={styles.loading}>
                    <div className={styles.spinner}></div>
                    <p>Conectando con el Tiempo...</p>
                </div>
            ) : capsules.length === 0 ? (
                <EmptyState
                    icon="⏳"
                    title="No hay cápsulas enterradas"
                    description="Escribe mensajes para el futuro y prográmalos para que se abran en una fecha especial."
                    action={
                        <Button onClick={() => setShowForm(true)} className={styles.newBtn}>
                            ¡Crear primera real!
                        </Button>
                    }
                />
            ) : (
                <div className={styles.grid}>
                    {capsules.map(capsule => (
                        <CapsuleCard
                            key={capsule.id}
                            capsule={capsule}
                            onEdit={() => { setEditingCapsule(capsule); setShowForm(true); }}
                            onDelete={() => handleDelete(capsule.id)}
                            onUnlock={() => handleUnlockManual(capsule.id)}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

function CapsuleCard({ capsule, onEdit, onDelete, onUnlock }) {
    let statusLabel = '🔒 Bloqueada';
    let statusClass = styles.locked;

    if (capsule.isDestructed) {
        statusLabel = '💥 Destruida';
        statusClass = styles.destructed;
    } else if (capsule.isViewed) {
        statusLabel = '👀 Leída';
        statusClass = styles.viewed;
    } else if (capsule.isUnlocked) {
        statusLabel = '✅ Desbloqueada';
        statusClass = styles.unlocked;
    }

    const unlockDateDisplay = capsule.unlockDate
        ? new Date(capsule.unlockDate).toLocaleDateString('es-MX', {
            day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
        })
        : 'Desbloqueo Manual';

    return (
        <Card className={styles.card}>
            <div className={styles.cardHeader}>
                <h3 className={styles.cardTitle}>{capsule.title}</h3>
                <span className={`${styles.statusBadge} ${statusClass}`}>
                    {statusLabel}
                </span>
            </div>

            <p className={styles.cardDate}>
                <span className={styles.dateIcon}>{capsule.unlockDate ? '⏰' : '🕹️'}</span> {unlockDateDisplay}
            </p>

            <div className={styles.cardBody}>
                {capsule.teaserMessage || <span className={styles.mutedText}>Sin mensaje de teaser...</span>}
            </div>

            <div className={styles.cardFooter}>
                {capsule.autoDestruct && <span className={styles.footerTag} title="Se destruirá tras ser leída">💣 Read-Once</span>}
                {capsule.notifyOnUnlock && <span className={styles.footerTag} title="Enviará Notificación Push">🔔 Notifica</span>}
                {!capsule.autoDestruct && !capsule.notifyOnUnlock && <span className={styles.footerTagMuted}>Estándar</span>}
            </div>

            {/* Hover Actions */}
            <div className={styles.cardActionsOverlay}>
                {!capsule.isUnlocked && !capsule.isDestructed && (
                    <button className={styles.actionBtn} onClick={onUnlock} title="Forzar Desbloqueo">
                        🔑
                    </button>
                )}
                <button className={styles.actionBtn} onClick={onEdit} title="Editar">
                    ✏️
                </button>
                <button 
                    className={`${styles.actionBtn} ${styles.deleteBtn}`} 
                    onClick={onDelete} 
                    title="Eliminar"
                >
                    🗑️
                </button>
            </div>
        </Card>
    );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './UserCapsules.module.css';
import { CapsuleIcons } from '../../icons/CapsuleIcons';
import { getCapsules, openCapsule } from '../../apiClient';
import Button from '../../components/ui/Button/Button';

/**
 * Normaliza los campos raw de Firestore a los campos derivados que espera la UI.
 */
function normalizeCapsule(raw) {
    const now = Date.now();
    const opensAtRaw = raw.unlockDate || raw.opensAt;
    const opensAt = opensAtRaw ? new Date(opensAtRaw).getTime() : null;
    const destructsAtRaw = raw.destructAt || raw.destructsAt;
    const destructsAt = destructsAtRaw ? new Date(destructsAtRaw).getTime() : null;

    let status = 'locked';
    if (raw.isDestructed) status = 'destructed';
    else if (raw.isUnlocked) {
        status = (raw.isDestructible || destructsAt) ? 'destructible' : 'unlocked';
    }
    else if (opensAt && opensAt > now) status = 'scheduled';

    const opensInDays = opensAt ? Math.ceil((opensAt - now) / 86400000) : null;
    const destroysInHours = destructsAt ? Math.ceil((destructsAt - now) / 3600000) : null;

    return {
        ...raw,
        status,
        type: raw.type || 'standard',
        opensInDays,
        destroysInHours,
        domain: raw.domain || null,
    };
}

/**
 * UserCapsules — Vista de Cápsulas del Tiempo (Buzón)
 * Rediseñado con tokens y lógica de estados (locked, unlocked, destructible).
 */
export default function UserCapsules() {
    const [capsules, setCapsules] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedCapsule, setSelectedCapsule] = useState(null);
    const [showDestruct, setShowDestruct] = useState(false);
    const hasOpenedRef = useRef(new Set()); // Track which capsules were marked as opened/viewed

    useEffect(() => {
        getCapsules({})
            .then(res => {
                const normalized = (res.docs || []).map(normalizeCapsule);
                setCapsules(normalized);
            })
            .catch(err => console.error(err))
            .finally(() => setIsLoading(false));
    }, []);

    const handleDownloadFiles = (files) => {
        if (!files || files.length === 0) return;
        files.forEach(file => {
            const a = document.createElement('a');
            a.href = file.url;
            a.download = file.fileName || 'capsule-file';
            a.target = '_blank'; // Previene bloqueos en algunos navegadores
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        });
    };

    const handleFinalClose = async (capsuleId) => {
        // Only trigger backend open once per session/view
        if (!hasOpenedRef.current.has(capsuleId)) {
            try {
                await openCapsule({ capsuleId });
                hasOpenedRef.current.add(capsuleId);
            } catch (err) {
                console.error('[UserCapsules] Error marking capsule as opened:', err);
            }
        }
        
        setSelectedCapsule(null);
        setShowDestruct(false);
        
        // Refresh list to show 'destructed' state
        const res = await getCapsules({});
        setCapsules((res.docs || []).map(normalizeCapsule));
    };

    const handleToggleModal = (capsule) => {
        if (!capsule) {
            // Case: Closing from the content modal (X button)
            if (selectedCapsule?.autoDestruct && selectedCapsule?.files?.length > 0) {
                setShowDestruct(true);
            } else {
                handleFinalClose(selectedCapsule?.id);
            }
        } else {
            setSelectedCapsule(capsule);
        }
    };

    if (isLoading) {
        return (
            <div className={styles.root}>
                <div className={styles.loading}>Cargando cápsulas... ✨</div>
            </div>
        );
    }

    return (
        <div className={styles.root}>
            <div className={styles.header}>
                <h1 className={styles.title}>Cápsulas</h1>
                <p className={styles.subtitle}>{capsules.length} sorpresas listas para ti</p>
            </div>

            <div className={styles.grid}>
                {capsules.map(capsule => (
                    <CapsuleCard
                        key={capsule.id}
                        capsule={capsule}
                        onOpen={() => setSelectedCapsule(capsule)}
                    />
                ))}
            </div>

            <AnimatePresence>
                {selectedCapsule && !showDestruct && selectedCapsule.status !== 'locked' && (
                    <CapsuleModal
                        capsule={selectedCapsule}
                        onClose={() => handleToggleModal(null)}
                    />
                )}
            </AnimatePresence>

            <AnimatePresence>
                {showDestruct && (
                    <DestructModal
                        files={selectedCapsule?.content?.files || []}
                        onDownload={() => {
                            handleDownloadFiles(selectedCapsule.content.files);
                            handleFinalClose(selectedCapsule.id);
                        }}
                        onSkip={() => handleFinalClose(selectedCapsule.id)}
                        onTimeUp={() => handleFinalClose(selectedCapsule.id)}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

function CapsuleCard({ capsule, onOpen }) {
    const { status, type, teaserMessage, title, opensInDays, destroysInHours, domain } = capsule;

    const isLocked = status === 'locked';
    const isDestructible = status === 'destructible';
    const isUnlocked = status === 'unlocked';

    // Icono dinámico desde el módulo externo
    const Icon = CapsuleIcons[type] || CapsuleIcons['message'];

    const getCardClass = () => {
        if (isLocked) return styles.cardLocked;
        if (isDestructible) return styles.cardDestructible;
        return styles.cardUnlocked;
    };

    return (
        <motion.div
            whileHover={!isLocked ? { scale: 1.02 } : {}}
            whileTap={!isLocked ? { scale: 0.98 } : {}}
            className={`${styles.card} ${getCardClass()}`}
            onClick={() => {
                if (!isLocked) onOpen();
            }}
        >
            {/* Header / Badge */}
            <div className={styles.cardHeader}>
                {isLocked && (
                    <span className={styles.badgeLocked}>⏳ Se abre en {opensInDays} días</span>
                )}
                {isUnlocked && (
                    <span className={styles.badgeOpen}>✨ ¡Lista!</span>
                )}
            </div>

            {/* Icon */}
            <div className={`${styles.iconWrapper} ${isLocked ? styles.iconGray : styles.iconMint}`}>
                <Icon />
            </div>

            {/* Content Título o Teaser */}
            {isDestructible ? (
                <>
                    <p className={styles.contentTitle}>{title}</p>
                    <div className={styles.destructionBar}>
                        <p className={styles.destructionText}>💥 SE DESTRUYE EN {destroysInHours} HORAS</p>
                        <div className={styles.progressBar}>
                            <div className={styles.progressFill} style={{ width: '60%' }}></div>
                        </div>
                    </div>
                </>
            ) : (
                <p className={isLocked ? styles.teaserDimmed : styles.teaser}>
                    "{teaserMessage}"
                </p>
            )}

            {/* Dominios para links */}
            {type === 'link' && domain && (
                <span className={styles.domainPill}>{domain}</span>
            )}

            {/* Acciones */}
            {isUnlocked && (
                <button className={styles.openBtn}>
                    Toca para abrir 👆
                </button>
            )}
        </motion.div>
    );
}

function CapsuleModal({ capsule, onClose }) {
    const { type, status, message, files, links } = capsule;
    const Icon = CapsuleIcons[type] || CapsuleIcons['message'];

    // Variants for sequenced reveal
    const bodyVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: { staggerChildren: 0.15, delayChildren: 0.2 }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20, scale: 0.95 },
        visible: { 
            opacity: 1, y: 0, scale: 1,
            transition: { type: 'spring', damping: 20, stiffness: 200 }
        }
    };

    const iconVariants = {
        hidden: { scale: 0, rotate: -20 },
        visible: { 
            scale: 1, rotate: 0,
            transition: { type: 'spring', damping: 15, stiffness: 300, delay: 0.1 }
        }
    };

    return (
        <motion.div
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
        >
            <motion.div
                className={styles.modalContent}
                initial={{ scale: 0.9, y: 50, rotate: -2 }}
                animate={{ scale: 1, y: 0, rotate: 0 }}
                exit={{ scale: 0.9, y: 50, rotate: 2 }}
                transition={{ type: 'spring', damping: 25, stiffness: 300 }}
                onClick={(e) => e.stopPropagation()}
            >
                <button className={styles.closeBtn} onClick={onClose}>×</button>
                
                <motion.div 
                    className={styles.modalBody}
                    variants={bodyVariants}
                    initial="hidden"
                    animate="visible"
                >
                    <motion.div className={styles.modalIconLarge} variants={iconVariants}>
                        <Icon />
                    </motion.div>

                    {message && (
                        <motion.div className={styles.modalMessage} variants={itemVariants}>
                            {message}
                        </motion.div>
                    )}

                    {files && files.length > 0 && (
                        <motion.div style={{ width: '100%' }} variants={itemVariants}>
                            <p className={styles.sectionTitle}>Archivos adjuntos</p>
                            <div className={styles.contentList}>
                                {files.map((file, idx) => (
                                    <a 
                                        key={idx} 
                                        href={file.url} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className={styles.contentLink}
                                    >
                                        <span className={styles.linkIcon}>📎</span>
                                        {file.fileName || file.name || 'Descargar archivo'}
                                    </a>
                                ))}
                            </div>
                        </motion.div>
                    )}

                    {links && links.length > 0 && (
                        <motion.div style={{ width: '100%' }} variants={itemVariants}>
                            <p className={styles.sectionTitle}>Links compartidos</p>
                            <div className={styles.contentList}>
                                {links.map((link, idx) => (
                                    <a 
                                        key={idx} 
                                        href={link.url} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className={styles.contentLink}
                                    >
                                        <span className={styles.linkIcon}>🔗</span>
                                        {link.title || link.url}
                                    </a>
                                ))}
                            </div>
                        </motion.div>
                    )}

                    {status === 'destructible' && (
                        <motion.div 
                            variants={itemVariants}
                            style={{ marginTop: '1rem', color: 'var(--color-error)', fontWeight: '800', fontSize: '0.8rem', textTransform: 'uppercase' }}
                        >
                            ⚠️ Esta cápsula se autodestruirá pronto
                        </motion.div>
                    )}
                </motion.div>
            </motion.div>
        </motion.div>
    );
}

/**
 * DestructModal — Pantalla de advertencia crítica con countdown
 */
function DestructModal({ files, onDownload, onSkip, onTimeUp }) {
    const [seconds, setSeconds] = useState(10);
    const timerRef = useRef(null);

    useEffect(() => {
        timerRef.current = setInterval(() => {
            setSeconds(prev => {
                if (prev <= 1) {
                    clearInterval(timerRef.current);
                    onTimeUp();
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);

        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, [onTimeUp]);

    return createPortal(
        <div className={styles.destructOverlay}>
            <motion.div 
                className={styles.destructCard}
                initial={{ scale: 0.8, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ type: 'spring', damping: 20 }}
            >
                <div className={styles.destructIcon}>💥</div>
                <h2 className={styles.destructTitle}>Esta cápsula se autodestruirá</h2>
                
                <div className={styles.countdownContainer}>
                    <motion.span 
                        key={seconds}
                        initial={{ scale: 1.5, opacity: 0 }}
                        animate={{ scale: 1, opacity: 1 }}
                        className={styles.countdownNumber}
                    >
                        {seconds}
                    </motion.span>
                </div>

                <p className={styles.destructText}>
                    ¿Quieres descargar los archivos antes de que desaparezcan para siempre?
                </p>

                <div className={styles.destructActions}>
                    <Button 
                        variant="primary" 
                        fullWidth 
                        onClick={onDownload}
                    >
                        💾 Descargar todo
                    </Button>
                    <Button 
                        variant="ghost" 
                        fullWidth 
                        onClick={onSkip}
                    >
                        No, destruir
                    </Button>
                </div>
            </motion.div>
        </div>,
        document.body
    );
}

import { useState, useRef, useEffect } from 'react';
import Button from '../../../components/ui/Button/Button';
import styles from './MediaUploader.module.css';

/**
 * MediaUploader - Componente para seleccionar y previsualizar imágenes/videos
 * para adjuntar a una cápsula.
 * 
 * @param {object} props
 * @param {Array} props.files - Lista de archivos File
 * @param {function} props.onChange - Callback al cambiar la lista de archivos
 */
export default function MediaUploader({ files = [], onChange }) {
    const [previews, setPreviews] = useState([]);
    const fileInputRef = useRef(null);

    // Sincronizar previsualizaciones con los archivos
    useEffect(() => {
        const newPreviews = files.map(file => ({
            id: Math.random().toString(36).substr(2, 9),
            file,
            url: URL.createObjectURL(file),
            type: file.type.startsWith('video/') ? 'video' : 'image'
        }));

        setPreviews(newPreviews);

        // Cleanup
        return () => {
            newPreviews.forEach(p => URL.revokeObjectURL(p.url));
        };
    }, [files]);

    const handleFileSelect = (e) => {
        const selectedFiles = Array.from(e.target.files || []);
        if (selectedFiles.length === 0) return;

        onChange([...files, ...selectedFiles]);
        e.target.value = ''; // Reset input
    };

    const removeFile = (index) => {
        const newFiles = [...files];
        newFiles.splice(index, 1);
        onChange(newFiles);
    };

    return (
        <div className={styles.root}>
            <div className={styles.header}>
                <span className={styles.icon}>📎</span>
                <span className={styles.label}>Archivos Multimedia</span>
                <span className={styles.count}>{files.length} / 10</span>
            </div>

            <div className={styles.grid}>
                {previews.map((preview, index) => (
                    <div key={preview.id} className={styles.previewItem}>
                        {preview.type === 'video' ? (
                            <video src={preview.url} className={styles.media} muted />
                        ) : (
                            <img src={preview.url} alt="Vista previa" className={styles.media} />
                        )}
                        <button 
                            type="button" 
                            className={styles.removeBtn}
                            onClick={() => removeFile(index)}
                            aria-label="Eliminar"
                        >
                            ✕
                        </button>
                        {preview.type === 'video' && <span className={styles.videoBadge}>▶</span>}
                    </div>
                ))}

                {files.length < 10 && (
                    <button 
                        type="button" 
                        className={styles.addBtn}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <span className={styles.plus}>+</span>
                        <span className={styles.addLabel}>Añadir</span>
                    </button>
                )}
            </div>

            <input 
                ref={fileInputRef}
                type="file"
                multiple
                accept="image/*,video/*"
                className={styles.hiddenInput}
                onChange={handleFileSelect}
            />
        </div>
    );
}

import { useState } from 'react';
import Button from '../../components/ui/Button/Button';
import Card from '../../components/ui/Card/Card';
import PageHeader from '../../components/ui/PageHeader/PageHeader';
import EmptyState from '../../components/ui/EmptyState/EmptyState';
import KawaiiInput from '../../components/ui/KawaiiInput/KawaiiInput';
import { useCoupons } from '../../hooks/useCoupons';
import { toast } from '../../components/ui/PastelToast/PastelToast';
import styles from './CouponManager.module.css';

export default function CouponManager() {
    const { 
        coupons, 
        isLoading, 
        createCoupon, 
        updateCoupon, 
        deleteCoupon 
    } = useCoupons({ adminMode: true });

    const [activeTab, setActiveTab] = useState('active'); // 'active', 'inactive', 'claimed'
    const [showForm, setShowForm] = useState(false);
    const [editingCoupon, setEditingCoupon] = useState(null);
    const [assigningCoupon, setAssigningCoupon] = useState(null);

    // Form state
    const [formData, setFormData] = useState({ 
        emoji: '🎁', title: '', type: 'wish', description: '', instructions: '', expiryDate: '', isActive: true, maxRedemptions: 1 
    });

    const handleCreated = async (e) => {
        e.preventDefault();
        
        try {
            const couponData = {
                ...formData,
                status: formData.isActive ? 'activo' : 'inactivo',
                redemptionsLeft: formData.maxRedemptions
            };

            if (editingCoupon) {
                await toast.promise(updateCoupon(editingCoupon.id, couponData), {
                    loading: 'Guardando cambios...',
                    success: 'Cupón actualizado ✨',
                    error: 'Error al actualizar'
                });
            } else {
                await toast.promise(createCoupon(couponData), {
                    loading: 'Creando cupón...',
                    success: '¡Cupón creado con éxito! 🎁',
                    error: 'Error al crear'
                });
            }
            setShowForm(false);
            setEditingCoupon(null);
            setFormData({ emoji: '🎁', title: '', type: 'wish', description: '', instructions: '', expiryDate: '', isActive: true, maxRedemptions: 1 });
        } catch (err) {
            console.error('[CouponManager] Form error:', err);
        }
    };

    const handleEdit = (c) => {
        setEditingCoupon(c);
        setFormData({
            emoji: c.emoji, title: c.title || c.name, type: c.type, description: c.description,
            instructions: c.instructions || '', expiryDate: c.expiryDate || '', 
            isActive: c.status === 'activo', maxRedemptions: c.maxRedemptions || 1
        });
        setShowForm(true);
    };

    const handleDelete = async (id) => {
        if (confirm('¿Seguro que quieres eliminar este cupón permanentemente?')) {
            try {
                await toast.promise(deleteCoupon(id), {
                    loading: 'Eliminando...',
                    success: 'Cupón eliminado 🗑️',
                    error: 'No se pudo eliminar'
                });
            } catch (err) {
                console.error('[CouponManager] Delete error:', err);
            }
        }
    };

    const toggleActive = async (coupon) => {
        try {
            const newStatus = coupon.status === 'activo' ? 'inactivo' : 'activo';
            await updateCoupon(coupon.id, { 
                status: newStatus,
                isActive: newStatus === 'activo'
            });
        } catch (err) {
            toast.error('Error al cambiar estado');
        }
    };

    const handleAssign = async (userId) => {
        if (!assigningCoupon) return;
        try {
            // This will be implemented in useCoupons or a direct service call
            await toast.promise(assignCouponDirectly(assigningCoupon.id, userId), {
                loading: 'Asignando cupón...',
                success: 'Cupón asignado con éxito 🎁',
                error: 'Error al asignar'
            });
            setAssigningCoupon(null);
        } catch (err) {
            console.error('[CouponManager] Assign error:', err);
        }
    };

    // Filter coupons based on activeTab
    const filteredCoupons = coupons.filter(c => {
        if (activeTab === 'active') return c.status === 'activo' || (c.isActive && c.status !== 'cobrado' && c.status !== 'inactivo');
        if (activeTab === 'inactive') return c.status === 'inactivo' || (!c.isActive && c.status !== 'cobrado');
        if (activeTab === 'claimed') return c.status === 'cobrado' || c.isUsed;
        return true;
    });

    return (
        <div className={styles.root}>
            <PageHeader
                title="Gestión de Cupones"
                subtitle="Configura recompensas y asigna detalles especiales."
                actionLabel="Nuevo Cupón"
                actionIcon="✨"
                onAction={() => { 
                    setEditingCoupon(null); 
                    setFormData({ emoji: '🎁', title: '', type: 'wish', description: '', instructions: '', expiryDate: '', isActive: true, maxRedemptions: 1 }); 
                    setShowForm(true); 
                }}
            />

            <div className={styles.tabsContainer}>
                <button 
                    className={`${styles.tab} ${activeTab === 'active' ? styles.tabActive : ''}`}
                    onClick={() => setActiveTab('active')}
                >
                    🟢 Activos
                </button>
                <button 
                    className={`${styles.tab} ${activeTab === 'inactive' ? styles.tabActive : ''}`}
                    onClick={() => setActiveTab('inactive')}
                >
                    ⚪ Inactivos
                </button>
                <button 
                    className={`${styles.tab} ${activeTab === 'claimed' ? styles.tabActive : ''}`}
                    onClick={() => setActiveTab('claimed')}
                >
                    ✅ Cobrados
                </button>
            </div>

            {/* Form panel */}
            {showForm && (
                <Card className={styles.formPanel} glass>
                    <div className={styles.formPanelHeader}>
                        <h2>{editingCoupon ? '✍️ Editar Cupón' : '✨ Nuevo Cupón'}</h2>
                        <button type="button" onClick={() => setShowForm(false)} className={styles.closeBtn} title="Cerrar">✕</button>
                    </div>
                    <form onSubmit={handleCreated} className={styles.form}>
                        <div className={styles.formRow}>
                            <div className={styles.formGroup} style={{ flex: '0 0 100px' }}>
                                <KawaiiInput 
                                    type="text" 
                                    label="Emoji" 
                                    maxLength="2" 
                                    required 
                                    value={formData.emoji} 
                                    onChange={e => setFormData({ ...formData, emoji: e.target.value })} 
                                />
                            </div>
                            <div className={styles.formGroup} style={{ flex: '1' }}>
                                <KawaiiInput 
                                    type="text" 
                                    label="Título" 
                                    required 
                                    placeholder="Ej. Vale por un abrazo..." 
                                    value={formData.title} 
                                    onChange={e => setFormData({ ...formData, title: e.target.value })} 
                                />
                            </div>
                        </div>

                        <div className={styles.formRow}>
                            <div className={styles.formGroup} style={{ flex: '1' }}>
                                <KawaiiInput 
                                    type="select" 
                                    label="Categoría" 
                                    value={formData.type} 
                                    onChange={e => setFormData({ ...formData, type: e.target.value })} 
                                    options={[
                                        { value: 'massage', label: '💆‍♀️ Masaje / Relax' },
                                        { value: 'date_night', label: '🍷 Date Night' },
                                        { value: 'free_pass', label: '🃏 Pase Libre' },
                                        { value: 'wish', label: '✨ Deseo Libre' },
                                        { value: 'naughty', label: '🌶️ Picante' }
                                    ]} 
                                />
                            </div>
                            <div className={styles.formGroup} style={{ flex: '1' }}>
                                <KawaiiInput 
                                    type="number" 
                                    label="Max Canjes" 
                                    min="1"
                                    value={formData.maxRedemptions} 
                                    onChange={e => setFormData({ ...formData, maxRedemptions: parseInt(e.target.value) || 1 })} 
                                />
                            </div>
                        </div>

                        <div className={styles.formGroup}>
                            <KawaiiInput 
                                type="textarea" 
                                label="Descripción" 
                                required 
                                rows="2" 
                                placeholder="¿Qué incluye este cupón?" 
                                value={formData.description} 
                                onChange={e => setFormData({ ...formData, description: e.target.value })} 
                            />
                        </div>

                        <div className={styles.toggleGroup}>
                            <KawaiiInput 
                                type="toggle" 
                                label="Cupón Activo" 
                                value={formData.isActive} 
                                onChange={e => setFormData({ ...formData, isActive: e.target.checked || e.target.value === true })} 
                            />
                        </div>

                        <div className={styles.formActions}>
                            <Button type="button" variant="ghost" onClick={() => setShowForm(false)}>Cancelar</Button>
                            <Button type="submit">{editingCoupon ? 'Guardar' : 'Crear'}</Button>
                        </div>
                    </form>
                </Card>
            )}

            {/* Grid */}
            {isLoading ? (
                <div className={styles.loading}>
                    <div className={styles.spinner}></div>
                    <p>Cargando cupones...</p>
                </div>
            ) : filteredCoupons.length === 0 ? (
                <EmptyState
                    icon={activeTab === 'active' ? '🎟️' : activeTab === 'inactive' ? '⚪' : '✅'}
                    title={activeTab === 'active' ? 'Sin cupones activos' : activeTab === 'inactive' ? 'Sin cupones inactivos' : 'Sin historial de cobros'}
                    description={activeTab === 'active' ? 'Crea cupones para que tu partner pueda canjearlos.' : ''}
                />
            ) : (
                <div className={styles.grid}>
                    {filteredCoupons.map(coupon => (
                        <CouponCard 
                            key={coupon.id} 
                            coupon={coupon} 
                            onEdit={() => handleEdit(coupon)} 
                            onDelete={() => handleDelete(coupon.id)} 
                            onToggleActive={() => toggleActive(coupon)} 
                            onAssign={() => setAssigningCoupon(coupon)}
                            showAssign={activeTab === 'active'}
                        />
                    ))}
                </div>
            )}

            {/* Assignment Modal (Future-proof Selector) */}
            {assigningCoupon && (
                <div className={styles.modalOverlay} onClick={() => setAssigningCoupon(null)}>
                    <Card className={styles.assignModal} onClick={e => e.stopPropagation()}>
                        <h3>🎁 Asignar "{assigningCoupon.title || assigningCoupon.name}"</h3>
                        <p>El cupón aparecerá directamente en "Disponibles" del Partner.</p>
                        
                        <div className={styles.partnerList}>
                            {/* For now we assume one partner, but could be fetched from a useUsers hook */}
                            <button className={styles.partnerBtn} onClick={() => handleAssign('partner_uid')}>
                                <span className={styles.partnerAvatar}>💖</span>
                                <span className={styles.partnerName}>Partner</span>
                            </button>
                        </div>
                        
                        <Button variant="ghost" className={styles.cancelModal} onClick={() => setAssigningCoupon(null)}>Cancelar</Button>
                    </Card>
                </div>
            )}
        </div>
    );
}

function CouponCard({ coupon, onEdit, onDelete, onToggleActive, onAssign, showAssign }) {
    const typeLabels = {
        massage: 'Relax', date_night: 'Cita', free_pass: 'Pase Libre', wish: 'Deseo', naughty: 'Intimo'
    };

    const isInactive = coupon.status === 'inactivo' || !coupon.isActive;
    const isClaimed = coupon.status === 'cobrado' || coupon.isUsed;

    return (
        <Card className={`${styles.card} ${isInactive ? styles.cardInactive : ''} ${isClaimed ? styles.cardClaimed : ''}`}>
            <div className={styles.cardHeader}>
                <div className={styles.couponIcon}>{coupon.emoji}</div>
                <div className={styles.cardHeaderActions}>
                    <span className={styles.typeBadge}>{typeLabels[coupon.type] || coupon.type}</span>
                    <button className={`${styles.toggleBtn} ${!isInactive ? styles.toggleOn : styles.toggleOff}`} onClick={onToggleActive} title={!isInactive ? "Desactivar" : "Activar"}>
                        {!isInactive ? '👁️' : '🙈'}
                    </button>
                </div>
            </div>

            <h3 className={styles.cardTitle}>{coupon.title || coupon.name}</h3>
            <p className={styles.cardDesc}>{coupon.description}</p>
            
            <div className={styles.cardStats}>
                {coupon.maxRedemptions > 1 && (
                    <span className={styles.statBadge}>
                        🔢 {coupon.redemptionsLeft} / {coupon.maxRedemptions}
                    </span>
                )}
                {isClaimed && <span className={styles.claimedBadge}>COBRADO</span>}
            </div>

            <div className={styles.cardFooter}>
                {showAssign && !isClaimed && (
                    <Button size="sm" className={styles.assignBtn} onClick={onAssign}>
                        🎁 Asignar
                    </Button>
                )}
                <div className={styles.footerActions}>
                    <button className={styles.miniBtn} onClick={onEdit} title="Editar">✏️</button>
                    <button className={`${styles.miniBtn} ${styles.deleteBtn}`} onClick={onDelete} title="Eliminar">🗑️</button>
                </div>
            </div>

            <div className={styles.tearLine}></div>
        </Card>
    );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Button from '../../components/ui/Button/Button';
import SegmentedControl from '../../components/ui/SegmentedControl/SegmentedControl';
import styles from './UserCoupons.module.css';
import CouponTicket from '../../components/ui/CouponTicket/CouponTicket';
import BottomSheetModal from '../../components/ui/BottomSheetModal/BottomSheetModal';

import { MOCK_COUPONS } from '../../data/couponsData';

import { useCoupons } from '../../hooks/useCoupons';

export default function UserCoupons({ onModalStateChange }) {
    const [activeTab, setActiveTab] = useState('available');
    const { coupons, redemptions, isLoading, redeemCoupon, claimRedemption } = useCoupons();
    const [actionCoupon, setActionCoupon] = useState(null);
    const [actionType, setActionType] = useState('redeem'); // 'redeem' or 'claim'

    // Logic:
    // 1. Available: All active coupons (Pool) + redemptions with status 'assigned'
    // 2. Pending: Redemptions with status 'pending_approval' or 'approved'/'pending_claim'
    // 3. Claimed: Redemptions with status 'claimed'

    const available = [
        ...(coupons || []).filter(c => c.status === 'activo' && (c.redemptionsLeft === undefined || c.redemptionsLeft > 0)),
        ...(redemptions || []).filter(r => r.status === 'assigned').map(r => {
            const coupon = coupons.find(c => c.id === r.couponId);
            return { ...coupon, id: r.couponId, redemptionId: r.id, isAssigned: true };
        })
    ].filter(item => item.id); // Ensure we have a valid coupon object

    const pending = (redemptions || []).filter(r => r.status === 'pending_approval' || r.status === 'approved' || r.status === 'pending_claim').map(r => {
        const coupon = coupons.find(c => c.id === r.couponId);
        return { ...coupon, id: r.couponId, redemptionId: r.id, redemptionStatus: r.status };
    }).filter(item => item.id);

    const claimed = (redemptions || []).filter(r => r.status === 'claimed').map(r => {
        const coupon = coupons.find(c => c.id === r.couponId);
        return { ...coupon, id: r.couponId, redemptionId: r.id };
    }).filter(item => item.id);

    const handleTabChange = (newTab) => {
        setActiveTab(newTab);
    };

    const handleConfirmAction = async () => {
        if (!actionCoupon) return;

        let res;
        if (actionType === 'redeem') {
            res = await redeemCoupon(actionCoupon.id);
        } else {
            res = await claimRedemption(actionCoupon.redemptionId);
        }

        if (res.success) {
            setActionCoupon(null);
            if (onModalStateChange) onModalStateChange(false);
        }
    };

    const handleCloseModal = () => {
        setActionCoupon(null);
        if (onModalStateChange) onModalStateChange(false);
    };

    const openRedeemModal = (coupon) => {
        setActionType('redeem');
        setActionCoupon(coupon);
        if (onModalStateChange) onModalStateChange(true);
    };

    const openClaimModal = (coupon) => {
        setActionType('claim');
        setActionCoupon(coupon);
        if (onModalStateChange) onModalStateChange(true);
    };

    if (isLoading && coupons.length === 0) {
        return (
            <div className={styles.root}>
                <div className={styles.loading}>Sincronizando tus cupones... ✨</div>
            </div>
        );
    }

    return (
        <div className={styles.root}>
            <div className={styles.header}>
                <h1 className={styles.title}>Cupones 🎁</h1>
                <p className={styles.subtitle}>Detalles especiales para canjear y disfrutar.</p>
            </div>
            
            <SegmentedControl
                tabs={[
                    { id: 'available', label: `Disponibles (${available.length})` },
                    { id: 'pending', label: `Pendientes (${pending.length})` },
                    { id: 'claimed', label: `Cobrados (${claimed.length})` }
                ]}
                activeTab={activeTab}
                onChange={handleTabChange}
            />

            <div className={styles.couponList}>
                <AnimatePresence mode="popLayout">
                    <motion.div
                        key={activeTab}
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className={styles.gridContainer}
                    >
                        {activeTab === 'available' && available.map(coupon => (
                            <CouponTicket
                                key={coupon.redemptionId || coupon.id}
                                coupon={coupon}
                                onRedeem={() => openRedeemModal(coupon)}
                            />
                        ))}

                        {activeTab === 'pending' && pending.map(coupon => (
                            <CouponTicket
                                key={coupon.redemptionId}
                                coupon={{ ...coupon, isPending: true }}
                                onRedeem={() => coupon.redemptionStatus !== 'pending_approval' && openClaimModal(coupon)}
                            />
                        ))}

                        {activeTab === 'claimed' && claimed.map(coupon => (
                            <CouponTicket
                                key={coupon.redemptionId}
                                coupon={{ ...coupon, isUsed: true }}
                            />
                        ))}

                        {(activeTab === 'available' && available.length === 0) && (
                            <p className={styles.emptyState}>No tienes caprichos nuevos por ahora.</p>
                        )}
                        {(activeTab === 'pending' && pending.length === 0) && (
                            <p className={styles.emptyState}>No hay canjes esperando aprobación.</p>
                        )}
                        {(activeTab === 'claimed' && claimed.length === 0) && (
                            <p className={styles.emptyState}>Aún no has cobrado ningún capricho.</p>
                        )}
                    </motion.div>
                </AnimatePresence>
            </div>

            <BottomSheetModal
                isOpen={!!actionCoupon}
                onClose={handleCloseModal}
                emoji={actionCoupon?.emoji}
                title={actionCoupon?.title || actionCoupon?.name}
                description={actionType === 'redeem' ? "¿Segura que quieres solicitar este vale?" : "¿Ya recibiste tu regalo? Esto lo marcará como cobrado definitivamente."}
                confirmText={actionType === 'redeem' ? "¡Sí, por favor! 💝" : "¡Sí, lo cobré! ✅"}
                cancelText="Mejor después"
                onConfirm={handleConfirmAction}
                onCancel={handleCloseModal}
            />
        </div>
    );
}

import { useState, useEffect, useRef } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { useGallery } from './hooks/useGallery';
import PhotoDetailOverlay from './components/PhotoDetailOverlay';
import LoadingScreen from '../../components/ui/LoadingScreen/LoadingScreen';
import styles from './GalleryView.module.css';

/**
 * GalleryView — Chronological photogrid for all memories
 */
export default function GalleryView() {
    const { photos, loading, hasMore, loadMore, error } = useGallery(24);
    const [selectedPhotoIndex, setSelectedPhotoIndex] = useState(null);
    const observerTarget = useRef(null);

    // Infinite scroll observer
    useEffect(() => {
        const observer = new IntersectionObserver(
            entries => {
                if (entries[0].isIntersecting && hasMore && !loading) {
                    loadMore();
                }
            },
            { threshold: 1.0 }
        );

        if (observerTarget.current) {
            observer.observe(observerTarget.current);
        }

        return () => observer.disconnect();
    }, [hasMore, loading, loadMore]);

    if (loading && photos.length === 0) {
        return <LoadingScreen message="Cargando sus momentos... ✨" />;
    }

    if (error) {
        return (
            <div className={styles.errorContainer}>
                <span className="material-symbols-outlined">error</span>
                <p>Ups, no pudimos cargar las fotos</p>
                <button onClick={() => window.location.reload()}>Reintentar</button>
            </div>
        );
    }

    return (
        <div className={styles.container}>
            <header className={styles.header}>
                <h1>Nuestra Galería</h1>
                <p className={styles.subtitle}>Un recorrido por nuestros momentos</p>
            </header>

            {photos.length === 0 ? (
                <motion.div
                    className={styles.emptyState}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                >
                    <div className={styles.emptyCard}>
                        <div className={styles.emptyIcon}>
                            <span className="material-symbols-outlined">auto_awesome_motion</span>
                            <div className={styles.sparkle}>✨</div>
                        </div>
                        <h2>Aquí vivirán sus recuerdos 🌸</h2>
                        <p>Cada foto que suban en sus citas aparecerá aquí para que siempre puedan volver a ella.</p>
                        <div className={styles.emptyDecoration}>
                            <div className={styles.dot} />
                            <div className={styles.dot} />
                            <div className={styles.dot} />
                        </div>
                    </div>
                </motion.div>
            ) : (
                <motion.div 
                    className={styles.grid}
                    variants={{
                        hidden: { opacity: 0 },
                        show: {
                            opacity: 1,
                            transition: {
                                staggerChildren: 0.05
                            }
                        }
                    }}
                    initial="hidden"
                    animate="show"
                >
                    {photos.map((photo, index) => (
                        <motion.div
                            key={`${photo.id}-${index}`}
                            className={styles.photoThumb}
                            onClick={() => setSelectedPhotoIndex(index)}
                            variants={{
                                hidden: { opacity: 0, y: 20, scale: 0.9 },
                                show: { 
                                    opacity: 1, y: 0, scale: 1,
                                    transition: { type: 'spring', damping: 25, stiffness: 200 }
                                }
                            }}
                        >
                            <img
                                src={photo.thumbnailUrl || photo.url || photo.storagePath}
                                alt={photo.caption || ''}
                                loading="lazy"
                            />
                            {photo.isSpecial && (
                                <div className={styles.specialBadge}>
                                    <span className="material-symbols-outlined">favorite</span>
                                </div>
                            )}
                            {photo._type === 'snapshot' && (
                                <div className={styles.snapshotBadge}>📸</div>
                            )}
                            {photo.wasUnseen && (
                                <div className={styles.unseenBadge}>📥</div>
                            )}
                        </motion.div>
                    ))}

                    {/* Intersection Observer Target */}
                    <div ref={observerTarget} className={styles.loaderTarget}>
                        {loading && (
                            <div className={styles.miniLoader}>
                                <div className={styles.spinner} />
                            </div>
                        )}
                    </div>
                </motion.div>
            )}

            {/* Photo Detail Modal */}
            <AnimatePresence>
                {selectedPhotoIndex !== null && (
                    <PhotoDetailOverlay
                        photos={photos}
                        initialIndex={selectedPhotoIndex}
                        onClose={() => setSelectedPhotoIndex(null)}
                    />
                )}
            </AnimatePresence>
        </div>
    );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './PhotoDetailOverlay.module.css';

/**
 * PhotoDetailOverlay — Full screen photo viewer with metadata and swipe support
 */
export default function PhotoDetailOverlay({ photos, initialIndex, onClose }) {
    const [currentIndex, setCurrentIndex] = useState(initialIndex);

    const currentPhoto = photos[currentIndex];

    const handleNext = () => {
        if (currentIndex < photos.length - 1) {
            setCurrentIndex(prev => prev + 1);
        }
    };

    const handlePrev = () => {
        if (currentIndex > 0) {
            setCurrentIndex(prev => prev - 1);
        }
    };

    // Swipe logic with framer-motion
    const swipeConfidenceThreshold = 10000;
    const swipePower = (offset, velocity) => {
        return Math.abs(offset) * velocity;
    };

    return (
        <motion.div
            className={styles.overlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
        >
            <button className={styles.closeBtn} onClick={onClose}>
                <span className="material-symbols-outlined">close</span>
            </button>

            <div className={styles.content}>
                <AnimatePresence mode="wait">
                    <motion.div
                        key={currentPhoto.id}
                        className={styles.slide}
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        exit={{ opacity: 0, x: -20 }}
                        drag="x"
                        dragConstraints={{ left: 0, right: 0 }}
                        dragElastic={1}
                        onDragEnd={(e, { offset, velocity }) => {
                            const swipe = swipePower(offset.x, velocity.x);

                            if (swipe < -swipeConfidenceThreshold) {
                                handleNext();
                            } else if (swipe > swipeConfidenceThreshold) {
                                handlePrev();
                            }
                        }}
                    >
                        <img
                            src={currentPhoto.url || currentPhoto.storagePath}
                            alt={currentPhoto.caption || ''}
                            className={styles.mainPhoto}
                        />

                        <div className={styles.metadata}>
                            {currentPhoto.caption && <p className={styles.caption}>{currentPhoto.caption}</p>}

                            <div className={styles.infoRow}>
                                {currentPhoto.createdAt && (
                                    <div className={styles.infoItem}>
                                        <span className="material-symbols-outlined">calendar_month</span>
                                        <span>{currentPhoto.createdAt.toDate?.().toLocaleDateString() || new Date(currentPhoto.createdAt).toLocaleDateString()}</span>
                                    </div>
                                )}
                                {currentPhoto.location && (
                                    <div className={styles.infoItem}>
                                        <span className="material-symbols-outlined">location_on</span>
                                        <span>{currentPhoto.location.name || 'Ubicación'}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </motion.div>
                </AnimatePresence>

                {/* Navigation Arrows (for desktop/accessibility) */}
                {currentIndex > 0 && (
                    <button className={`${styles.navBtn} ${styles.prevBtn}`} onClick={handlePrev}>
                        <span className="material-symbols-outlined">chevron_left</span>
                    </button>
                )}
                {currentIndex < photos.length - 1 && (
                    <button className={`${styles.navBtn} ${styles.nextBtn}`} onClick={handleNext}>
                        <span className="material-symbols-outlined">chevron_right</span>
                    </button>
                )}
            </div>

            <div className={styles.counter}>
                {currentIndex + 1} / {photos.length}
            </div>
        </motion.div>
    );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { callBackendApi } from '../../../apiClient';
import { auth } from '../../../services/firebase';

/**
 * useGallery — Custom hook for paginated photo fetching.
 * Uses collectionGroup('photos') to get all photos across all memories.
 * Now also includes archived snapshots merged chronologically.
 */
export function useGallery(pageSize = 20) {
    const [photos, setPhotos] = useState([]);
    const [loading, setLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);
    const [error, setError] = useState(null);
    const lastDocRef = useRef(null);
    const isLoadingRef = useRef(false);

    const fetchPhotos = useCallback(async (isInitial = false) => {
        if (!auth.currentUser) {
            setLoading(false);
            isLoadingRef.current = false;
            return;
        }
        if (isLoadingRef.current || (!hasMore && !isInitial)) return;

        setLoading(true);
        isLoadingRef.current = true;
        setError(null);

        try {
            const currentPageSize = pageSize;
            const params = { limit: currentPageSize };

            // Apply cursor if not initial fetch
            if (!isInitial && lastDocRef.current) {
                params.lastCreatedAt = lastDocRef.current.createdAt;
                params.lastId = lastDocRef.current.id;
            }

            const result = await callBackendApi('getGallery', params);

            if (result.success) {
                const fetchedPhotos = result.photos || [];

                if (isInitial) {
                    setPhotos(fetchedPhotos);
                } else {
                    setPhotos(prev => [...prev, ...fetchedPhotos]);
                }

                // Update cursor with the last element
                if (fetchedPhotos.length > 0) {
                    lastDocRef.current = fetchedPhotos[fetchedPhotos.length - 1];
                }

                // If we got less than limit, we've reached the end
                setHasMore(fetchedPhotos.length === currentPageSize);
            } else {
                throw new Error(result.error || 'Failed to fetch gallery');
            }
        } catch (err) {
            console.error('Error fetching gallery photos:', err);
            setError(err.message);
        } finally {
            setLoading(false);
            isLoadingRef.current = false;
        }
    }, [pageSize, hasMore]);

    // Initial fetch
    useEffect(() => {
        fetchPhotos(true);
    }, []);

    const loadMore = () => fetchPhotos(false);

    return { photos, loading, hasMore, error, loadMore };
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Map, MapMarker, MarkerContent, MapControls, MarkerLabel } from '@/components/ui/map';
import MapPin from '../../components/ui/MapPin/MapPin';
import { subscribeToGlobalSettings } from '../../services/settingsService';
import { toast } from '../../components/ui/PastelToast/PastelToast';
import { useAuth } from '../../hooks/useAuth';
import styles from './MapView.module.css';
import { usePlaces } from './hooks/usePlaces';
import { getMemories } from '../../apiClient';
import SystemConfig from '../../models/SystemConfig';
import { useOnlineStatus } from './hooks/useOnlineStatus';
import { getCachedMapConfig, saveCachedMapConfig } from '../../utils/offlineCache';

// Sub-components
import PlaceDetailDrawer from './components/PlaceDetailDrawer/PlaceDetailDrawer';
import SearchOverlay from './components/SearchOverlay';
import ActionFabs from './components/ActionFabs';

export default function MapView({
    onPlaceSelected,
    bingoContextToMap,
    clearBingoContext,
    openPendingSignal,
    onPendingSignalHandled,
    onOpenSnapshot,
    onOpenCamera,
    citaContext,
    onCitaContextChange,
    onOpenPending,
    onOpenPhotoViewer
}) {
    const { isPartner, isAdmin } = useAuth();
    const [selectedPlace, setSelectedPlace] = useState(null);
    const [activeFilter, setActiveFilter] = useState('todos');
    const [globalSettings, setGlobalSettings] = useState(null);
    const [placeMemories, setPlaceMemories] = useState([]);
    const [loadingMemories, setLoadingMemories] = useState(false);
    const isOnline = useOnlineStatus();
    const [isUsingCache, setIsUsingCache] = useState(false);

    // Tuxtla Gutiérrez, Chiapas
    const [viewport, setViewport] = useState({
        center: [-93.1152, 16.7521], // MapLibre uses [lng, lat]
        zoom: 13,
    });


    useEffect(() => {
        let isFirstLoad = true;

        // 1. Cargar desde caché inmediatamente (Zero Latency)
        async function loadCache() {
            const cached = await getCachedMapConfig();
            if (cached && cached.data) {
                const config = SystemConfig.fromFirestore(cached.data);
                setGlobalSettings(config);
                setIsUsingCache(true);
                console.log('[MapView] Loaded mapConfig from IndexedDB');
            }
        }
        loadCache();

        // 2. Suscribirse a Firestore si hay conexión
        const unsub = subscribeToGlobalSettings(async (data) => {
            if (!data) return;

            const remoteConfig = SystemConfig.fromFirestore(data);
            const cached = await getCachedMapConfig();

            const remoteTs = remoteConfig.mapConfig?.lastActTimestamp;
            const localTs = cached?.data?.mapConfig?.lastActTimestamp;

            // Solo actualizar si no hay caché o si el remoto es más reciente
            // Nota: remoteTs puede ser un FieldValue o un Date según el estado de sync de Firestore
            const shouldUpdate = !cached || !localTs || (remoteTs && new Date(remoteTs) > new Date(localTs));

            if (shouldUpdate) {
                setGlobalSettings(remoteConfig);
                setIsUsingCache(false);
                await saveCachedMapConfig(data);

                if (!isFirstLoad) {
                    toast.success('Configuración actualizada', 'Los ajustes del mapa se han sincronizado.');
                }
            }

            isFirstLoad = false;
        });

        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (pos) => {
                    setViewport(prev => ({
                        ...prev,
                        center: [pos.coords.longitude, pos.coords.latitude],
                        zoom: 14
                    }));
                },
                (err) => {
                    if (err.code === 3) console.warn('[MapView] Geolocation timeout');
                    else console.log('[MapView] Geolocation error:', err);
                },
                { enableHighAccuracy: false, timeout: 30000, maximumAge: 300000 }
            );
        }

        return unsub;
    }, []);

    useEffect(() => {
        if (bingoContextToMap) {
            if (onCitaContextChange) onCitaContextChange(bingoContextToMap);
            if (clearBingoContext) clearBingoContext();
            if (onPlaceSelected) onPlaceSelected(true);
        }
    }, [bingoContextToMap, clearBingoContext, onPlaceSelected, onCitaContextChange]);

    const { places, loading: placesLoading } = usePlaces();
    const [isSearchActive, setIsSearchActive] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        if (openPendingSignal) {
            if (onOpenPending) onOpenPending();
            if (onPendingSignalHandled) onPendingSignalHandled();
        }
    }, [openPendingSignal, onPendingSignalHandled, onOpenPending]);

    useEffect(() => {
        const isAnyOverlayOpen = !!citaContext || !!selectedPlace || isSearchActive;
        if (onPlaceSelected) onPlaceSelected(isAnyOverlayOpen);
    }, [citaContext, selectedPlace, isSearchActive, onPlaceSelected]);

    const filteredPlaces = useMemo(() => {
        return places.filter(p => {
            const hasCitas = (p.visitCount || 0) > 0;
            const matchesFilter = activeFilter === 'todos' || p.tags?.includes(activeFilter);
            const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase());
            return hasCitas && matchesFilter && matchesSearch;
        });
    }, [places, activeFilter, searchQuery]);

    const uniqueTags = useMemo(() => {
        const visiblePlaces = places.filter(p => (p.visitCount || 0) > 0);
        return [...new Set(visiblePlaces.flatMap(p => p.tags ?? []))];
    }, [places]);

    const TAG_ICONS = {
        'cine': 'movie',
        'comida': 'restaurant',
        'romántico': 'local_florist',
        'aventura': 'hiking',
        'relajación': 'spa',
        'fiesta': 'celebration',
        'misterioso': 'help_center',
        'todos': 'favorite'
    };

    const activeFilters = [
        { id: 'todos', label: 'Todos', icon: 'favorite' },
        ...uniqueTags.map(tag => ({
            id: tag,
            label: tag.charAt(0).toUpperCase() + tag.slice(1),
            icon: TAG_ICONS[tag] || 'bookmark'
        }))
    ];

    const handleMarkerClick = useCallback((place) => {
        const newPlace = selectedPlace?.id === place.id ? null : place;
        setSelectedPlace(newPlace);
        if (onPlaceSelected) onPlaceSelected(!!newPlace);
    }, [selectedPlace, onPlaceSelected]);

    const handleMapClick = useCallback(() => {
        if (isSearchActive) setIsSearchActive(false);
        if (selectedPlace) {
            setSelectedPlace(null);
            if (onPlaceSelected) onPlaceSelected(false);
        }
    }, [isSearchActive, selectedPlace, onPlaceSelected]);

    const handleFitAll = useCallback(() => {
        if (places.length === 0) return;

        const validPlaces = places.filter(p => (p.coordinates?.lat || p.coordinates?.latitude) && (p.coordinates?.lng || p.coordinates?.longitude));
        if (validPlaces.length === 0) return;

        let minLng = Infinity, maxLng = -Infinity, minLat = Infinity, maxLat = -Infinity;
        validPlaces.forEach(p => {
            const lng = p.coordinates.lng;
            const lat = p.coordinates.lat;
            if (lng < minLng) minLng = lng;
            if (lng > maxLng) maxLng = lng;
            if (lat < minLat) minLat = lat;
            if (lat > maxLat) maxLat = lat;
        });

        const center = [(minLng + maxLng) / 2, (minLat + maxLat) / 2];
        const lngDiff = maxLng - minLng;
        const latDiff = maxLat - minLat;
        const maxDiff = Math.max(lngDiff, latDiff);

        let zoom = 14;
        if (maxDiff > 0.5) zoom = 10;
        else if (maxDiff > 0.1) zoom = 12;
        else if (maxDiff > 0.05) zoom = 13;

        setViewport({ center, zoom });
    }, [places]);

    useEffect(() => {
        if (!placesLoading && filteredPlaces.length > 0) {
            handleFitAll();
        }
    }, [activeFilter, placesLoading, handleFitAll]);

    useEffect(() => {
        if (selectedPlace && selectedPlace.id) {
            const fetchMemories = async () => {
                setLoadingMemories(true);
                setPlaceMemories([]);
                try {
                    const result = await getMemories({ placeId: selectedPlace.id, limit: 10 });
                    if (result.success) {
                        setPlaceMemories(result.docs || []);
                    }
                } catch (err) {
                    console.error('[MapView] Error fetching memories for place:', err);
                } finally {
                    setLoadingMemories(false);
                }
            };
            fetchMemories();
        } else {
            setPlaceMemories([]);
        }
    }, [selectedPlace]);

    useEffect(() => {
        if (selectedPlace && selectedPlace.coordinates) {
            setViewport(prev => ({
                ...prev,
                center: [selectedPlace.coordinates.lng, selectedPlace.coordinates.lat],
                zoom: 16
            }));
        }
    }, [selectedPlace]);

    return (
        <div className={styles.screen}>
            {/* Sync Badge */}
            {(!isOnline || isUsingCache) && (
                <div className={styles.offlineBadge}>
                    <span>{isOnline ? '📡 Config. local' : '📴 Modo Offline'}</span>
                </div>
            )}
            {/* ── THE MAP ── */}
            <div className={styles.mapLayer}>
                <Map
                    viewport={viewport}
                    onViewportChange={setViewport}
                    className={styles.map}
                    attributionControl={false}
                    theme="light"
                    onClick={handleMapClick}
                >
                    {/* Controles de zoom eliminados por petición del usuario */}

                    {filteredPlaces.filter(p => (p.coordinates?.lat || p.coordinates?.latitude) && (p.coordinates?.lng || p.coordinates?.longitude)).map(place => {
                        const isSelected = selectedPlace?.id === place.id;
                        const zoom = viewport?.zoom || 13;

                        const tierStyle = place.getMarkerStyle(globalSettings?.mapConfig);


                        let size = 'small';
                        if (place.visitCount >= 5) size = 'large';
                        else if (place.visitCount >= 2) size = 'medium';
                        if (zoom < 10) size = 'micro';

                        // Base scale from zoom + additional scale from tier
                        const zoomScale = zoom >= 14 ? 1 : zoom >= 12 ? 0.7 : zoom >= 10 ? 0.45 : 0.25;
                        const finalScale = zoomScale * (tierStyle.scale || 1.0);

                        const hideIcon = zoom < 12;
                        const hidePulse = zoom < 13;

                        return (
                            <MapMarker
                                key={place.id}
                                longitude={place.coordinates.lng}
                                latitude={place.coordinates.lat}
                                onClick={() => handleMarkerClick(place)}
                            >
                                <MarkerContent>
                                    <div style={{
                                        display: 'flex',
                                        alignItems: size === 'micro' ? 'center' : 'flex-end',
                                        justifyContent: 'center',
                                        position: 'relative'
                                    }}>
                                        <div style={{ transform: `scale(${finalScale})`, transformOrigin: 'bottom center', display: 'flex' }}>
                                            <MapPin
                                                size={size}
                                                color={tierStyle.color}
                                                selected={isSelected}
                                                hideIcon={hideIcon}
                                                hidePulse={hidePulse}
                                            />
                                        </div>
                                    </div>
                                </MarkerContent>
                                <MarkerLabel className={styles.pinLabel} position="top">
                                    {place.name}
                                </MarkerLabel>
                            </MapMarker>
                        );
                    })}
                </Map>
            </div>

            {/* ── OVERLAY LAYER ── */}
            <div className={styles.overlay}>
                <SearchOverlay 
                    isSearchActive={isSearchActive}
                    setIsSearchActive={setIsSearchActive}
                    searchQuery={searchQuery}
                    setSearchQuery={setSearchQuery}
                    activeFilters={activeFilters}
                    activeFilter={activeFilter}
                    setActiveFilter={setActiveFilter}
                    placesLoading={placesLoading}
                    places={places}
                    onPlaceSelected={onPlaceSelected}
                    isPartner={isPartner}
                    isAdmin={isAdmin}
                    onOpenSnapshot={onOpenSnapshot}
                    onOpenCamera={onOpenCamera}
                />

                <ActionFabs 
                    isPartner={isPartner}
                    isSearchActive={isSearchActive}
                    citaContext={citaContext}
                    selectedPlace={selectedPlace}
                    onSpontaneousCita={() => {
                        const minVal = globalSettings?.citaConfig?.minPhotosSpontaneous || 5;
                        if (onCitaContextChange) onCitaContextChange({ type: 'spontaneous', minPhotos: minVal });
                    }}
                />

                {!isSearchActive && (
                    <PlaceDetailDrawer
                        selectedPlace={selectedPlace}
                        onClose={() => {
                            setSelectedPlace(null);
                            if (onPlaceSelected) onPlaceSelected(false);
                        }}
                        loadingMemories={loadingMemories}
                        placeMemories={placeMemories}
                        onPhotoClick={onOpenPhotoViewer}
                        citaContext={citaContext}
                        onVerifyPlace={(place) => {
                            if (onCitaContextChange) {
                                onCitaContextChange({ 
                                    ...citaContext,
                                    placeId: place.id, 
                                    name: place.name,
                                    verified: true
                                });
                            }
                        }}
                    />
                )}
            </div>
        </div>
    );
}

