import { useState, useEffect } from 'react';
import { subscribeToCollection } from '../../../services/firestore';
import { COLLECTIONS } from '../../../config/constants';
import Place from '../../../models/Place';
import { cachePlaceThumbnail } from '../../../utils/offlineCache';

/**
 * Hook to manage real-time subscription to Places collection.
 * Replaces MOCK_PLACES with real data from Firestore.
 * 
 * @returns {Object} { places: Array, loading: boolean, error: Error|null }
 */
let globalPlacesCache = [];
let globalLoading = true;
let globalUnsubscribe = null;
let listeners = new Set();

export function usePlaces() {
    const [places, setPlaces] = useState(globalPlacesCache);
    const [loading, setLoading] = useState(globalLoading);
    const [error, setError] = useState(null);

    useEffect(() => {
        const updateState = () => {
            setPlaces(globalPlacesCache);
            setLoading(globalLoading);
        };

        listeners.add(updateState);

        if (!globalUnsubscribe) {
            try {
                globalUnsubscribe = subscribeToCollection(
                    COLLECTIONS.PLACES,
                    (docs) => {
                        const newPlaces = (docs || []).map(doc => Place.fromFirestore(doc.id, doc));
                        globalPlacesCache = newPlaces;
                        globalLoading = false;
                        
                        // Lógica de caché de thumbnails (silenciosa)
                        // Cacheamos solo los 50 lugares más visitados para no saturar storage
                        const popularPlaces = [...newPlaces]
                            .sort((a, b) => (b.visitCount || 0) - (a.visitCount || 0))
                            .slice(0, 50);
                            
                        popularPlaces.forEach(place => {
                            if (place.coverPhotoUrl && !place.coverPhotoUrl.startsWith('blob:')) {
                                cachePlaceThumbnail(place.id, place.coverPhotoUrl);
                            }
                        });

                        listeners.forEach(l => l());
                    },
                    [],
                    200
                );
            } catch (err) {
                console.error('Error subscribing to places:', err);
                setError(err);
                globalLoading = false;
                listeners.forEach(l => l());
            }
        }

        return () => {
            listeners.delete(updateState);
            // We DON'T unsubscribe globally here to keep data "in memory"
            // The subscription will stay alive for the entire session
        };
    }, []);

    return { places, loading, error };
}

import { useState, useEffect } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { createMemory, findOrCreatePlace, updateMemory, completeBingoSquare } from '../../apiClient';
import BingoSuggestionSheet from './components/BingoSuggestionSheet';
import { useOfflineQueue } from '../../hooks/useOfflineQueue';
import { usePendingCitas } from '../../hooks/usePendingCitas';
import Memory from '../../models/Memory';
import { reverseGeocode } from '../../services/mapService';
import { PLACE_CATEGORIES } from '../../config/constants';
import { extractMetadataFromFile } from '../../utils/extractGpsFromFile';
import { usePlaces } from '../map/hooks/usePlaces';
import { useBingo } from '../../hooks/useBingo';

import styles from './MemoryForm.module.css';

// Sub-components
import StepIndicator from './components/StepIndicator';
import DraftRecoveryPrompt from './components/DraftRecoveryPrompt';
import MemoryDetailsForm from './components/MemoryDetailsForm';
import MemoryPhotoSection from './components/MemoryPhotoSection';

// Helper to format date for input type="datetime-local"
const toInputDateTime = (date) => {
    if (!date) return '';
    const d = new Date(date);
    const z = (n) => String(n).padStart(2, '0');
    const yyyy = d.getFullYear();
    const mm = z(d.getMonth() + 1);
    const dd = z(d.getDate());
    const hh = z(d.getHours());
    const min = z(d.getMinutes());
    return `${yyyy}-${mm}-${dd}T${hh}:${min}`;
};

export default function MemoryForm({ initialData = null, onSuccess, onCancel, role = 'admin', bingoContext = null, initialPhotos = [] }) {
    const isPartner = role === 'partner';
    const { queueMemory } = useOfflineQueue();
    const { getActiveDraft, saveDraft, removePendingCita } = usePendingCitas();
    const isEditing = !!initialData;

    const [form, setForm] = useState({
        title: initialData?.title ?? '',
        description: initialData?.description ?? '',
        eventDate: initialData?.eventDate
            ? toInputDateTime(
                typeof initialData.eventDate.toDate === 'function'
                    ? initialData.eventDate.toDate()
                    : new Date(initialData.eventDate)
            )
            : toInputDateTime(new Date()),
        tags: initialData?.tags ?? [],
        placeName: bingoContext?.placeName ?? initialData?.placeName ?? '',
        placeCity: '',
        placeLat: '',
        placeLng: '',
        placeCategory: bingoContext?.placeCategory ?? PLACE_CATEGORIES.OTRO,
    });

    const [memoryId, setMemoryId] = useState(initialData?.id ?? null);
    const [draftPhotos, setDraftPhotos] = useState(initialPhotos || []);
    const [foundDraft, setFoundDraft] = useState(null);
    const [isSaving, setIsSaving] = useState(false);
    const [isGeocoding, setIsGeocoding] = useState(false);
    const [isPlacePickerOpen, setIsPlacePickerOpen] = useState(false);
    const [selectedPlaceId, setSelectedPlaceId] = useState(initialData?.placeId ?? '');
    const [customLocation, setCustomLocation] = useState(null);
    const [error, setError] = useState(null);
    const [step, setStep] = useState(isPartner ? 'details' : 'unified'); 

    // Bingo Suggestions States
    const [bingoSuggestions, setBingoSuggestions] = useState([]);
    const [showBingoSheet, setShowBingoSheet] = useState(false);
    const { places } = usePlaces();
    const { availableTags } = useBingo();

    // drafts on mount
    useEffect(() => {
        if (!isEditing && isPartner) {
            getActiveDraft().then(draft => {
                if (draft) setFoundDraft(draft);
            });
        }
    }, [isEditing, isPartner, getActiveDraft]);

    // autosave draft
    useEffect(() => {
        if (!isEditing && isPartner && !foundDraft && (form.title || draftPhotos.length > 0 || form.description)) {
            const timer = setTimeout(() => {
                saveDraft(memoryId, form, draftPhotos).then(id => {
                    if (!memoryId) setMemoryId(id);
                });
            }, 500);
            return () => clearTimeout(timer);
        }
    }, [form, draftPhotos, memoryId, isEditing, isPartner, foundDraft, saveDraft]);

    function handleResume() {
        if (!foundDraft) return;
        setForm(foundDraft.data || form);
        setMemoryId(foundDraft.id);
        const photos = (foundDraft.photos || []).map(p => {
            const file = new File([p.file], p.name, { type: p.type });
            return file;
        });
        setDraftPhotos(photos);

        if (foundDraft.data?.placeId) {
            setSelectedPlaceId(foundDraft.data.placeId);
        } else if (foundDraft.data?.customLocation) {
            setCustomLocation(foundDraft.data.customLocation);
            setSelectedPlaceId('custom_map');
        }
        setFoundDraft(null);
    }

    async function handleDiscardDraft() {
        if (foundDraft) {
            await removePendingCita(foundDraft.id);
            setFoundDraft(null);
        }
    }

    // Auto-Geocode when coords change and name is empty
    useEffect(() => {
        if (form.placeLat && form.placeLng && !form.placeName && !isGeocoding) {
            const timer = setTimeout(async () => {
                setIsGeocoding(true);
                const result = await reverseGeocode(form.placeLat, form.placeLng);
                if (result && !form.placeName) {
                    setForm(f => ({
                        ...f,
                        placeName: result.name,
                        placeCity: result.city || f.placeCity
                    }));
                }
                setIsGeocoding(false);
            }, 800);
            return () => clearTimeout(timer);
        }
    }, [form.placeLat, form.placeLng, form.placeName, isGeocoding]);

    function toggleTag(tag) {
        setForm(f => ({
            ...f,
            tags: f.tags.includes(tag)
                ? f.tags.filter(t => t !== tag)
                : [...f.tags, tag],
        }));
    }

    async function handleSaveDetails(e) {
        if (e) e.preventDefault();
        setError(null);
        setIsSaving(true);

        if (draftPhotos?.length > 0) {
            try {
                const metadata = await extractMetadataFromFile(draftPhotos[0]);
                if (metadata) {
                    setForm(f => {
                        const updates = {};
                        if (metadata.lat && !f.placeLat) {
                            updates.placeLat = String(metadata.lat);
                            updates.placeLng = String(metadata.lng);
                        }
                        if (metadata.dateTime && !f.eventDate) {
                            updates.eventDate = toInputDateTime(metadata.dateTime);
                        }
                        if (Object.keys(updates).length === 0) return f;
                        return { ...f, ...updates };
                    });
                }
            } catch (err) {
                console.warn('[Metadata Extraction] Final check failed:', err);
            }
        }

        try {
            let finalPlaceId = initialData?.placeId ?? null;
            let finalPlaceName = form.placeName || null;

            if (selectedPlaceId && selectedPlaceId !== 'custom_map') {
                finalPlaceId = selectedPlaceId;
            } else if (customLocation || (form.placeLat && form.placeLng)) {
                const result = await findOrCreatePlace({
                    lat: customLocation?.lat || form.placeLat,
                    lng: customLocation?.lng || form.placeLng,
                    name: form.placeName,
                    city: form.placeCity,
                    category: form.placeCategory,
                    tags: form.tags,
                });
                finalPlaceId = result.placeId;
            }

            const memoryModel = Memory.fromForm({
                ...form,
                id: memoryId || initialData?.id,
                placeId: finalPlaceId,
                placeName: finalPlaceName,
            });

            const memoryPayload = {
                ...memoryModel.toApiPayload(),
                ...(bingoContext ? { bingoContext } : {}),
            };

            if (draftPhotos?.length > 0 && !isEditing) {
                await queueMemory(memoryPayload, draftPhotos);
                if (memoryId) await removePendingCita(memoryId);
                onSuccess?.();
                return;
            }

            if (isEditing) {
                await updateMemory({ memoryId: initialData.id, ...memoryPayload });
                setMemoryId(initialData.id);
            } else {
                const response = await createMemory(memoryPayload);
                setMemoryId(response.memoryId);

                // Handle Bingo Suggestions
                if (response.bingoSuggestions?.length > 0) {
                    setBingoSuggestions(response.bingoSuggestions);
                    setShowBingoSheet(true);
                    return; // Don't call onSuccess yet, wait for Modal
                }
            }

            if (!isEditing && isPartner) {
                setStep('photos');
            } else {
                onSuccess?.();
            }
        } catch (err) {
            setError('Error al guardar. Intenta de nuevo.');
            console.error(err);
        } finally {
            setIsSaving(false);
        }
    }

    async function handleBingoConfirm(selectedCategoryIds) {
        setIsSaving(true);
        try {
            await Promise.all(
                selectedCategoryIds.map(categoryId => 
                    completeBingoSquare({ 
                        categoryId, 
                        memoryId: memoryId 
                    })
                )
            );
        } catch (err) {
            console.error('[Bingo Link Error]', err);
        } finally {
            setIsSaving(false);
            setShowBingoSheet(false);
            onSuccess?.();
        }
    }



    return (
        <div className={styles.root}>
            <DraftRecoveryPrompt 
                foundDraft={foundDraft}
                onResume={handleResume}
                onDiscard={handleDiscardDraft}
            />

            <StepIndicator step={step} isPartner={isPartner} />

            {(step === 'details' || step === 'unified') && (
                <MemoryDetailsForm 
                    form={form}
                    setForm={setForm}
                    toggleTag={toggleTag}
                    isSaving={isSaving}
                    onCancel={onCancel}
                    isEditing={isEditing}
                    isPartner={isPartner}
                    onSave={handleSaveDetails}
                    availableTags={availableTags}
                    isGeocoding={isGeocoding}
                    selectedPlaceId={selectedPlaceId}
                    setIsPlacePickerOpen={setIsPlacePickerOpen}
                    isPlacePickerOpen={isPlacePickerOpen}
                    places={places}
                    error={error}
                    onSelectPlace={(placeId) => {
                        setSelectedPlaceId(placeId);
                        setCustomLocation(null);
                        const p = places.find(x => x.id === placeId);
                        if (p) {
                            setForm(f => ({ 
                                ...f, 
                                placeName: p.name,
                                placeCity: p.city || f.placeCity,
                                placeCategory: p.category || f.placeCategory
                            }));
                        }
                    }}
                    onLocationSelected={(loc, placeId, name) => {
                        if (placeId) {
                            setSelectedPlaceId(placeId);
                            setCustomLocation(null);
                            setForm(f => ({ ...f, placeName: name || f.placeName }));
                        } else {
                            setCustomLocation(loc);
                            setSelectedPlaceId('custom_map');
                            setForm(f => ({ 
                                ...f, 
                                placeName: name || f.placeName,
                                placeLat: String(loc.lat),
                                placeLng: String(loc.lng)
                            }));
                        }
                    }}
                />
            )}

            {(step === 'photos' || (step === 'unified' && !isEditing)) && (
                <MemoryPhotoSection 
                    isPartner={isPartner}
                    isEditing={isEditing}
                    memoryId={memoryId}
                    draftPhotos={draftPhotos}
                    step={step}
                    onPhotosChange={(newFiles) => {
                        const updatedPhotos = [...draftPhotos, ...newFiles];
                        setDraftPhotos(updatedPhotos);
                        if (isPartner && !isEditing) {
                            saveDraft(memoryId, form, updatedPhotos).then(id => {
                                if (!memoryId) setMemoryId(id);
                            });
                        }
                    }}
                    onDone={() => {
                        if (isPartner && step === 'photos') {
                            handleSaveDetails();
                        } else {
                            onSuccess();
                        }
                    }}
                    onMetadataDetected={(metadata) => {
                        if (!metadata) return;
                        setForm(f => {
                            const updates = {};
                            if (metadata.lat && !f.placeLat) {
                                updates.placeLat = String(metadata.lat);
                                updates.placeLng = String(metadata.lng);
                            }
                            if (metadata.dateTime) {
                                updates.eventDate = toInputDateTime(metadata.dateTime);
                            }
                            if (Object.keys(updates).length === 0) return f;
                            return { ...f, ...updates };
                        });
                    }}
                    onFinalSave={handleSaveDetails}
                />
            )}

            <BingoSuggestionSheet 
                isOpen={showBingoSheet}
                suggestions={bingoSuggestions}
                onConfirm={handleBingoConfirm}
                onCancel={async () => {
                    // Save to IndexedDB so badge appears on board even if sheet is dismissed
                    try {
                        const { openDB } = await import('../../config/dbConfig');
                        const db = await openDB();
                        const tx = db.transaction('pending_bingo', 'readwrite');
                        const store = tx.objectStore('pending_bingo');

                        // Use existing memoryId or generate UUID
                        const mid = memoryId || crypto.randomUUID();

                        store.put({
                            memoryId: mid,
                            suggestions: bingoSuggestions,
                            createdAt: Date.now(),
                            resolved: false,
                            dismissed: true
                        });

                        await new Promise((resolve, reject) => {
                            tx.oncomplete = () => resolve();
                            tx.onerror = () => reject(tx.error);
                        });
                        window.dispatchEvent(new Event('pending_bingo_updated'));
                    } catch (err) {
                        console.error('[MemoryForm] Error saving suggestions to IndexedDB:', err);
                    }

                    setShowBingoSheet(false);
                    onSuccess?.();
                }}
                isSaving={isSaving}
            />
        </div>
    );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { compressImage } from '../../services/storage';
import { autoDetectMetadata } from '../../utils/extractGpsFromFile';
import Button from '../../components/ui/Button/Button';
import styles from './PhotoUploader.module.css';
import { logToVercel } from '../../utils/vercelLogger';
import CameraPermissionGate from '../../components/ui/CameraPermissionGate/CameraPermissionGate';

export default function PhotoUploader({ 
    onDone, 
    onMetadataDetected, 
    onPhotosChange
}) {
    const { isPartner } = useAuth();
    const [uploads, setUploads] = useState([]);
    const [isProcessing, setIsProcessing] = useState(false);

    const fileInputRef = useRef(null);
    const cameraInputRef = useRef(null);
    const galleryInputRef = useRef(null);

    // Clean up URLs on unmount
    useEffect(() => {
        return () => {
            uploads.forEach(u => {
                if (u.previewUrl) URL.revokeObjectURL(u.previewUrl);
            });
        };
    }, [uploads]);

    const processFiles = useCallback(async (files) => {
        setIsProcessing(true);
        const processedFiles = [];

        for (const file of files) {
            const id = Math.random().toString(36).substring(7);
            
            // 1. Immediate Compression (RAM optimization)
            let compressedBlob;
            let previewUrl;
            let finalFile;

            try {
                compressedBlob = await compressImage(file);
                previewUrl = URL.createObjectURL(compressedBlob);
                finalFile = compressedBlob;
            } catch (err) {
                logToVercel('PhotoUploader', 'COMPRESS_ERROR', err.message);
                // Fallback to original file if compression fails
                previewUrl = URL.createObjectURL(file);
                finalFile = file;
            }
            
            const photoItem = {
                id,
                file: finalFile,
                previewUrl,
                originalName: file.name,
                status: 'ready'
            };

            processedFiles.push(photoItem);
            setUploads(prev => [...prev, photoItem]);

            // Metadata Detection (first file only)
            if (onMetadataDetected && processedFiles.length === 1) {
                // We use the original file for metadata because compression might strip EXIF
                autoDetectMetadata(file).then(metadata => {
                    if (metadata) onMetadataDetected(metadata);
                }).catch((err) => {
                    logToVercel('PhotoUploader', 'METADATA_ERROR', err.message);
                });
            }
        }

        // Notify parent to save in Draft
        if (onPhotosChange) {
            onPhotosChange(processedFiles.map(p => p.file));
        }

        setIsProcessing(false);
    }, [onMetadataDetected, onPhotosChange]);

    // Simplified: No auto-upload here. Parent (MemoryForm) handles final queuing.

    const onDrop = useCallback((e) => {
        e.preventDefault();
        const files = Array.from(e.dataTransfer?.files || []);
        if (files.length === 0) return;
        processFiles(files);
    }, [processFiles]);

    const handleFileChange = useCallback((e) => {
        const files = Array.from(e.target.files || []);
        logToVercel('PhotoUploader', 'INPUT_ONCHANGE', `Files length: ${files.length}`);
        e.target.value = '';
        if (files.length === 0) return;
        processFiles(files);
    }, [processFiles]);


    return (
        <div className={styles.root}>
            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center', marginBottom: '1rem' }}>
                <CameraPermissionGate onCancel={() => logToVercel('PhotoUploader', 'PERMISSION_CANCELLED', 'User closed permission gate')}>
                    <label
                        style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', padding: '10px 20px', backgroundColor: '#eef2f5', borderRadius: '8px', fontWeight: '500', border: 'none', overflow: 'hidden' }}
                        onClick={() => logToVercel('Photo_Label_Camera', 'CLICK', 'Label was clicked')}
                        onTouchStart={() => logToVercel('Photo_Label_Camera', 'TOUCHSTART', 'Label touch start')}
                        onTouchEnd={(e) => {
                            logToVercel('Photo_Label_Camera', 'TOUCHEND', 'Label touch end');
                            e.stopPropagation();
                        }}
                    >
                        <input
                            ref={cameraInputRef}
                            type="file"
                            multiple
                            accept="image/*"
                            capture="environment"
                            onChange={handleFileChange}
                            onClick={(e) => logToVercel('Photo_Input_Camera', 'CLICK', `Input clicked. Cancelable: ${e.cancelable}, isTrusted: ${e.isTrusted}`)}
                            onTouchStart={() => logToVercel('Photo_Input_Camera', 'TOUCHSTART', 'Direct tap on input began')}
                            onTouchEnd={() => logToVercel('Photo_Input_Camera', 'TOUCHEND', 'Direct tap on input ended')}
                            style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', opacity: 0, zIndex: 100, cursor: 'pointer', touchAction: 'manipulation' }}
                        />
                        <span className="material-symbols-outlined">add_a_photo</span>
                        Cámara
                    </label>
                </CameraPermissionGate>

                <label
                    style={{ 
                        position: 'relative', 
                        display: 'flex', 
                        alignItems: 'center', 
                        gap: '8px', 
                        cursor: uploads.length === 0 ? 'not-allowed' : 'pointer', 
                        padding: '10px 20px', 
                        backgroundColor: '#eef2f5', 
                        borderRadius: '8px', 
                        fontWeight: '500', 
                        border: 'none', 
                        overflow: 'hidden',
                        opacity: uploads.length === 0 ? 0.6 : 1
                    }}
                    onClick={() => {
                        if (uploads.length === 0) {
                            logToVercel('Photo_Label_Gallery', 'BLOCKED', 'Gallery blocked - first photo must be from camera');
                            return;
                        }
                        logToVercel('Photo_Label_Gallery', 'CLICK', 'Label was clicked');
                    }}
                    onTouchStart={() => {
                        if (uploads.length > 0) logToVercel('Photo_Label_Gallery', 'TOUCHSTART', 'Label touch start');
                    }}
                    onTouchEnd={(e) => {
                        if (uploads.length === 0) {
                            e.preventDefault();
                            return;
                        }
                        logToVercel('Photo_Label_Gallery', 'TOUCHEND', 'Label touch end');
                        e.stopPropagation();
                    }}
                >
                    <input
                        ref={galleryInputRef}
                        type="file"
                        multiple
                        disabled={uploads.length === 0}
                        accept="image/*"
                        onChange={handleFileChange}
                        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', opacity: 0, zIndex: 100, cursor: uploads.length === 0 ? 'not-allowed' : 'pointer', touchAction: 'manipulation' }}
                    />
                    <span className="material-symbols-outlined">photo_library</span>
                    Galería
                </label>
            </div>
            <div
                className={styles.dropzone}
                onDragOver={e => e.preventDefault()}
                onDrop={onDrop}
            >
                <input
                    ref={fileInputRef}
                    type="file"
                    multiple
                    accept="image/*"
                    onChange={handleFileChange}
                    id="file-input"
                    className={styles.hiddenInput}
                />
                <label htmlFor="file-input" className={styles.dropzoneLabel}>
                    <span className={styles.uploadIcon}>📸</span>
                    <p className={styles.dropTitle}>Suelta tus fotos aquí</p>
                    <p className={styles.dropSubtitle}>o haz clic para buscarlas</p>
                </label>
            </div>
            {uploads.length > 0 && (
                <div className={styles.previewGrid}>
                    {uploads.map(upload => (
                        <div key={upload.id} className={`${styles.previewItem} ${styles[upload.status]}`}>
                            <div className={styles.previewThumb}>
                                <img src={upload.previewUrl} alt="Preview" className={styles.thumbImage} />
                                <div className={styles.statusOverlay}>
                                    {upload.status === 'processing' && <span className={styles.spinner}></span>}
                                    {upload.status === 'ready' && <span>✅</span>}
                                    {upload.status === 'error' && <span>❌</span>}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
            <div className={styles.actions}>
                <Button variant="primary" size="lg" onClick={onDone} disabled={uploads.length === 0 || isProcessing}>
                    Siguiente
                </Button>
            </div>
        </div>
    );
}

