            handleUpdate('inviteConfig.inviteLink', inviteUrl);
            handleUpdate('inviteConfig.generatedAt', now);

            // 2. Persist automatically
            await updateConfig({ 
                inviteConfig: { 
                    inviteLink: inviteUrl, 
                    generatedAt: now 
                } 
            });

            toast.success('¡Enlace generado!', 'Link generado y guardado ✓');
        } catch (err) {
