import { useEffect, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '../../../services/firebase';
import { useAppConfig } from '../../../context/AppConfigContext';
import styles from './SnapshotOverlay.module.css';

/**
 * SnapshotOverlay — Shows a queue of unseen snapshots one at a time.
 *
 * Visual deck: max 3 visible at once.
 * - Slot 0 (front/active): centered, full size, timer running.
 * - Slot 1 (behind 1):     slightly smaller, shifted up-right.
 * - Slot 2 (behind 2):     even smaller, shifted further up-right.
 *
 * When the timer fires → active is marked as seen, deck shifts forward.
 *
 * @param {Array}    snapshots - Array of snapshot objects (unseen, ordered oldest→newest)
 * @param {Function} onClose   - Called when all snapshots have been viewed or closed manually
 */

/* How many cards to show in the deck (front + background cards) */
const DECK_VISIBLE = 3;

/* Offset per background slot (px). Each slot shifts further up-right. */
const SLOT_OFFSET_X = 22;   // px right per slot
const SLOT_OFFSET_Y = -18;  // px up per slot
const SLOT_SCALE   = 0.07;  // scale reduction per slot

export default function SnapshotOverlay({ snapshots = [], onClose }) {
    const { snapshotConfig } = useAppConfig();
    const timerSeconds = snapshotConfig?.timerSeconds ?? 9;

    const [currentIndex, setCurrentIndex] = useState(0);
    const [progress, setProgress] = useState(0);

    const totalCount = snapshots.length;
    const currentSnapshot = snapshots[currentIndex];
    const isLast = currentIndex >= totalCount - 1;

    /* ─── mark-seen + advance ─── */
    const markAsSeenAndAdvance = useCallback(async () => {
        if (!currentSnapshot) return;

        try {
            const snapshotRef = doc(db, 'instantaneas', currentSnapshot.id);
            await updateDoc(snapshotRef, {
                isSeen: true,
                seenAt: serverTimestamp(),
            });
        } catch (err) {
            console.error('Error marking snapshot as seen:', err);
        }

        if (isLast) {
            onClose();
        } else {
            setCurrentIndex(prev => prev + 1);
            setProgress(0);
        }
    }, [currentSnapshot, isLast, onClose]);

    /* ─── close immediately ─── */
    const handleClose = () => {
        if (currentSnapshot) {
            const snapshotRef = doc(db, 'instantaneas', currentSnapshot.id);
            updateDoc(snapshotRef, {
                isSeen: true,
                seenAt: serverTimestamp(),
            }).catch(() => { });
        }
        onClose();
    };

    /* ─── progress animation ─── */
    useEffect(() => {
        let start = null;
        let raf;
        const duration = timerSeconds * 1000;

        const step = (ts) => {
            if (!start) start = ts;
            const elapsed = ts - start;
            const pct = Math.min(elapsed / duration, 1);
            setProgress(pct);
            if (pct < 1) {
                raf = requestAnimationFrame(step);
            }
        };

        raf = requestAnimationFrame(step);
        return () => cancelAnimationFrame(raf);
    }, [timerSeconds, currentIndex]);

    /* ─── auto-advance timeout ─── */
    useEffect(() => {
        const timeout = setTimeout(() => {
            markAsSeenAndAdvance();
        }, timerSeconds * 1000);
        return () => clearTimeout(timeout);
    }, [timerSeconds, currentIndex, markAsSeenAndAdvance]);

    if (!currentSnapshot) return null;

    /* ─── build the visible deck ─── */
    const deckSlots = [];
    for (let slot = 0; slot < DECK_VISIBLE; slot++) {
        const snapIdx = currentIndex + slot;
        if (snapIdx < totalCount) {
            deckSlots.push({ slot, snap: snapshots[snapIdx] });
        }
    }
    const deckSlotsReversed = [...deckSlots].reverse();
    const squirclePath = "M0.5,0 C0.42,0 0,0.42 0,0.5 C0,0.58 0.42,1 0.5,1 C0.58,1 1,0.58 1,0.5 C1,0.42 0.58,0 0.5,0 Z";

    return (
        <motion.div
            className={styles.overlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
        >
            {totalCount > 1 && (
                <div className={styles.counter}>
                    {currentIndex + 1} de {totalCount}
                </div>
            )}

            <button className={styles.closeBtn} onClick={handleClose}>✕</button>

            <svg height="0" width="0" style={{ position: 'absolute' }}>
                <defs>
                    <clipPath clipPathUnits="objectBoundingBox" id="pillowClip">
                        <path d={squirclePath} transform="rotate(45 0.5 0.5)" />
                    </clipPath>
                </defs>
            </svg>

            <div className={styles.stage}>
                <AnimatePresence mode="popLayout">
                    {deckSlotsReversed.map(({ slot, snap }) => {
                        const isActive = slot === 0;
                        const tx = slot * SLOT_OFFSET_X;
                        const ty = slot * SLOT_OFFSET_Y;
                        const sc = 1 - slot * SLOT_SCALE;
                        const zIndex = DECK_VISIBLE - slot;
                        const opacity = 1 - slot * 0.12;

                        return (
                            <motion.div
                                key={snap.id}
                                className={styles.cardSlot}
                                style={{ zIndex }}
                                onClick={isActive ? markAsSeenAndAdvance : undefined}
                                initial={{ x: tx, y: ty, scale: sc, opacity: 0 }}
                                animate={{ x: tx, y: ty, scale: sc, opacity }}
                                exit={{ x: tx - 40, y: ty + 40, scale: sc * 0.8, opacity: 0 }}
                                transition={{ type: 'spring', stiffness: 300, damping: 25 }}
                            >
                                <div className={styles.photoWrapper}>
                                    <img src={snap.photoUrl} alt="" className={styles.photo} />
                                    {isActive && snap.message && (
                                        <div className={styles.messageOverlay}>
                                            <p className={styles.messageText}>{snap.message}</p>
                                        </div>
                                    )}
                                </div>

                                {isActive && (
                                    <svg className={styles.progressRingSvg} viewBox="0 0 1 1">
                                        <path d={squirclePath} className={styles.timerTrack} transform="rotate(45 0.5 0.5)" />
                                        <path d={squirclePath} className={styles.timerFill} transform="rotate(45 0.5 0.5)" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - progress} />
                                    </svg>
                                )}
                            </motion.div>
                        );
                    })}
                </AnimatePresence>
            </div>
        </motion.div>
    );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useAuth } from '../../hooks/useAuth';
import { useAppConfig } from '../../hooks/useAppConfig';
// eslint-disable-next-line no-unused-vars
import { motion, AnimatePresence } from 'framer-motion';
import UserCapsules from '../capsules/UserCapsules';
import UserCoupons from '../coupons/UserCoupons';
import UserBingo from '../bingo/UserBingo';
import MapView from '../map/MapView';
import GalleryView from '../gallery/GalleryView';
import BottomNav from '../../components/ui/BottomNav/BottomNav';
import SnapshotOverlay from '../snapshots/components/SnapshotOverlay';
import SnapshotCreator from '../snapshots/components/SnapshotCreator';
import SnapshotHistory from '../snapshots/components/SnapshotHistory';
import CitaOverlay from '../../components/Cita/CitaOverlay';
import SnapshotButton from '../snapshots/components/SnapshotButton';
import styles from './UserDashboard.module.css';

import { TABS } from '../../data/dashboardData';
import { usePendingCitas } from '../../hooks/usePendingCitas';
import Memory from '../../models/Memory';
import { useOfflineQueue } from '../../hooks/useOfflineQueue';
import { usePendingBingo } from '../../hooks/usePendingBingo';
import { useBingo } from '../../hooks/useBingo';
import BingoSuggestionSheet from '../memories/components/BingoSuggestionSheet';
import PhotoViewer from '../../components/ui/PhotoViewer/PhotoViewer';
import PendingDatesList from '../../components/PendingDates/PendingDatesList';
import PendingDateForm from '../../components/PendingDates/PendingDateForm';
import { usePlaces } from '../map/hooks/usePlaces';
import { toast } from '../../components/ui/PastelToast/PastelToast';
import CelebrationOverlay from '../../components/Bingo/CelebrationOverlay';
import LaLaLandIris from '../../components/Bingo/LaLaLandIris';

export default function UserDashboard() {
    const { isPartner, isAdmin } = useAuth();
    const { isFeatureOn } = useAppConfig();
    const { pendingCount, pendingCitas, removePendingCita, addPendingCita, updatePendingCitaStatus, updatePendingCita, restorePendingCita } = usePendingCitas();
    const { pendingSuggestions, resolvePendingSuggestion, dismissSuggestion } = usePendingBingo();
    const { completeBingoSquare, markBatchComplete, celebrationEvent, clearCelebrationEvent, irisEvent, resetBingoBoard } = useBingo();
    const firstPendingSuggestion = pendingSuggestions.find(s => !s.dismissed);

    // Map tab IDs to feature flags
    const TAB_FLAGS = {
        lugares: 'memoryMap',
        galeria: 'photoGallery',
        sorpresas: 'timeCapsules',
        caprichos: 'coupons',
        bingo: 'bingoBoard',
        ejercicio: 'exercise',
        movies: 'movieTracking',
        juegos: 'games'
    };

    // Filter TABS based on dynamic feature flags
    const filteredTabs = TABS.filter(tab => {
        const flag = TAB_FLAGS[tab.id];
        // If it has a flag, it must be ON to be shown
        return flag ? isFeatureOn(flag) : true;
    });

    const mainTabs = filteredTabs.filter(t => !t.inMore);
    const moreTabs = filteredTabs.filter(t => t.inMore);

    const [activeTab, setActiveTab] = useState('lugares');
    const [prevTab, setPrevTab] = useState('lugares');
    const [isPlaceSelected, setIsPlaceSelected] = useState(false);
    const [bingoContextToMap, setBingoContextToMap] = useState(null);
    const [isBingoModalOpen, setIsBingoModalOpen] = useState(false);
    const [isCouponsModalOpen, setIsCouponsModalOpen] = useState(false);
    const [openPendingSignal, setOpenPendingSignal] = useState(false);
    const [isSnapshotOpen, setIsSnapshotOpen] = useState(false);
    const [isHistoryOpen, setIsHistoryOpen] = useState(false);
    const [activeSnapshots, setActiveSnapshots] = useState([]);
    const [isCameraOpen, setIsCameraOpen] = useState(false);
    const { queueMemory } = useOfflineQueue();
    const { places } = usePlaces();
    const [citaContext, setCitaContext] = useState(null);
    const [selectedPendingDate, setSelectedPendingDate] = useState(null);
    const [viewerPhotos, setViewerPhotos] = useState(null);
    const [isPendingListOpen, setIsPendingListOpen] = useState(false);
    const [sheetDismissed, setSheetDismissed] = useState(false);


    // Dynamic check for ANY overlay that should hide the map
    // We EXCLUDE isPlaceSelected because that modal (PlaceDetailDrawer) lives INSIDE MapView
    const hasAnyOverlayOpen = !!citaContext || isBingoModalOpen || isCouponsModalOpen || isSnapshotOpen || isCameraOpen || isHistoryOpen || isPendingListOpen || !!selectedPendingDate || !!viewerPhotos || (!!firstPendingSuggestion && !sheetDismissed) || !!celebrationEvent;

    // Check specifically for nav hiding (includes map selection)
    const shouldHideNav = hasAnyOverlayOpen;

    
    // Check for map rendering (should NOT hide when a place is selected)
    const shouldShowMap = activeTab === 'lugares' && (!hasAnyOverlayOpen || isPlaceSelected);

    // Partículas solo cuando NO es el mapa
    useEffect(() => {
        if (activeTab === 'lugares') return;

        const createParticle = () => {
            const particle = document.createElement('div');
            particle.className = styles.particle;
            const size = Math.random() * 8 + 4;
            const left = Math.random() * 100;
            const duration = Math.random() * 20 + 20;
            const delay = Math.random() * 5;
            particle.style.width = `${size}px`;
            particle.style.height = `${size}px`;
            particle.style.left = `${left}%`;
            particle.style.animationDuration = `${duration}s`;
            particle.style.animationDelay = `-${delay}s`;
            const container = document.getElementById('user-dashboard-bg');
            if (container) container.appendChild(particle);
            setTimeout(() => particle.remove(), duration * 1000);
        };

        const interval = setInterval(createParticle, 800);
        return () => clearInterval(interval);
    }, [activeTab]);

    const handleTabChange = (newTab) => {
        if (newTab === activeTab) {
            // Si ya estamos en lugares y hay citas pendientes, mandamos señal para abrir lista
            if (newTab === 'lugares' && pendingCount > 0) {
                setIsPendingListOpen(true);
            }
            return;
        }
        setPrevTab(activeTab);
        setActiveTab(newTab);
        // Reset modals when changing tabs
        setIsCouponsModalOpen(false);
    };

    // Reset indicator when a NEW pending suggestion arrives
    useEffect(() => {
        if (firstPendingSuggestion) {
            setSheetDismissed(false);
        }
    }, [firstPendingSuggestion?.memoryId]);


    // Al completar el tablero, forzar cambio a pestaña de Bingo para ver la animación
    useEffect(() => {
        if (celebrationEvent?.isFullBoard && activeTab !== 'bingo') {
            console.log('[Dashboard] Full board detected! Switching to Bingo tab.');
            setActiveTab('bingo');
        }
    }, [celebrationEvent?.isFullBoard, activeTab]);

    // Calcular dirección para la animación
    const getDirection = () => {
        if (activeTab === 'lugares' || prevTab === 'lugares') return 0;
        const prevIndex = TABS.findIndex(t => t.id === prevTab);
        const nextIndex = TABS.findIndex(t => t.id === activeTab);
        return nextIndex > prevIndex ? 1 : -1;
    };

    const direction = getDirection();

    const variants = {
        initial: (dir) => ({
            x: dir * 40,
            opacity: 0
        }),
        animate: {
            x: 0,
            opacity: 1
        },
        exit: (dir) => ({
            x: dir * -40,
            opacity: 0
        })
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'galeria': return <GalleryView />;
            case 'sorpresas': return <UserCapsules />;
            case 'caprichos': return <UserCoupons onModalStateChange={setIsCouponsModalOpen} />;
            case 'bingo': return (
                <UserBingo
                    setActiveTab={setActiveTab}
                    setBingoContextToMap={setBingoContextToMap}
                    setIsModalOpen={setIsBingoModalOpen}
                />
            );
            case 'ejercicio': return (
                <div className={styles.placeholderModule}>
                    <h1>Ejercicio</h1>
                    <p>¡Tus rachas se están sincronizando! 🔥</p>
                    <button onClick={() => setActiveTab('lugares')}>Volver al inicio</button>
                </div>
            );
            case 'movies': return (
                <div className={styles.placeholderModule}>
                    <h1>Películas</h1>
                    <p>Prepara las palomitas... 🍿</p>
                    <button onClick={() => setActiveTab('lugares')}>Volver al inicio</button>
                </div>
            );
            case 'juegos': return (
                <div className={styles.placeholderModule}>
                    <h1>Secretos y Juegos</h1>
                    <p>Prepara tus habilidades... 🎮</p>
                    <button onClick={() => setActiveTab('lugares')}>Volver al inicio</button>
                </div>
            );
            default: return null;
        }
    };

    const handleAutoSavePendingDate = async (data) => {
        if (!updatePendingCita || !data.id) return;
        try {
            await updatePendingCita(data.id, {
                title: data.title,
                eventDate: data.eventDate,
                tags: data.tags,
                comments: data.comments,
                placeId: data.placeId,
                placeName: data.placeName,
                coordinates: data.customLocation // Save raw coordinates for potential recovery
            });
        } catch (err) {
            console.warn('[UserDashboard] Auto-save failed:', err);
        }
    };

    const handleSavePendingDate = async (data) => {
        try {
            const memory = Memory.fromForm(data);
            const payload = memory.toApiPayload();

            if (updatePendingCita && data.id) {
                // Persistent save of ALL form fields in IndexedDB before/during upload
                await updatePendingCita(data.id, {
                    title: memory.title,
                    tags: memory.tags,
                    suggestedTags: memory.tags, // Keep for backward compatibility
                    description: memory.description,
                    comments: memory.description, // Keep for backward compatibility
                    eventDate: memory.eventDate,
                    placeId: memory.placeId,
                    placeName: memory.placeName,
                    coordinates: data.customLocation,
                    status: 'uploading'
                });
            }

            const files = (data.photos || []).map(p => p.file);

            if (files.length > 0) {
                await queueMemory(payload, files, data.id, data.bingoOrigin);
            }
            setSelectedPendingDate(null);
            if (pendingCitas.length > 1) {
                setIsPendingListOpen(true);
            }
            toast.success('¡Cita guardada! 💾', 'Se está subiendo ✨');
        } catch (err) {
            console.error('[UserDashboard] Error saving:', err);
            toast.error('Error al guardar');
        }
    };

    return (
        <div className={styles.appContainer}>

            {/* ── MAPA ── */}
            {shouldShowMap && (
                <div className={styles.mapWrapper}>
                    <MapView
                        onPlaceSelected={setIsPlaceSelected}
                        bingoContextToMap={bingoContextToMap}
                        clearBingoContext={() => setBingoContextToMap(null)}
                        onOpenSnapshot={(snapshotsArray) => {
                            setActiveSnapshots(snapshotsArray);
                            setIsSnapshotOpen(true);
                        }}
                        onOpenCamera={() => setIsCameraOpen(true)}
                        citaContext={citaContext}
                        onCitaContextChange={setCitaContext}
                        onOpenPending={() => setIsPendingListOpen(true)}
                        onOpenPhotoViewer={setViewerPhotos}
                    />
                </div>
            )}

            {/* ── OTROS TABS: con fondo decorativo y padding normal ── */}
            {activeTab !== 'lugares' && (
                <>
                    <div id="user-dashboard-bg" className={styles.background}>
                        <div className={styles.gradientOrb1} />
                        <div className={styles.gradientOrb2} />
                        <div className={styles.dotPattern} />
                    </div>

                    <main className={`${styles.mainContent} ${activeTab === 'bingo' ? styles.mainContentBingo : ''}`}>
                        <AnimatePresence mode="wait" custom={direction}>
                            <motion.div
                                key={activeTab}
                                custom={direction}
                                variants={variants}
                                initial="initial"
                                animate="animate"
                                exit="exit"
                                transition={{ type: 'spring', damping: 28, stiffness: 280 }}
                                className={styles.tabContentWrapper}
                            >
                                {renderContent()}
                            </motion.div>
                        </AnimatePresence>
                    </main>

                </>
            )}

            {/* ── NAVBAR: siempre flotando encima de todo ── */}
            <AnimatePresence>
                {!hasAnyOverlayOpen && (
                    <motion.div
                        initial={{ y: 100, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        exit={{ y: 100, opacity: 0 }}
                        transition={{ type: 'spring', stiffness: 260, damping: 20 }}
                    >
                        <BottomNav
                            activeTab={activeTab}
                            setActiveTab={handleTabChange}
                            tabs={mainTabs}
                            moreTabs={moreTabs}
                            pendingCount={pendingCount}
                            pendingBingoCount={pendingSuggestions.length}
                        />
                    </motion.div>
                )}
            </AnimatePresence>

            {/* ── Persist Camera FAB across specific views ── */}
            {/* ── Global Snapshot FAB removido por petición (Solo se ve en Mapa) ── */}

            <AnimatePresence>
                {isSnapshotOpen && activeSnapshots.length > 0 && (
                    <SnapshotOverlay
                        key="snapshot-overlay"
                        snapshots={activeSnapshots}
                        onClose={() => {
                            setIsSnapshotOpen(false);
                            setActiveSnapshots([]);
                        }}
                    />
                )}
            </AnimatePresence>

            {isCameraOpen && (
                <SnapshotCreator 
                    onClose={() => setIsCameraOpen(false)} 
                    onOpenOwnSnapshots={(ownSnaps) => {
                        setActiveSnapshots(ownSnaps);
                        setIsHistoryOpen(true);
                        setIsCameraOpen(false);
                    }}
                />
            )}

            <AnimatePresence>
                {isHistoryOpen && (
                    <SnapshotHistory 
                        snapshots={activeSnapshots}
                        onClose={() => {
                            setIsHistoryOpen(false);
                            setActiveSnapshots([]);
                            setIsCameraOpen(true); // Return to camera section
                        }}
                    />
                )}
            </AnimatePresence>

            {citaContext && (
                <CitaOverlay
                    citaContext={citaContext}
                    onClose={() => {
                        setCitaContext(null);
                        setIsPlaceSelected(false);
                    }}
                    onSave={async (files) => {
                        await addPendingCita(files, citaContext);
                        setCitaContext(null);
                        setIsPlaceSelected(false);
                    }}
                />
            )}

            <AnimatePresence>
                {isPendingListOpen && (
                    <PendingDatesList
                        pendingDates={pendingCitas}
                        onClose={() => setIsPendingListOpen(false)}
                        onSelectDate={(date) => {
                            setSelectedPendingDate(date);
                            setIsPendingListOpen(false);
                        }}
                        onRemove={removePendingCita}
                        onRestore={restorePendingCita}
                    />
                )}
                {selectedPendingDate && (
                    <PendingDateForm
                        pendingDate={selectedPendingDate}
                        onClose={() => {
                            setSelectedPendingDate(null);
                            setIsPendingListOpen(true);
                        }}
                        onSave={handleSavePendingDate}
                        onAutoSave={handleAutoSavePendingDate}
                        defaultPlaces={places}
                    />
                )}
            </AnimatePresence>

            {viewerPhotos && (
                <PhotoViewer
                    photos={viewerPhotos}
                    onClose={() => setViewerPhotos(null)}
                />
            )}

            <BingoSuggestionSheet 
                isOpen={!!firstPendingSuggestion && !sheetDismissed}
                suggestions={firstPendingSuggestion?.suggestions || []}
                onConfirm={async (selectedIds) => {
                    if (!firstPendingSuggestion) return;
                    
                    // 1. Cerrar visualmente de inmediato
                    setSheetDismissed(true);

                    // 2. Ejecutar lógica de bingo en batch (dispara celebración única)
                    if (markBatchComplete) {
                        markBatchComplete(selectedIds, firstPendingSuggestion.memoryId);
                    } else {
                        for (const id of selectedIds) {
                            completeBingoSquare(id, firstPendingSuggestion.memoryId);
                        }
                    }
                    
                    // 3. Resolver sugerencia en background (sin await bloqueante)
                    resolvePendingSuggestion(firstPendingSuggestion.memoryId);
                }}
                onCancel={async () => {
                    if (!firstPendingSuggestion) return;
                    
                    // 1. NO resolve immediately. Instead, dismiss to hide sheet but keep badge.
                    // 2. Ensure it's in pending_bingo (IndexedDB) with resolved: false
                    try {
                        const { openDB } = await import('../../config/dbConfig');
                        const db = await openDB();
                        const tx = db.transaction('pending_bingo', 'readwrite');
                        const store = tx.objectStore('pending_bingo');
                        
                        // Use existing memoryId or fallback to UUID if missing
                        const memoryId = firstPendingSuggestion.memoryId || crypto.randomUUID();
                        
                        store.put({
                            ...firstPendingSuggestion,
                            memoryId,
                            resolved: false,
                            dismissed: true, // Specific flag to hide from sheet
                            createdAt: firstPendingSuggestion.createdAt || Date.now()
                        });
                        
                        await new Promise((resolve, reject) => {
                            tx.oncomplete = () => resolve();
                            tx.onerror = () => reject(tx.error);
                        });
                    } catch (err) {
                        console.error('[BingoSuggestion] Error saving to IndexedDB:', err);
                    }

                    // 3. Update local state via hook
                    dismissSuggestion(firstPendingSuggestion.memoryId);
                }}
            />

            {celebrationEvent && (
                <CelebrationOverlay 
                    tierLabel={celebrationEvent.tierLabel}
                    reward={celebrationEvent.reward}
                    coins={celebrationEvent.totalCoins} /* Total display */
                    isCombo={celebrationEvent.isCombo}
                    achievements={celebrationEvent.achievements}
                    totalCoins={celebrationEvent.totalCoins}
                    isFullBoard={celebrationEvent.isFullBoard}
                    onComplete={() => {
                        if (celebrationEvent.isFullBoard) {
                            // First phase complete, reset board after transition
                            resetBingoBoard();
                        }
                        clearCelebrationEvent();
                    }}
                />
            )}

            {/* Global Easter Egg Transition (Top of everything) */}
            <AnimatePresence>
                {irisEvent && <LaLaLandIris key="la-la-land-iris" />}
            </AnimatePresence>
        </div>
    );
}

import {
    signInWithEmailAndPassword,
    signOut as firebaseSignOut,
} from 'firebase/auth';
import { doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { auth, db, functions } from './firebase';
import { COLLECTIONS } from '../config/constants';

// ─────────────────────────────────────────────────────────────────────────────
// Device Fingerprint
// ─────────────────────────────────────────────────────────────────────────────

const DEVICE_FINGERPRINT_KEY = 'capsule_device_id';

/**
 * Get (or lazily create) a stable device fingerprint stored in localStorage.
 * This persists across browser sessions and is only cleared if the user
 * manually clears site data.
 * @returns {string} UUID v4
 */
export function generateDeviceFingerprint() {
    let fingerprint = localStorage.getItem(DEVICE_FINGERPRINT_KEY);
    if (!fingerprint) {
        fingerprint = crypto.randomUUID();
        localStorage.setItem(DEVICE_FINGERPRINT_KEY, fingerprint);
    }
    return fingerprint;
}

/**
 * Get the stored device fingerprint without creating one.
 * @returns {string|null}
 */
export function getStoredDeviceFingerprint() {
    return localStorage.getItem(DEVICE_FINGERPRINT_KEY);
}

// ─────────────────────────────────────────────────────────────────────────────
// Admin Auth
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Sign in as admin using email/password.
 * @param {string} email
 * @param {string} password
 * @returns {Promise<import('firebase/auth').UserCredential>}
 */
export async function signInAsAdmin(email, password) {
    return signInWithEmailAndPassword(auth, email, password);
}

// ─────────────────────────────────────────────────────────────────────────────
// Partner Auth (Custom Token flow)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Exchange an invite token for a Firebase Custom Token.
 * Calls the `exchangeInviteToken` Cloud Function (HTTPS Callable).
 *
 * NOTE: This stub will work once Cloud Functions are deployed.
 * During local development without Functions, use the mock below.
 *
 * @param {string} inviteToken - The UUID from the invite URL (?t=...)
 * @param {string} deviceFingerprint - The device UUID from localStorage
 * @returns {Promise<{ customToken: string, userId: string }>}
 */
export async function exchangeInviteToken(inviteToken, deviceFingerprint) {
    const exchange = httpsCallable(functions, 'exchangeInviteToken');
    const result = await exchange({ token: inviteToken, deviceFingerprint });
    return result.data;
}

// ─────────────────────────────────────────────────────────────────────────────
// Token Claims
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Get the current user's custom claims from their ID token.
 * Forces a refresh to ensure claims are up-to-date.
 *
 * @param {boolean} [forceRefresh=false]
 * @returns {Promise<{ role: string|null, deviceId: string|null }>}
 */
export async function getCurrentUserClaims(forceRefresh = false) {
    const currentUser = auth.currentUser;
    if (!currentUser) return { role: null, deviceId: null };

    const tokenResult = await currentUser.getIdTokenResult(forceRefresh);
    return {
        role: tokenResult.claims.role ?? null,
        deviceId: tokenResult.claims.deviceId ?? null,
    };
}

// ─────────────────────────────────────────────────────────────────────────────
// Session Management
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Update the user's lastActiveAt timestamp in Firestore.
 * Called on every session start. Fails silently (non-critical).
 * @param {string} userId
 */
export async function updateLastActiveAt(userId) {
    try {
        const userRef = doc(db, COLLECTIONS.USERS, userId);
        await updateDoc(userRef, {
            lastActiveAt: serverTimestamp(),
        });
    } catch {
        // Non-critical — ignore failures (e.g. offline)
    }
}

/**
 * Sign out the current user (works for both admin and partner).
 * @returns {Promise<void>}
 */
export async function signOut() {
    return firebaseSignOut(auth);
}

import { openDB } from '../config/dbConfig';

const APP_CACHE_STORE = 'app_cache';
const THUMBNAILS_STORE = 'place_thumbnails';
const MAP_CONFIG_KEY = 'capsule_mapConfig';
const THUMBNAIL_EXPIRATION_DAYS = 7;
const MAX_THUMBNAILS = 100;

/**
 * Get map configuration from IndexedDB
 */
export async function getMapConfigCache() {
    try {
        const db = await openDB();
        return new Promise((resolve) => {
            const tx = db.transaction(APP_CACHE_STORE, 'readonly');
            const store = tx.objectStore(APP_CACHE_STORE);
            const request = store.get(MAP_CONFIG_KEY);
            request.onsuccess = () => resolve(request.result?.data || null);
            request.onerror = () => resolve(null);
        });
    } catch (err) {
        console.error('[offlineCache] Error getting mapConfig:', err);
        return null;
    }
}

/**
 * Save map configuration to IndexedDB
 */
export async function setMapConfigCache(config) {
    try {
        const db = await openDB();
        const tx = db.transaction(APP_CACHE_STORE, 'readwrite');
        const store = tx.objectStore(APP_CACHE_STORE);
        store.put({
            key: MAP_CONFIG_KEY,
            data: config,
            updatedAt: Date.now()
        });
        return true;
    } catch (err) {
        console.error('[offlineCache] Error saving mapConfig:', err);
        return false;
    }
}

/**
 * Get a cached thumbnail for a place as a Blob URL
 */
export async function getThumbnail(placeId) {
    try {
        const db = await openDB();
        const item = await new Promise((resolve) => {
            const tx = db.transaction(THUMBNAILS_STORE, 'readonly');
            const store = tx.objectStore(THUMBNAILS_STORE);
            const request = store.get(placeId);
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => resolve(null);
        });

        if (!item) return null;

        // Check expiration (7 days)
        const now = Date.now();
        const isExpired = (now - item.cachedAt) > (THUMBNAIL_EXPIRATION_DAYS * 24 * 60 * 60 * 1000);

        if (isExpired) {
            console.warn(`[offlineCache] Thumbnail for ${placeId} expired.`);
            return null;
        }

        // Convert Blob to URL
        return URL.createObjectURL(item.blob);
    } catch (err) {
        console.error('[offlineCache] Error getting thumbnail:', err);
        return null;
    }
}

/**
 * Save a thumbnail to the cache
 */
export async function cacheThumbnail(placeId, blob) {
    try {
        const db = await openDB();

        // Before adding, maybe clean up if full (simple LRU by count)
        await cleanOldThumbnails(db);

        const tx = db.transaction(THUMBNAILS_STORE, 'readwrite');
        const store = tx.objectStore(THUMBNAILS_STORE);
        store.put({
            placeId,
            blob,
            cachedAt: Date.now()
        });
        return true;
    } catch (err) {
        console.error('[offlineCache] Error caching thumbnail:', err);
        return false;
    }
}

/**
 * High-level helper for usePlaces or other components.
 * Fetches URL and caches it.
 */
export async function cachePlaceThumbnail(placeId, url) {
    if (!url || typeof url !== 'string' || url.startsWith('blob:') || url.startsWith('data:')) return;

    try {
        // Only fetch if not already in cache (or if expired)
        const db = await openDB();
        const existing = await new Promise(resolve => {
            const tx = db.transaction(THUMBNAILS_STORE, 'readonly');
            const req = tx.objectStore(THUMBNAILS_STORE).get(placeId);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => resolve(null);
        });

        if (existing) {
            const now = Date.now();
            const isFresh = (now - existing.cachedAt) < (THUMBNAIL_EXPIRATION_DAYS * 24 * 60 * 60 * 1000);
            if (isFresh) return;
        }

        const res = await fetch(url, { mode: 'cors' });
        if (!res.ok) return;
        const blob = await res.blob();
        await cacheThumbnail(placeId, blob);
    } catch (err) {
        // Silent fail for background caching
    }
}

/**
 * Simple cleanup of old or excessive thumbnails
 */
async function cleanOldThumbnails(dbInstance) {
// ... existing code ...
    const db = dbInstance || await openDB();
    const tx = db.transaction(THUMBNAILS_STORE, 'readwrite');
    const store = tx.objectStore(THUMBNAILS_STORE);
    const index = store.index('cachedAt');

    return new Promise((resolve) => {
        const countRequest = store.count();
        countRequest.onsuccess = () => {
            if (countRequest.result < MAX_THUMBNAILS) {
                resolve();
                return;
            }

            // If over limit, delete the oldest 10%
            const toDelete = Math.ceil(MAX_THUMBNAILS * 0.1);
            let deletedCount = 0;
            const cursorRequest = index.openCursor();
            cursorRequest.onsuccess = (e) => {
                const cursor = e.target.result;
                if (cursor && deletedCount < toDelete) {
                    cursor.delete();
                    deletedCount++;
                    cursor.continue();
                } else {
                    resolve();
                }
            };
        };
        countRequest.onerror = () => resolve();
    });
}

